@st.cache_resource
def get_engine():
    try:
        db = st.secrets["connections"]["supabase"]
        conn_str = (
            f"postgresql+psycopg2://{db['user']}:{db['password']}"
            f"@{db['host']}:{db['port']}/{db['database']}?sslmode=require"
        )
        return create_engine(
            conn_str,
            pool_pre_ping=True,
            pool_recycle=180,
            pool_timeout=10,
            pool_size=3,
            max_overflow=5,
            connect_args={
                "options":              "-c statement_timeout=30000",
                "connect_timeout":      8,
                "keepalives":           1,
                "keepalives_idle":      30,
                "keepalives_interval":  10,
                "keepalives_count":     3,
            }
        )
    except Exception as e:
        st.error(f"❌ Error de conexión: {e}")
        return None


@st.cache_resource
def _init_db():
    """Crea índices críticos una sola vez al arrancar la app."""
    engine = get_engine()
    if engine is None:
        return
    indices = [
        "CREATE INDEX IF NOT EXISTS idx_ventas_fecha       ON ventas(fecha_venta)",
        "CREATE INDEX IF NOT EXISTS idx_ventas_local       ON ventas(local)",
        "CREATE INDEX IF NOT EXISTS idx_ventas_fecha_local ON ventas(fecha_venta, local)",
        "CREATE INDEX IF NOT EXISTS idx_ventas_sku         ON ventas(sku_producto)",
        "CREATE INDEX IF NOT EXISTS idx_compras_fecha      ON compras(fecha_dte)",
        "CREATE INDEX IF NOT EXISTS idx_compras_local      ON compras(local)",
        "CREATE INDEX IF NOT EXISTS idx_compras_sku        ON compras(sku)",
        "CREATE INDEX IF NOT EXISTS idx_compras_rut        ON compras(rut_proveedor)",
        "CREATE INDEX IF NOT EXISTS idx_ventas_aliva_fecha ON ventas_aliva(fecha)",
        "CREATE INDEX IF NOT EXISTS idx_ventas_aliva_local ON ventas_aliva(local)",
        # --- Capa diaria de opciones (creada automaticamente) ---
        """CREATE TABLE IF NOT EXISTS opciones_diarias (
            fecha_venta     date              NOT NULL,
            local           text              NOT NULL,
            ab_categoria    text              NOT NULL,
            sku_padre       text              NOT NULL,
            sku_opcion      text              NOT NULL,
            nombre_producto text,
            ba_opcion       text,
            cant            double precision  NOT NULL,
            PRIMARY KEY (fecha_venta, local, ab_categoria, sku_padre, sku_opcion)
        )""",
        "CREATE INDEX IF NOT EXISTS idx_opdia_local_fecha ON opciones_diarias (local, fecha_venta)",
        "CREATE INDEX IF NOT EXISTS idx_opdia_padre       ON opciones_diarias (sku_padre, sku_opcion)",
        "CREATE INDEX IF NOT EXISTS idx_ventas_esopcion_ab ON ventas (es_opcion, ab_categoria, fecha_venta)",
        # --- Cierre diario de stock sobrante por categoría de proteína ---
        """CREATE TABLE IF NOT EXISTS stock_cierre_diario (
            id              bigserial         PRIMARY KEY,
            fecha           date              NOT NULL,
            local           text              NOT NULL,
            categoria       text              NOT NULL,
            cantidad        double precision  NOT NULL DEFAULT 0,
            fecha_registro  timestamp         NOT NULL DEFAULT now(),
            registrado_por  text,
            observacion     text,
            UNIQUE (fecha, local, categoria)
        )""",
        "CREATE INDEX IF NOT EXISTS idx_stkcierre_local_fecha ON stock_cierre_diario (local, fecha)",
    ]
    try:
        with engine.begin() as conn:
            for idx in indices:
                conn.execute(text(idx))
    except Exception:
        pass  # Si ya existen o no hay permisos, continuar sin error

_init_db()


def run_query(sql, params=None):
    engine = get_engine()
    if engine is None:
        return pd.DataFrame()
    try:
        with engine.connect() as conn:
            return pd.read_sql(text(sql), conn, params=params or {})
    except Exception as e:
        st.error(f"Error en consulta: {e}")
        return pd.DataFrame()


