def _cp_maximos_por_dia(mes, local="Todos"):
    """Devuelve dict {categoria: {dow: max}} con el máximo vendido por categoría
    en cada día de la semana (Lun..Dom) dentro del mes 'YYYY-MM'."""
    import calendar as _cal
    skus = list(_CP_SKU_CAT.keys())
    y, mo = map(int, mes.split("-"))
    dim = _cal.monthrange(y, mo)[1]
    params = {"i": f"{y:04d}-{mo:02d}-01", "f": f"{y:04d}-{mo:02d}-{dim:02d}", "skus": skus}
    loc_filter = ""
    if local and local != "Todos":
        loc_filter = "AND UPPER(local) = UPPER(:l)"
        params["l"] = local
    raw = run_query(f"""
        SELECT sku_producto, fecha_venta, SUM(cantidad_vendida) AS cant
        FROM ventas
        WHERE fecha_venta BETWEEN :i AND :f
          AND sku_producto = ANY(:skus) {loc_filter}
        GROUP BY sku_producto, fecha_venta
    """, params)
    DOW = {0:"Lun",1:"Mar",2:"Mié",3:"Jue",4:"Vie",5:"Sáb",6:"Dom"}
    if raw is None or raw.empty:
        return {}
    raw = raw.copy()
    raw["cant"] = pd.to_numeric(raw["cant"], errors="coerce").fillna(0)
    raw["categoria"] = raw["sku_producto"].map(_CP_SKU_CAT)
    raw = raw[raw["categoria"].notna()]
    raw["fecha_venta"] = pd.to_datetime(raw["fecha_venta"])
    raw["dow"] = raw["fecha_venta"].dt.weekday.map(DOW)
    diario = raw.groupby(["categoria", "fecha_venta", "dow"])["cant"].sum().reset_index()
    out = {}
    for (cat, dow), g in diario.groupby(["categoria", "dow"]):
        out.setdefault(cat, {})[dow] = float(g["cant"].max())
    return out


def init_exclusiones():
    """Crea las tablas compras_excluidas y sku_colacion si no existen."""
    engine = get_engine()
    if engine is None:
        return
    try:
        with engine.connect() as conn:
            conn.execute(text("""
                CREATE TABLE IF NOT EXISTS compras_excluidas (
                    id         SERIAL PRIMARY KEY,
                    compra_id  INTEGER NOT NULL UNIQUE,
                    sku        TEXT,
                    motivo     TEXT DEFAULT 'compra_emergencia',
                    creado_en  TIMESTAMP DEFAULT NOW()
                )
            """))
            conn.execute(text("""
                CREATE TABLE IF NOT EXISTS sku_colacion (
                    id        SERIAL PRIMARY KEY,
                    sku       TEXT NOT NULL UNIQUE,
                    nombre    TEXT,
                    creado_en TIMESTAMP DEFAULT NOW()
                )
            """))
            conn.commit()
    except Exception:
        pass


# ============================================================
# LÓGICA MRP (código 1 preservado íntegramente)
# ============================================================
def process_bom(df_v, df_d, df_p):
    df_v.columns = df_v.columns.str.strip()
    df_d.columns = df_d.columns.str.strip()
    df_p.columns = df_p.columns.str.strip()

    df_v = df_v.rename(columns={'SKU': 'SKU_VENTA', 'Cantidad': 'CANT_VENTA'})
    skus_vendidos = set(df_v['SKU_VENTA'].astype(str).str.strip().str.upper())

    def validar_opcion(row):
        es_op = str(row['EsOpcion']).strip()
        if pd.isna(row['EsOpcion']) or es_op in ["", "0", "4"]:
            return True
        return str(row['SKU']).strip().upper() in skus_vendidos

    df_d_ready = df_d[df_d.apply(validar_opcion, axis=1)].copy()
    m1 = pd.merge(df_v, df_d_ready, left_on='SKU_VENTA', right_on='CODIGO VENTA', how='inner')

    es_proc = m1['SKU'].str.startswith('PRO-', na=False)
    df_insumos_directos = m1[~es_proc].copy()
    df_procesados_a_explotar = m1[es_proc].copy()

    if not df_procesados_a_explotar.empty:
        rendimientos = df_p.groupby('Codigo Venta')['CantReceta'].sum().reset_index()
        rendimientos = rendimientos.rename(columns={'CantReceta': 'TOTAL_RECETA_AUTO'})

        df_p_clean = df_p.rename(columns={
            'Codigo Venta': 'COD_P',
            'Ingrediente': 'NOM_P',
            'CantEfic': 'CE_P',
            'CantReceta': 'CR_P',
            'Porcion': 'MARK_P',
            'UM Salida': 'UM_P',
            'SKU Ingrediente': 'SKU_P'
        })
        df_p_final = pd.merge(df_p_clean, rendimientos, left_on='COD_P', right_on='Codigo Venta', how='left')
        m2 = pd.merge(df_procesados_a_explotar, df_p_final, left_on='SKU', right_on='COD_P', how='left')

        def calcular_m2(row):
            if row['MARK_P'] == 1:
                return row['CANT_VENTA'] * row['CantReal'] * row['CE_P']
            else:
                divisor = row['TOTAL_RECETA_AUTO'] if row['TOTAL_RECETA_AUTO'] > 0 else 1
                return row['CANT_VENTA'] * row['CantReal'] * (row['CE_P'] / divisor)

        m2['CANT_OUT'] = m2.apply(calcular_m2, axis=1)
        exp_f = m2[['SKU_P', 'NOM_P', 'CANT_OUT', 'UM_P']].rename(
            columns={'SKU_P': 'SKU_FIN', 'NOM_P': 'ING_FIN', 'UM_P': 'UM_FIN'})
    else:
        exp_f = pd.DataFrame()

    df_insumos_directos['CANT_OUT'] = (
        df_insumos_directos['CANT_VENTA'] * df_insumos_directos['CantReal']
    )
    dir_out = df_insumos_directos[['SKU', 'Ingrediente', 'CANT_OUT', 'UM']].rename(
        columns={'SKU': 'SKU_FIN', 'Ingrediente': 'ING_FIN', 'UM': 'UM_FIN'})

    consolidado = pd.concat([dir_out, exp_f], ignore_index=True)
    resumen = consolidado.groupby(['SKU_FIN', 'UM_FIN'], as_index=False).agg(
        {'CANT_OUT': 'sum', 'ING_FIN': 'first'})

    def formatear(row):
        um = str(row['UM_FIN']).upper()
        if um in ['G', 'ML', 'CC']:
            return row['CANT_OUT'] / 1000
        return row['CANT_OUT']

    resumen['TOTAL'] = resumen.apply(formatear, axis=1)
    return resumen[['SKU_FIN', 'ING_FIN', 'UM_FIN', 'TOTAL']].rename(
        columns={'SKU_FIN': 'SKU', 'ING_FIN': 'Insumo', 'UM_FIN': 'UM', 'TOTAL': 'Total Kg/L/Un'})


# ============================================================
# CÁLCULO DE COSTO TEÓRICO POR PLATO (Informe 1)
# Directos: CantReal × MUC
# Procesados: CantEfic × MUC  (usando último precio por SKU)
# ============================================================
@st.cache_data(ttl=300, show_spinner=False)
def calcular_costo_platos(fecha_i, fecha_f, local):
    """
    Costo teórico por plato usando MUC correcto:
      MUC = costo_realfinal / (cant_conv * formato)   → ya está en $/unidad_base_del_SKU

    Para ingredientes directos:
      costo = cant_real × MUC        (cant_real en la misma unidad que el SKU: g, un, etc.)

    Para procesados (PRO-):
      El SKU es un sub-plato. Su costo se calcula recursivamente desde su propia receta
      en la tabla recetas (es_procesado=True, codigo_venta = SKU_PRO).
      Se usa cant_efic (cantidad eficiente del procesado) × costo_unitario_procesado.

    NO se aplica factor_um: el MUC ya está expresado en la unidad base del SKU
    ($/g para carnes/verduras, $/un para panes, etc.), que coincide con cant_real/cant_efic.
    """
    # MUC ponderado del período — promedio ponderado por gasto.
    # Fallback al último precio histórico (global) si no hay compras en el período para ese local.
    _filtro_local_precio = f"AND UPPER(local) = UPPER('{local}')" if local != "Todos" else ""

    precio_sql = f"""
        SELECT sku, precio_unitario FROM (
            -- Precio ponderado del período (directo, por local)
            SELECT sku,
                   SUM(costo_realfinal) / NULLIF(SUM(cant_conv * NULLIF(formato,0)), 0) AS precio_unitario,
                   1 AS prioridad
            FROM compras
            WHERE cant_conv > 0 AND costo_realfinal > 0 AND formato > 0
              AND fecha_dte::date BETWEEN '{fecha_i}' AND '{fecha_f}'
              AND sku IN (SELECT DISTINCT sku_ingrediente FROM recetas WHERE sku_ingrediente IS NOT NULL)
              {_filtro_local_precio}
            GROUP BY sku

            UNION ALL

            -- Precio ponderado del período (via equivalencia, por local)
            SELECT e.sku_receta AS sku,
                   SUM(c.costo_realfinal) / NULLIF(SUM(c.cant_conv * NULLIF(c.formato,0)), 0) AS precio_unitario,
                   2 AS prioridad
            FROM compras c
            JOIN sku_equivalencias e ON c.sku = e.sku_compra
            WHERE c.cant_conv > 0 AND c.costo_realfinal > 0 AND c.formato > 0
              AND c.fecha_dte::date BETWEEN '{fecha_i}' AND '{fecha_f}'
              AND e.sku_receta IN (SELECT DISTINCT sku_ingrediente FROM recetas WHERE sku_ingrediente IS NOT NULL)
              {_filtro_local_precio.replace('local', 'c.local')}
            GROUP BY e.sku_receta

            UNION ALL

            -- Fallback: último precio histórico (directo, global) — últimos 90 días
            SELECT sku, precio_unitario, 3 AS prioridad FROM (
                SELECT DISTINCT ON (sku) sku,
                       costo_realfinal / NULLIF(cant_conv * NULLIF(formato,0), 0) AS precio_unitario
                FROM compras
                WHERE cant_conv > 0 AND costo_realfinal > 0 AND formato > 0
                  AND fecha_dte::date >= CURRENT_DATE - INTERVAL '90 days'
                  AND sku IN (SELECT DISTINCT sku_ingrediente FROM recetas WHERE sku_ingrediente IS NOT NULL)
                ORDER BY sku, fecha_dte DESC
            ) fb1

            UNION ALL

            -- Fallback: último precio histórico (via equivalencia, global) — últimos 90 días
            SELECT sku, precio_unitario, 4 AS prioridad FROM (
                SELECT DISTINCT ON (e.sku_receta) e.sku_receta AS sku,
                       c.costo_realfinal / NULLIF(c.cant_conv * NULLIF(c.formato,0), 0) AS precio_unitario
                FROM compras c
                JOIN sku_equivalencias e ON c.sku = e.sku_compra
                WHERE c.cant_conv > 0 AND c.costo_realfinal > 0 AND c.formato > 0
                  AND c.fecha_dte::date >= CURRENT_DATE - INTERVAL '90 days'
                  AND e.sku_receta IN (SELECT DISTINCT sku_ingrediente FROM recetas WHERE sku_ingrediente IS NOT NULL)
                ORDER BY e.sku_receta, c.fecha_dte DESC
            ) fb2
        ) combined
        WHERE precio_unitario IS NOT NULL AND precio_unitario > 0
        ORDER BY sku, prioridad
    """
    df_precio_raw = run_query(precio_sql)
    # Keep only first (lowest prioridad) price per SKU
    df_precio = df_precio_raw.drop_duplicates(subset='sku', keep='first').reset_index(drop=True) if not df_precio_raw.empty else pd.DataFrame()

    if df_precio.empty:
        return pd.DataFrame()

    df_rec = get_recetas()
    if df_rec.empty:
        return pd.DataFrame()

    _es_op  = pd.to_numeric(df_rec["es_opcion"], errors="coerce")
    # df_dir  = recipes for sale plates (everything else), excluding pure options
    df_proc = df_rec[df_rec['codigo_venta'].astype(str).str.startswith('PRO-')].copy()
    df_dir  = df_rec[
        ~df_rec['codigo_venta'].astype(str).str.startswith('PRO-') &
        (_es_op.isna() | (_es_op == 0) | (_es_op == 6))
    ].copy()
    # Los PRO- tienen sus propios ingredientes directos en la tabla recetas
    # con es_procesado=True. Usamos cant_efic × MUC para cada ingrediente del PRO-.
    proc_ingredientes = df_proc.copy()
    proc_ingredientes['cant_efic'] = pd.to_numeric(proc_ingredientes['cant_efic'], errors='coerce').fillna(0)
    proc_ingredientes = pd.merge(
        proc_ingredientes, df_precio, left_on='sku_ingrediente', right_on='sku', how='left'
    )
    proc_ingredientes['precio_unitario'] = pd.to_numeric(
        proc_ingredientes['precio_unitario'], errors='coerce'
    ).fillna(0)
    proc_ingredientes['costo_parcial'] = proc_ingredientes['cant_efic'] * proc_ingredientes['precio_unitario']

    # Costo total del lote por PRO-
    costo_lote = proc_ingredientes.groupby('codigo_venta')['costo_parcial'].sum().reset_index()
    costo_lote.columns = ['codigo_venta', 'costo_lote']

    # Tamaño del lote = SUM(cant_real) cuando porcion=0, o 1 cuando porcion=1
    porcion_por_pro = df_proc.groupby('codigo_venta')['porcion'].first().reset_index()
    cant_lote = proc_ingredientes.groupby('codigo_venta')['cant_real'].sum().reset_index()
    cant_lote.columns = ['codigo_venta', 'cant_lote']

    costo_pro_df = pd.merge(costo_lote, porcion_por_pro, on='codigo_venta', how='left')
    costo_pro_df = pd.merge(costo_pro_df, cant_lote, on='codigo_venta', how='left')
    costo_pro_df['porcion'] = pd.to_numeric(costo_pro_df['porcion'], errors='coerce').fillna(0)
    costo_pro_df['cant_lote'] = pd.to_numeric(costo_pro_df['cant_lote'], errors='coerce').fillna(1)

    # Si porcion=1: costo unitario = costo_lote (ya es por unidad)
    # Si porcion=0: costo unitario por g/ml = costo_lote / cant_lote
    costo_pro_df['costo_unitario_pro'] = costo_pro_df.apply(
        lambda r: r['costo_lote'] if r['porcion'] == 1 else r['costo_lote'] / max(r['cant_lote'], 1),
        axis=1
    )

    costo_pro = costo_pro_df[['codigo_venta', 'costo_unitario_pro']].copy()
    costo_pro.columns = ['sku_ingrediente_pro', 'costo_unitario_pro']

    # ── DIRECTOS: ingredientes simples del plato de venta ────────────────────
    df_dir['cant_real'] = pd.to_numeric(df_dir['cant_real'], errors='coerce').fillna(0)

    # Separar directos que son ingredientes de compra vs los que son PRO-
    es_pro = df_dir['sku_ingrediente'].astype(str).str.startswith('PRO-')
    dir_compra = df_dir[~es_pro].copy()
    dir_pro    = df_dir[es_pro].copy()

    # Directos de compra: cant_real × MUC
    dir_compra = pd.merge(dir_compra, df_precio, left_on='sku_ingrediente', right_on='sku', how='left')
    dir_compra['precio_unitario'] = pd.to_numeric(dir_compra['precio_unitario'], errors='coerce').fillna(0)
    dir_compra['costo_parcial']   = dir_compra['cant_real'] * dir_compra['precio_unitario']

    # es_opcion=6: flavor options — weighted average cost using actual MODX sales distribution
    _es_op_dir = pd.to_numeric(dir_compra['es_opcion'], errors='coerce')
    dir_op6    = dir_compra[_es_op_dir == 6].copy()
    dir_normal = dir_compra[_es_op_dir != 6].copy()

    if not dir_op6.empty:
        # Get MODX sales distribution for the period
        _filtro_local_w = f"AND UPPER(local) = UPPER('{local}')" if local != "Todos" else ""
        _q_modx = f"""
            SELECT sku_producto, SUM(cantidad_vendida) AS ventas
            FROM ventas
            WHERE fecha_venta BETWEEN '{fecha_i}' AND '{fecha_f}'
              AND es_opcion = true
              AND ba_opcion IN ('BA.140','BA.230','BA.240')
              {_filtro_local_w}
            GROUP BY sku_producto
        """
        df_modx = run_query(_q_modx)

        if not df_modx.empty:
            _total_modx = df_modx['ventas'].sum()
            df_modx['peso'] = df_modx['ventas'] / _total_modx if _total_modx > 0 else 1 / len(df_modx)

            # Map MODX sku → ingredient sku
            _modx_map = {
                'MODX-013': 'AL-PO-001',
                'MODX-014': 'AL-PO-014',
                'MODX-015': 'AL-PO-012',
                'MODX-016': 'AL-PO-013',
            }
            df_modx['sku_ingrediente'] = df_modx['sku_producto'].map(_modx_map)
            df_modx = df_modx.dropna(subset=['sku_ingrediente'])

            # Merge weights into dir_op6
            dir_op6 = pd.merge(dir_op6, df_modx[['sku_ingrediente','peso']],
                               on='sku_ingrediente', how='left')
            dir_op6['peso'] = dir_op6['peso'].fillna(0)

            # Weighted cost per plate = SUM(costo_parcial × peso)
            dir_op6['costo_ponderado'] = dir_op6['costo_parcial'] * dir_op6['peso']
            dir_op6_avg = dir_op6.groupby('codigo_venta')['costo_ponderado'].sum().reset_index()
            dir_op6_avg.columns = ['codigo_venta', 'costo_parcial']
        else:
            # Fallback: simple average if no MODX sales data
            dir_op6_avg = dir_op6.groupby('codigo_venta')['costo_parcial'].mean().reset_index()
            dir_op6_avg.columns = ['codigo_venta', 'costo_parcial']

        dir_compra = pd.concat([dir_normal[['codigo_venta','costo_parcial']],
                                dir_op6_avg], ignore_index=True)
    else:
        dir_compra = dir_normal[['codigo_venta','costo_parcial']]

    # Directos PRO-: cant_real × costo_unitario_pro (calculado arriba)
    dir_pro = pd.merge(
        dir_pro, costo_pro,
        left_on='sku_ingrediente', right_on='sku_ingrediente_pro', how='left'
    )
    dir_pro['costo_unitario_pro'] = pd.to_numeric(dir_pro['costo_unitario_pro'], errors='coerce').fillna(0)
    dir_pro['costo_parcial']      = dir_pro['cant_real'] * dir_pro['costo_unitario_pro']

    # Consolidar todo
    costo_total = pd.concat(
        [dir_compra if isinstance(dir_compra, pd.DataFrame) and 'costo_parcial' in dir_compra.columns
         else dir_compra[['codigo_venta','costo_parcial']],
         dir_pro[['codigo_venta','costo_parcial']]],
        ignore_index=True
    )
    costo_platos = costo_total.groupby('codigo_venta')['costo_parcial'].sum().reset_index()
    costo_platos.columns = ['sku_producto', 'cmv_base']
    return costo_platos


@st.cache_data(ttl=300, show_spinner=False)
def calcular_cmv_con_opciones(fecha_i, fecha_f, local):
    """
    CMV unitario por plato = costo_base + cmv_opciones_unitario

    cmv_opciones_unitario = SUM(cant_opcion_i × costo_receta_opcion_i) / cant_padre_total

    cant_padre se obtiene en query separada para evitar inflación por el JOIN con opciones.
    """
    filtro_local = "AND UPPER(local) = UPPER(:l)" if local != "Todos" else ""
    params_loc = {'i': str(fecha_i), 'f': str(fecha_f)}
    if local != "Todos": params_loc['l'] = local

    costo_base = calcular_costo_platos(fecha_i, fecha_f, local)
    if costo_base.empty:
        return pd.DataFrame()

    # ── Cantidad total vendida de cada plato padre (query independiente) ──────
    q_cant_padre = f"""
        SELECT sku_producto, SUM(cantidad_vendida) AS cant_padre
        FROM ventas
        WHERE fecha_venta BETWEEN :i AND :f
          AND es_opcion = false
          {filtro_local}
        GROUP BY sku_producto
    """
    df_cant_padre = run_query(q_cant_padre, params_loc)
    if df_cant_padre.empty:
        result = costo_base.copy()
        result['cmv_opciones'] = 0.0
        result['cmv_unitario'] = result['cmv_base']
        return result[['sku_producto', 'cmv_unitario', 'cmv_base', 'cmv_opciones']]

    df_cant_padre['cant_padre'] = pd.to_numeric(df_cant_padre['cant_padre'], errors='coerce').fillna(1)

    # ── Opciones costeables: SOLO Pan y Proteína ─────────────────────────────
    # La clave es agrupar por (id_orden, ab_categoria, sku_padre, sku_opcion).
    # Dentro de cada pedido, ab_categoria identifica a qué plato base
    # pertenecen las opciones. Si hay 2 sandwiches distintos en el mismo pedido
    # con distinto ab_categoria, sus opciones no se mezclan.
    # Si hay 2 unidades del MISMO plato (mismo sku_padre), la cantidad de
    # opciones se divide por la cantidad del padre en ese pedido.
    ba_costeables_sql = "', '".join(BA_COSTEABLES)
    filtro_v = filtro_local

    _plates_2_scoops_sql = 'POS-002'
    _plates_3_scoops_sql = 'POS-008'

    q_opciones = f"""
        WITH skus_con_opciones AS (
            -- Solo padres que tienen opciones costeables declaradas en su receta
            SELECT DISTINCT codigo_venta AS sku_padre
            FROM recetas
            WHERE es_opcion IN (1, 2, 3, 6)
        ),
        padres AS (
            SELECT id_orden, ab_categoria, sku_producto AS sku_padre,
                   SUM(cantidad_vendida) AS cant_padre,
                   CASE
                       WHEN sku_producto = '{_plates_3_scoops_sql}' THEN 3
                       WHEN sku_producto = '{_plates_2_scoops_sql}' THEN 2
                       ELSE 1
                   END AS scoops_por_unidad
            FROM ventas
            WHERE fecha_venta BETWEEN :i AND :f
              AND es_opcion = false
              AND ab_categoria IS NOT NULL
              AND sku_producto IN (SELECT sku_padre FROM skus_con_opciones)
              {filtro_v}
            GROUP BY id_orden, ab_categoria, sku_producto
        ),
        total_por_ab_orden AS (
            SELECT id_orden, ab_categoria, SUM(cant_padre) AS total_padres
            FROM padres
            GROUP BY id_orden, ab_categoria
        ),
        opciones_raw AS (
            SELECT id_orden, ab_categoria, sku_producto AS sku_opcion,
                   SUM(cantidad_vendida) AS cant_opcion
            FROM ventas
            WHERE fecha_venta BETWEEN :i AND :f
              AND es_opcion = true
              AND ba_opcion IN ('{ba_costeables_sql}')
              {filtro_v}
            GROUP BY id_orden, ab_categoria, sku_producto
        ),
        -- Cap total options per (order, ab_categoria) to expected scoops
        opciones_cap AS (
            SELECT
                o.id_orden,
                o.ab_categoria,
                o.sku_opcion,
                o.cant_opcion,
                SUM(o.cant_opcion) OVER (PARTITION BY o.id_orden, o.ab_categoria) AS total_opciones,
                SUM(p.cant_padre * p.scoops_por_unidad) AS total_esperado
            FROM opciones_raw o
            JOIN (
                SELECT id_orden, ab_categoria,
                       SUM(cant_padre * scoops_por_unidad) AS cant_padre,
                       SUM(cant_padre * scoops_por_unidad) AS scoops_por_unidad
                FROM padres
                GROUP BY id_orden, ab_categoria
            ) p ON p.id_orden = o.id_orden AND p.ab_categoria = o.ab_categoria
            GROUP BY o.id_orden, o.ab_categoria, o.sku_opcion, o.cant_opcion
        ),
        opciones AS (
            SELECT
                id_orden, ab_categoria, sku_opcion,
                -- Scale down cant_opcion if total options exceed expected scoops
                CASE
                    WHEN total_opciones > total_esperado AND total_opciones > 0
                    THEN cant_opcion * total_esperado::float / total_opciones::float
                    ELSE cant_opcion
                END AS cant_opcion
            FROM opciones_cap
        )
        SELECT
            p.sku_padre,
            o.sku_opcion,
            SUM(o.cant_opcion::float * p.cant_padre::float / NULLIF(t.total_padres, 0)) AS cant_opcion_total
        FROM padres p
        JOIN total_por_ab_orden t ON t.id_orden = p.id_orden AND t.ab_categoria = p.ab_categoria
        JOIN opciones o            ON o.id_orden = p.id_orden AND o.ab_categoria = p.ab_categoria
        GROUP BY p.sku_padre, o.sku_opcion
    """
    df_op = run_query(q_opciones, params_loc)

    if df_op.empty:
        result = costo_base.copy()
        result['cmv_opciones'] = 0.0
        result['cmv_unitario'] = result['cmv_base']
        return result[['sku_producto', 'cmv_unitario', 'cmv_base', 'cmv_opciones']]

    df_op['cant_opcion_total'] = pd.to_numeric(df_op['cant_opcion_total'], errors='coerce').fillna(0)

    # ── Costo unitario de cada SKU opción desde recetas (es_opcion != 0) ──────
    # Costo de cada SKU opción — usar costo_base que ya tiene el costo correcto
    # de todos los platos incluyendo CHUX-021, PANX-001, etc.
    costo_op_sku = costo_base.copy().rename(columns={
        'sku_producto':  'sku_opcion',
        'cmv_base':      'costo_receta_opcion'
    })

    # cant_opcion_norm ya viene normalizada por unidades del padre en cada pedido.
    # Multiplicamos por costo unitario y sumamos por padre → cmv_opciones total acumulado.
    # Dividimos por cant_padre (total vendido) → cmv_opciones unitario.
    df_op = pd.merge(df_op, costo_op_sku, on='sku_opcion', how='left')
    df_op['costo_receta_opcion'] = pd.to_numeric(df_op['costo_receta_opcion'], errors='coerce').fillna(0)
    df_op['costo_opcion_acum'] = df_op['cant_opcion_total'] * df_op['costo_receta_opcion']

    agg = df_op.groupby('sku_padre')['costo_opcion_acum'].sum().reset_index()
    agg.columns = ['sku_producto', 'costo_opciones_acum']

    # cant_padre total del período (ya calculado arriba)
    agg = pd.merge(agg, df_cant_padre, on='sku_producto', how='left')
    agg['cant_padre'] = agg['cant_padre'].fillna(1)
    # cant_opcion_norm ya fue dividida por cant_padre_orden en el SQL,
    # así que costo_opciones_acum / cant_padre_total da el costo unitario correcto.
    agg['cmv_opciones'] = agg['costo_opciones_acum'] / agg['cant_padre'].clip(lower=1)

    result = pd.merge(costo_base, agg[['sku_producto', 'cmv_opciones']], on='sku_producto', how='left')
    result['cmv_opciones'] = result['cmv_opciones'].fillna(0)
    result['cmv_unitario'] = result['cmv_base'] + result['cmv_opciones']
    return result[['sku_producto', 'cmv_unitario', 'cmv_base', 'cmv_opciones']]





# ============================================================
# COSTO PERÍODO: MUC ponderado del período, fallback última compra
# ============================================================

# ============================================================
# INFORME 1: RENTABILIDAD POR PRODUCTO / CATEGORÍA
# ============================================================
@st.cache_data(ttl=300, show_spinner=False)
def informe_rentabilidad(fecha_i, fecha_f, local):
    engine = get_engine()
    if engine is None:
        return pd.DataFrame()

    filtro_local_r = "AND UPPER(local) = UPPER(:l)" if local != "Todos" else ""
    params = {"i": str(fecha_i), "f": str(fecha_f)}
    if local != "Todos":
        params["l"] = local

    q_v = f"""
        SELECT sku_producto,
               MAX(nombre_producto)  as nombre_producto,
               MAX(categoria_menu)   as categoria_menu,
               MAX(ab_categoria)     as ab_categoria,
               SUM(cantidad_vendida) as cant,
               SUM(monto_venta_real) as venta
        FROM ventas
        WHERE fecha_venta BETWEEN :i AND :f
          AND (
              es_opcion = false
              OR sku_producto IN (
                  -- Incluir agregados con precio propio que tienen receta definida
                  SELECT DISTINCT codigo_venta FROM recetas
                  WHERE codigo_venta IS NOT NULL
              )
          )
          AND sku_producto NOT LIKE 'CP%'
          {filtro_local_r}
        GROUP BY sku_producto
    """
    df_v = run_query(q_v, params)
    if df_v.empty:
        st.warning("No hay ventas para el período/local seleccionado.")
        return pd.DataFrame()

    df_v['cant']  = pd.to_numeric(df_v['cant'],  errors='coerce').fillna(0)
    df_v['venta'] = pd.to_numeric(df_v['venta'], errors='coerce').fillna(0)

    # CMV con opciones ponderadas (nuevo método)
    df_cmv = calcular_cmv_con_opciones(fecha_i, fecha_f, local)

    df = pd.merge(df_v, df_cmv, on='sku_producto', how='left')
    df['cmv_unitario'] = pd.to_numeric(df.get('cmv_unitario'), errors='coerce').fillna(0)
    df['cmv_base']     = pd.to_numeric(df.get('cmv_base'),     errors='coerce').fillna(0)
    df['cmv_opciones'] = pd.to_numeric(df.get('cmv_opciones'), errors='coerce').fillna(0)

    # Indicadores por producto
    df['cmv_total']    = df['cant'] * df['cmv_unitario']
    df['cmv_pct']      = df.apply(lambda r: r['cmv_total']/r['venta']*100 if r['venta']>0 else 0, axis=1)
    df['mc_unitario']  = df['venta']/df['cant'].clip(lower=1) - df['cmv_unitario']
    df['mc_total']     = df['venta'] - df['cmv_total']
    df['margen_pct']   = df.apply(lambda r: r['mc_total']/r['venta']*100 if r['venta']>0 else 0, axis=1)

    # Popularidad por categoría
    total_cant_cat = df.groupby('categoria_menu')['cant'].transform('sum')
    n_items_cat    = df.groupby('categoria_menu')['sku_producto'].transform('count')
    df['mix_pct']      = df['cant'] / total_cant_cat.clip(lower=1) * 100
    df['umbral_pct']   = 100 / n_items_cat * 70  # 70% del reparto uniforme

    # Cuadrante BCG gastronómico por categoría
    # Usamos MEDIANA de mix_pct y mc_unitario por categoría como umbral
    # Esto evita que outliers distorsionen la clasificación
    mediana_mix_cat = df.groupby('categoria_menu')['mix_pct'].transform('median')
    mediana_mc_cat  = df.groupby('categoria_menu')['mc_unitario'].transform('median')
    def cuadrante(r):
        alta_pop  = r['mix_pct']      >= mediana_mix_cat[r.name]
        alto_mc   = r['mc_unitario']  >= mediana_mc_cat[r.name]
        if alta_pop and alto_mc:   return "⭐ Estrella"
        if not alta_pop and alto_mc: return "❓ Interrogante"
        if alta_pop and not alto_mc: return "🐄 Vaca"
        return "🐶 Perro"
    df['cuadrante'] = df.apply(cuadrante, axis=1)

    # Compatibilidad con código existente
    df['costo_unitario_teorico'] = df['cmv_unitario']
    df['costo_unitario_periodo'] = df['cmv_unitario']
    df['costo_total_teorico']    = df['cmv_total']
    df['costo_total_periodo']    = df['cmv_total']
    df['rentabilidad_teorica']   = df['mc_total']
    df['rentabilidad_periodo']   = df['mc_total']
    df['margen_teorico']         = df['margen_pct']
    df['margen_periodo']         = df['margen_pct']
    df['costo_total']            = df['cmv_total']
    df['rentabilidad']           = df['mc_total']

    return df.sort_values('venta', ascending=False)



# BA jerarquías que forman parte del costo del plato (Pan + Proteína).
# Bebida, Agregados, Postre, Cubiertos, Acompañamiento, etc. son productos
# independientes con precio propio → NO se suman al CMV del plato padre.
BA_COSTEABLES = {
    'BA.010',  # Opcion Pan Clasicos
    'BA.011',  # Opcion Pan de la casa
    'BA.020',  # Opcion Proteinas
    'BA.250',  # Opción Proteínas Clásicos
    'BA.260',  # Opcion Sándwich Italiano (proteína específica)
    'BA.140',  # Helados
    'BA.230',  # Opcion Helado 2
    'BA.240',  # Opcion Helado 3
}

# Mapeo BA jerarquía → grupo visual
BA_GRUPOS = {
    'Pan':            ['BA.010','BA.011'],
    'Proteína':       ['BA.020','BA.250','BA.260'],
    'Agregados':      ['BA.030','BA.270','BA.280'],
    'Modificación':   ['BA.040','BA.330','BA.340','BA.350','BA.360','BA.370',
                       'BA.380','BA.390','BA.400','BA.410','BA.420','BA.430',
                       'BA.440','BA.450','BA.460','BA.470','BA.480','BA.490'],
    'Punto Cocción':  ['BA.050'],
    'Bebida':         ['BA.060','BA.070','BA.150','BA.210'],
    'Acompañamiento': ['BA.100','BA.110','BA.120','BA.170','BA.180','BA.220'],
    'Extras':         ['BA.080','BA.090','BA.290','BA.300','BA.310'],
    'Postre':         ['BA.140','BA.230','BA.240','BA.320'],
    'Cubiertos':      ['BA.200'],
}
# Invertir para lookup rápido: BA.010 → 'Pan'
BA_A_GRUPO = {ba: grupo for grupo, bas in BA_GRUPOS.items() for ba in bas}


def get_opciones_producto(fecha_i, fecha_f, local, ab_categoria_padre, sku_padre=None):
    """
    Distribución de opciones para un plato, agrupadas por jerarquía BA.
    Usa lógica proporcional: cada plato recibe cant_opcion × (cant_padre / total_padres_ab)
    para separar correctamente las opciones cuando hay múltiples platos con el mismo ab_categoria.
    """
    filtro_local = "AND UPPER(local) = UPPER(:l)" if local != "Todos" else ""
    params = {'i': str(fecha_i), 'f': str(fecha_f), 'ab': ab_categoria_padre}
    if local != "Todos":
        params['l'] = local

    filtro_sku = "AND p.sku_producto = :sku" if sku_padre else ""
    if sku_padre:
        params['sku'] = sku_padre

    q = f"""
        WITH padres AS (
            SELECT id_orden, ab_categoria, sku_producto AS sku_padre,
                   SUM(cantidad_vendida) AS cant_padre
            FROM ventas
            WHERE fecha_venta BETWEEN :i AND :f
              AND es_opcion = false
              AND ab_categoria = :ab
              {filtro_local}
            GROUP BY id_orden, ab_categoria, sku_producto
        ),
        total_por_ab_orden AS (
            SELECT id_orden, ab_categoria, SUM(cant_padre) AS total_padres
            FROM padres GROUP BY id_orden, ab_categoria
        ),
        opciones AS (
            SELECT id_orden, ab_categoria, sku_producto, nombre_producto, ba_opcion,
                   SUM(cantidad_vendida) AS cant_opcion
            FROM ventas
            WHERE fecha_venta BETWEEN :i AND :f
              AND es_opcion = true
              AND ab_categoria = :ab
              {filtro_local}
            GROUP BY id_orden, ab_categoria, sku_producto, nombre_producto, ba_opcion
        )
        SELECT
            o.sku_producto, o.nombre_producto, o.ba_opcion,
            SUM(o.cant_opcion::float * p.cant_padre::float / NULLIF(t.total_padres, 0)) AS cant
        FROM padres p
        JOIN total_por_ab_orden t ON t.id_orden = p.id_orden AND t.ab_categoria = p.ab_categoria
        JOIN opciones o            ON o.id_orden = p.id_orden AND o.ab_categoria = p.ab_categoria
        {("WHERE p.sku_padre = :sku" if sku_padre else "")}
        GROUP BY o.sku_producto, o.nombre_producto, o.ba_opcion
        ORDER BY o.ba_opcion, cant DESC
    """
    df = run_query(q, params)
    if df.empty:
        return {}

    df['cant'] = pd.to_numeric(df['cant'], errors='coerce').fillna(0)

    # Agrupar por grupo BA
    resultado = {}
    for _, row in df.iterrows():
        ba  = str(row['ba_opcion'] or '').strip()
        grp = BA_A_GRUPO.get(ba, 'Otros')
        if grp not in resultado:
            resultado[grp] = []
        resultado[grp].append(row)

    # Convertir a DataFrame por grupo y calcular %
    grupos_df = {}
    for grp, rows in resultado.items():
        df_g = pd.DataFrame(rows)
        total_g = df_g['cant'].sum()
        df_g['pct'] = (df_g['cant'] / total_g * 100).round(1) if total_g > 0 else 0
        grupos_df[grp] = df_g.sort_values('cant', ascending=False)

    # Ordenar grupos según BA_GRUPOS
    orden = list(BA_GRUPOS.keys()) + ['Otros']
    return {g: grupos_df[g] for g in orden if g in grupos_df}


def get_opciones_por_local(fecha_i, fecha_f, ab_categoria_padre):
    """Distribución de opciones por local para un plato dado, agrupadas por BA."""
    q = """
        SELECT p.local, o.nombre_producto, o.ba_opcion,
               SUM(o.cantidad_vendida) as cant
        FROM ventas p
        JOIN ventas o
          ON p.id_orden     = o.id_orden
         AND p.ab_categoria = o.ab_categoria
         AND o.es_opcion    = true
         AND p.es_opcion    = false
        WHERE p.fecha_venta BETWEEN :i AND :f
          AND p.ab_categoria = :ab
        GROUP BY p.local, o.nombre_producto, o.ba_opcion
        ORDER BY p.local, o.ba_opcion, cant DESC
    """
    df = run_query(q, {'i': str(fecha_i), 'f': str(fecha_f), 'ab': ab_categoria_padre})
    if df.empty:
        return {}

    df['cant'] = pd.to_numeric(df['cant'], errors='coerce').fillna(0)
    df['grupo'] = df['ba_opcion'].apply(lambda x: BA_A_GRUPO.get(str(x or '').strip(), 'Otros'))
    return df


def refrescar_opciones_diarias(fecha_i, fecha_f=None, platos=None, ab_categorias=None):
    """
    Recalcula la capa diaria de opciones (tabla opciones_diarias) para un rango.
    Idempotente: borra y reinserta el rango (acotado por 'platos' si se indica).

    Parametros:
        fecha_i, fecha_f : rango de fechas ('YYYY-MM-DD' o date). Si fecha_f es None,
                           procesa un solo dia (fecha_i).
        platos           : lista de sku_padre a incluir. Si None -> TODOS los platos.
                           Este filtro se aplica SOLO en el WHERE final (y en el DELETE),
                           NUNCA dentro de 'padres', para no inflar el denominador.
        ab_categorias    : lista de ab_categoria para acotar el escaneo (va en 'padres'
                           y 'opciones'). Si None -> todas las categorias.

    Usos:
        refrescar_opciones_diarias('2026-06-04')                          # 1 dia (nocturno)
        refrescar_opciones_diarias('2026-03-01', '2026-03-31')            # mes completo
        refrescar_opciones_diarias('2026-03-01', '2026-03-31',
                                   platos=['AE06','AE07'],
                                   ab_categorias=['AB.010140'])            # mes + lista

    Levanta el statement_timeout SOLO para esta transaccion (SET LOCAL), asi el backfill
    no choca con el limite de 30s del engine de la app. Devuelve True/False.
    """
    engine = get_engine()
    if engine is None:
        return False
    fecha_f = fecha_f or fecha_i
    params = {"i": str(fecha_i), "f": str(fecha_f)}

    f_ab = ""
    if ab_categorias:
        f_ab = "AND ab_categoria = ANY(:abs)"
        params["abs"] = list(ab_categorias)

    f_padre_out = ""
    f_delete = ""
    if platos:
        f_padre_out = "WHERE p.sku_padre = ANY(:platos)"
        f_delete = "AND sku_padre = ANY(:platos)"
        params["platos"] = list(platos)

    sql_delete = f"""
        DELETE FROM opciones_diarias
        WHERE fecha_venta BETWEEN :i AND :f
        {f_delete}
    """

    sql_insert = f"""
        INSERT INTO opciones_diarias
            (fecha_venta, local, ab_categoria, sku_padre, sku_opcion,
             nombre_producto, ba_opcion, cant)
        WITH padres AS (
            SELECT fecha_venta, local, id_orden, ab_categoria,
                   sku_producto AS sku_padre,
                   SUM(cantidad_vendida) AS cant_padre
            FROM ventas
            WHERE fecha_venta BETWEEN :i AND :f
              AND es_opcion = false
              {f_ab}
            GROUP BY fecha_venta, local, id_orden, ab_categoria, sku_producto
        ),
        total_por_ab_orden AS (
            SELECT fecha_venta, local, id_orden, ab_categoria,
                   SUM(cant_padre) AS total_padres
            FROM padres
            GROUP BY fecha_venta, local, id_orden, ab_categoria
        ),
        opciones AS (
            SELECT fecha_venta, local, id_orden, ab_categoria,
                   sku_producto AS sku_opcion, nombre_producto, ba_opcion,
                   SUM(cantidad_vendida) AS cant_opcion
            FROM ventas
            WHERE fecha_venta BETWEEN :i AND :f
              AND es_opcion = true
              {f_ab}
            GROUP BY fecha_venta, local, id_orden, ab_categoria,
                     sku_producto, nombre_producto, ba_opcion
        )
        SELECT
            p.fecha_venta, p.local, p.ab_categoria, p.sku_padre, o.sku_opcion,
            MAX(o.nombre_producto) AS nombre_producto,
            MAX(o.ba_opcion)       AS ba_opcion,
            SUM(o.cant_opcion::float * p.cant_padre::float
                / NULLIF(t.total_padres, 0)) AS cant
        FROM padres p
        JOIN total_por_ab_orden t
               ON t.fecha_venta  = p.fecha_venta
              AND t.local        = p.local
              AND t.id_orden     = p.id_orden
              AND t.ab_categoria = p.ab_categoria
        JOIN opciones o
               ON o.fecha_venta  = p.fecha_venta
              AND o.local        = p.local
              AND o.id_orden     = p.id_orden
              AND o.ab_categoria = p.ab_categoria
        {f_padre_out}
        GROUP BY p.fecha_venta, p.local, p.ab_categoria, p.sku_padre, o.sku_opcion
    """

    try:
        with engine.begin() as conn:
            conn.execute(text("SET LOCAL statement_timeout = 0"))
            conn.execute(text(sql_delete), params)
            conn.execute(text(sql_insert), params)
        return True
    except Exception as e:
        st.error(f"Error refrescando opciones_diarias: {e}")
        return False


def get_estadisticas_opciones_dia_semana(fecha_i, fecha_f, local="Todos",
                                         sku_padre=None, ab_categoria=None):
    """
    Estadistica de opciones por DIA DE SEMANA sobre la capa diaria (opciones_diarias).
    Rellena con 0 los dias operativos del local sin venta de esa opcion.
    Entrega: n_dias, minimo, maximo, promedio, desv, cv, mediana, p75, p90, moda.
    Devuelve un pd.DataFrame (NO el dict de get_opciones_producto).
    """
    filtros = []
    params = {"i": str(fecha_i), "f": str(fecha_f)}
    if local and local != "Todos":
        filtros.append("AND UPPER(local) = UPPER(:l)")
        params["l"] = local
    if sku_padre:
        filtros.append("AND sku_padre = :sku")
        params["sku"] = sku_padre
    if ab_categoria:
        filtros.append("AND ab_categoria = :ab")
        params["ab"] = ab_categoria
    f_combos = "\n              ".join(filtros)

    q = f"""
        WITH dias AS (
            SELECT DISTINCT local, fecha_venta
            FROM opciones_diarias
            WHERE fecha_venta BETWEEN :i AND :f
        ),
        combos AS (
            SELECT DISTINCT local, ab_categoria, sku_padre, sku_opcion,
                   nombre_producto, ba_opcion
            FROM opciones_diarias
            WHERE fecha_venta BETWEEN :i AND :f
              {f_combos}
        ),
        serie AS (
            SELECT c.local, c.ab_categoria, c.sku_padre, c.sku_opcion,
                   c.nombre_producto, c.ba_opcion,
                   EXTRACT(ISODOW FROM d.fecha_venta)::int AS dow,
                   COALESCE(o.cant, 0) AS cant
            FROM combos c
            JOIN dias d ON d.local = c.local
            LEFT JOIN opciones_diarias o
                   ON o.local        = c.local
                  AND o.fecha_venta  = d.fecha_venta
                  AND o.ab_categoria = c.ab_categoria
                  AND o.sku_padre    = c.sku_padre
                  AND o.sku_opcion   = c.sku_opcion
        )
        SELECT
            local, ab_categoria, sku_padre, sku_opcion, nombre_producto, ba_opcion,
            dow,
            CASE dow WHEN 1 THEN 'Lunes'  WHEN 2 THEN 'Martes' WHEN 3 THEN 'Miercoles'
                     WHEN 4 THEN 'Jueves' WHEN 5 THEN 'Viernes' WHEN 6 THEN 'Sabado'
                     WHEN 7 THEN 'Domingo' END                       AS dia_semana,
            COUNT(*)                                                 AS n_dias,
            ROUND(MIN(cant)::numeric, 2)                             AS minimo,
            ROUND(MAX(cant)::numeric, 2)                             AS maximo,
            ROUND(AVG(cant)::numeric, 2)                             AS promedio,
            ROUND(COALESCE(STDDEV_SAMP(cant), 0)::numeric, 2)        AS desv,
            ROUND((COALESCE(STDDEV_SAMP(cant), 0)
                   / NULLIF(AVG(cant), 0))::numeric, 2)              AS cv,
            ROUND(PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY cant)::numeric, 2) AS mediana,
            ROUND(PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY cant)::numeric, 2) AS p75,
            ROUND(PERCENTILE_CONT(0.90) WITHIN GROUP (ORDER BY cant)::numeric, 2) AS p90,
            ROUND(MODE() WITHIN GROUP (ORDER BY cant)::numeric, 2)   AS moda
        FROM serie
        GROUP BY local, ab_categoria, sku_padre, sku_opcion,
                 nombre_producto, ba_opcion, dow
        ORDER BY local, sku_padre, ba_opcion, dow
    """

    df = run_query(q, params)
    if df.empty:
        return df

    df["grupo_ba"] = df["ba_opcion"].apply(
        lambda x: BA_A_GRUPO.get(str(x or "").strip(), "Otros")
    )
    return df


# ============================================================
# CP2 — Patrón de demanda: día de semana × fase de pago
# (Control de Producción · proyección de "semana presente")
# Sufijo _CP2 / get_estadisticas_cp2 para NO colisionar con
# get_estadisticas_opciones_dia_semana ni con el bloque Garzones.
# ============================================================

# Fase de pago en Chile. El sueldo se paga el ÚLTIMO día hábil del mes, por lo que
# el pico arranca a fin de mes y se extiende a los primeros días del mes siguiente:
# por eso "fin de mes" e "inicio de mes" son el MISMO evento y van fusionados.
#   1 = Sueldo (fin/inicio mes)  últimos 3 días del mes  Y  días 1..5
#   2 = Valle 1ª quincena        6..12
#   3 = Adelanto (~15)           13..18
#   4 = Valle 2ª quincena        19 .. (fin-3)
_CP2_FASE_NOM = {
    1: "Sueldo (fin/inicio mes)",
    2: "Valle 1ª quincena",
    3: "Adelanto (~15)",
    4: "Valle 2ª quincena",
}
# Clasificador SQL de fase de pago (coherente con opciones_diarias).
# Último día del mes = DATE_TRUNC('month') + 1 mes - 1 día; "últimos 3" => >= último-2.
# La fase 1 (Sueldo) cubre dos tramos: dd<=5 OR dd>=(último-2).
_CP2_FASE_SQL = """
    CASE
        WHEN EXTRACT(DAY FROM {col})::int <= 5 THEN 1
        WHEN {col} >= (DATE_TRUNC('month', {col})
                       + INTERVAL '1 month' - INTERVAL '3 day')::date THEN 1
        WHEN EXTRACT(DAY FROM {col})::int BETWEEN 6 AND 12 THEN 2
        WHEN EXTRACT(DAY FROM {col})::int BETWEEN 13 AND 18 THEN 3
        ELSE 4
    END
"""


def fase_pago_cp2(d):
    """Clasifica una fecha (date) en fase de pago. Espejo Python del SQL CP2."""
    import calendar as _cal
    dim = _cal.monthrange(d.year, d.month)[1]
    dd = d.day
    if dd <= 5 or dd >= dim - 2:   # Sueldo: inicio de mes o últimos 3 días
        return 1
    if 6 <= dd <= 12:
        return 2
    if 13 <= dd <= 18:
        return 3
    return 4


def get_estadisticas_cp2(fecha_i, fecha_f, local="Todos",
                         sku_padre=None, ab_categoria=None):
    """
    Patrón de demanda por DÍA DE SEMANA × FASE DE PAGO sobre la capa diaria
    (opciones_diarias), para proyectar la "semana presente" en Control de Producción.

    A diferencia de get_estadisticas_opciones_dia_semana:
      - cruza día de semana CON la fase de pago (efecto sueldo/adelanto chileno);
      - NO rellena días cerrados: si un local no operó un día, ese día simplemente
        no existe en opciones_diarias y no entra al promedio (n_dias lo refleja);
      - mantiene el cero legítimo (operó pero no vendió esa opción) vía el LEFT JOIN
        contra los días en que el local SÍ tuvo registros.

    Devuelve un DataFrame con una fila por
    (local, sku_padre, sku_opcion, ba_opcion, dow, fase) y métricas:
    n_dias, minimo, maximo, promedio, desv, cv, mediana, p75, p90, moda.
    """
    filtros = []
    params = {"i": str(fecha_i), "f": str(fecha_f)}
    if local and local != "Todos":
        filtros.append("AND UPPER(local) = UPPER(:l)")
        params["l"] = local
    if sku_padre:
        filtros.append("AND sku_padre = :sku")
        params["sku"] = sku_padre
    if ab_categoria:
        filtros.append("AND ab_categoria = :ab")
        params["ab"] = ab_categoria
    f_combos = "\n              ".join(filtros)

    fase_d = _CP2_FASE_SQL.format(col="d.fecha_venta")

    q = f"""
        WITH dias AS (
            -- días en que CADA local SÍ operó (tuvo registros): excluye cierres
            SELECT DISTINCT local, fecha_venta
            FROM opciones_diarias
            WHERE fecha_venta BETWEEN :i AND :f
        ),
        combos AS (
            SELECT DISTINCT local, ab_categoria, sku_padre, sku_opcion,
                   nombre_producto, ba_opcion
            FROM opciones_diarias
            WHERE fecha_venta BETWEEN :i AND :f
              {f_combos}
        ),
        serie AS (
            SELECT c.local, c.ab_categoria, c.sku_padre, c.sku_opcion,
                   c.nombre_producto, c.ba_opcion,
                   EXTRACT(ISODOW FROM d.fecha_venta)::int AS dow,
                   {fase_d} AS fase,
                   COALESCE(o.cant, 0) AS cant
            FROM combos c
            JOIN dias d ON d.local = c.local
            LEFT JOIN opciones_diarias o
                   ON o.local        = c.local
                  AND o.fecha_venta  = d.fecha_venta
                  AND o.ab_categoria = c.ab_categoria
                  AND o.sku_padre    = c.sku_padre
                  AND o.sku_opcion   = c.sku_opcion
        )
        SELECT
            local, ab_categoria, sku_padre, sku_opcion, nombre_producto, ba_opcion,
            dow,
            CASE dow WHEN 1 THEN 'Lunes'  WHEN 2 THEN 'Martes' WHEN 3 THEN 'Miercoles'
                     WHEN 4 THEN 'Jueves' WHEN 5 THEN 'Viernes' WHEN 6 THEN 'Sabado'
                     WHEN 7 THEN 'Domingo' END                       AS dia_semana,
            fase,
            COUNT(*)                                                 AS n_dias,
            ROUND(MIN(cant)::numeric, 2)                             AS minimo,
            ROUND(MAX(cant)::numeric, 2)                             AS maximo,
            ROUND(AVG(cant)::numeric, 2)                             AS promedio,
            ROUND(COALESCE(STDDEV_SAMP(cant), 0)::numeric, 2)        AS desv,
            ROUND((COALESCE(STDDEV_SAMP(cant), 0)
                   / NULLIF(AVG(cant), 0))::numeric, 2)              AS cv,
            ROUND(PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY cant)::numeric, 2) AS mediana,
            ROUND(PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY cant)::numeric, 2) AS p75,
            ROUND(PERCENTILE_CONT(0.90) WITHIN GROUP (ORDER BY cant)::numeric, 2) AS p90,
            ROUND(MODE() WITHIN GROUP (ORDER BY cant)::numeric, 2)   AS moda
        FROM serie
        GROUP BY local, ab_categoria, sku_padre, sku_opcion,
                 nombre_producto, ba_opcion, dow, fase
        ORDER BY local, sku_padre, ba_opcion, dow, fase
    """

    df = run_query(q, params)
    if df.empty:
        return df

    df["grupo_ba"] = df["ba_opcion"].apply(
        lambda x: BA_A_GRUPO.get(str(x or "").strip(), "Otros")
    )
    df["fase_nom"] = df["fase"].map(_CP2_FASE_NOM)
    return df


def get_dias_operativos_cp2(fecha_i, fecha_f, local="Todos"):
    """
    Cuenta los DÍAS-CALENDARIO reales por (local, día de semana, fase de pago)
    en la muestra. Es el denominador de confianza correcto: cuántos 'lunes-Sueldo'
    (etc.) ocurrieron realmente, INDEPENDIENTE del SKU vendido ese día.

    A diferencia de n_dias de get_estadisticas_cp2 (que cuenta por sku_opcion),
    aquí se cuentan fechas distintas en que el local operó, que es lo que da
    soporte estadístico a la proyección.

    Devuelve dict {(local, dow, fase): n_dias_calendario}.
    """
    params = {"i": str(fecha_i), "f": str(fecha_f)}
    f_loc = ""
    if local and local != "Todos":
        f_loc = "AND UPPER(local) = UPPER(:l)"
        params["l"] = local
    fase_d = _CP2_FASE_SQL.format(col="fecha_venta")
    q = f"""
        SELECT local,
               EXTRACT(ISODOW FROM fecha_venta)::int AS dow,
               {fase_d} AS fase,
               COUNT(DISTINCT fecha_venta) AS n_dias
        FROM opciones_diarias
        WHERE fecha_venta BETWEEN :i AND :f
          {f_loc}
        GROUP BY local, EXTRACT(ISODOW FROM fecha_venta)::int, {fase_d}
    """
    df = run_query(q, params)
    if df is None or df.empty:
        return {}
    out = {}
    for _, r in df.iterrows():
        out[(r["local"], int(r["dow"]), int(r["fase"]))] = int(r["n_dias"])
    return out


def get_cobertura_cp2():
    """
    Rango real de datos en la capa opciones_diarias: (fecha_min, fecha_max, n_dias).
    Sirve para proyectar sobre TODO el histórico disponible por defecto.
    Devuelve (None, None, 0) si la capa está vacía.
    """
    df = run_query("""
        SELECT MIN(fecha_venta) AS fmin,
               MAX(fecha_venta) AS fmax,
               COUNT(DISTINCT fecha_venta) AS n
        FROM opciones_diarias
    """)
    if df is None or df.empty or pd.isna(df["fmin"].iloc[0]):
        return (None, None, 0)
    return (df["fmin"].iloc[0], df["fmax"].iloc[0], int(df["n"].iloc[0]))





# ============================================================
# INFORME 2: DESVIACIÓN REAL VS TEÓRICO
# ============================================================
@st.cache_data(ttl=300, show_spinner=False)
def informe_desviacion(fecha_i, fecha_f, local):
    if get_engine() is None:
        return pd.DataFrame()

    # Ventas del período — casteamos fechas a string para evitar problemas de tipo con SQLAlchemy
    filtro_local_v = "AND UPPER(local) = UPPER(:l)" if local != "Todos" else ""
    params = {"i": str(fecha_i), "f": str(fecha_f)}
    if local != "Todos":
        params["l"] = local

    q_v = f"""
        SELECT sku_producto, SUM(cantidad_vendida) as cant_vendida
        FROM ventas
        WHERE fecha_venta BETWEEN :i AND :f
        {filtro_local_v}
        GROUP BY 1
    """
    df_v = run_query(q_v, params)

    # Recetario completo
    df_rec = get_recetas()
    if df_rec.empty or df_v.empty:
        return pd.DataFrame()

    # Filtrar opcionales — NULL se trata como 0 (siempre va en el plato)
    df_rec['es_opcion'] = pd.to_numeric(df_rec['es_opcion'], errors='coerce').fillna(0)
    df_rec['cant_real'] = pd.to_numeric(df_rec['cant_real'], errors='coerce').fillna(0)
    df_rec['cant_efic'] = pd.to_numeric(df_rec['cant_efic'], errors='coerce').fillna(0)
    df_rec = df_rec[df_rec['es_opcion'] == 0].copy()  # solo fijos (null→0 por fillna, opciones 1/2/3/5/6 excluidas)

    # Separar directos y procesados
    df_dir  = df_rec[df_rec['es_procesado'] == False].copy()
    df_proc = df_rec[df_rec['es_procesado'] == True].copy()

    # ---- DIRECTOS que no son PRO- ----
    dir_no_pro = df_dir[~df_dir['sku_ingrediente'].str.startswith('PRO-', na=False)].copy()
    merge_dir = pd.merge(df_v, dir_no_pro, left_on='sku_producto', right_on='codigo_venta', how='inner')
    merge_dir['consumo_parcial'] = merge_dir['cant_vendida'] * merge_dir['cant_real']
    dir_out = merge_dir[['sku_ingrediente', 'nombre_ingrediente', 'consumo_parcial']]



    # ---- EXPLOSIÓN PROCESADOS ----
    # Paso 1: platos que usan un PRO- como ingrediente
    dir_pro = df_dir[df_dir['sku_ingrediente'].str.startswith('PRO-', na=False)].copy()
    merge_pro = pd.merge(df_v, dir_pro, left_on='sku_producto', right_on='codigo_venta', how='inner')

    exp_out = pd.DataFrame()
    if not merge_pro.empty and not df_proc.empty:
        # Paso 2: rendimiento total y porcion de cada procesado
        # Usa MAX(rendimiento) si está definido (>1), sino SUM(cant_real)
        rend_exp = df_proc.groupby('codigo_venta').agg(
            rendimiento_explicito=('rendimiento', 'max'),
            rendimiento_suma=('cant_real', 'sum'),
            porcion=('porcion', 'first')
        ).reset_index()
        rend_exp['rendimiento_total'] = rend_exp.apply(
            lambda r: r['rendimiento_explicito'] if pd.notna(r['rendimiento_explicito']) and r['rendimiento_explicito'] > 1
            else r['rendimiento_suma'], axis=1
        )
        rend = rend_exp[['codigo_venta', 'rendimiento_total', 'porcion']]

        # Agregar ventas por codigo_venta + sku_ingrediente (PRO-XX) para evitar iterar fila por fila
        merge_pro_agg = merge_pro.groupby(['codigo_venta', 'sku_ingrediente']).agg(
            cant_vendida=('cant_vendida', 'sum'),
            cant_real=('cant_real', 'first'),
            um_salida=('um_salida', 'first')
        ).reset_index()

        rows = []
        for _, plato_row in merge_pro_agg.iterrows():
            pro_sku    = plato_row['sku_ingrediente']  # PRO-XX
            cant_plato = pd.to_numeric(plato_row['cant_real'], errors='coerce') or 0
            ventas     = pd.to_numeric(plato_row['cant_vendida'], errors='coerce') or 0

            base_rows = df_proc[df_proc['codigo_venta'] == pro_sku]
            if base_rows.empty:
                continue

            rend_row   = rend[rend['codigo_venta'] == pro_sku]
            rend_total = float(rend_row['rendimiento_total'].values[0]) if not rend_row.empty else 1
            porcion    = int(rend_row['porcion'].values[0]) if not rend_row.empty else 0
            if rend_total == 0:
                rend_total = 1

            um_plato = 1
            cant_plato_conv = cant_plato

            for _, base in base_rows.iterrows():
                cant_base = pd.to_numeric(base['cant_real'], errors='coerce') or 0
                if porcion == 1:
                    consumo = ventas * cant_plato_conv * cant_base
                else:
                    consumo = ventas * (cant_plato_conv / rend_total) * cant_base
                rows.append({
                    'sku_ingrediente':    base['sku_ingrediente'],
                    'nombre_ingrediente': base['nombre_ingrediente'],
                    'consumo_parcial':    consumo
                })

        if rows:
            exp_out = pd.DataFrame(rows)



    # ---- CONSOLIDAR ----
    todo = pd.concat([df for df in [dir_out, exp_out] if not df.empty], ignore_index=True)
    cons_teo = todo.groupby('sku_ingrediente').agg(
        consumo_teorico=('consumo_parcial', 'sum'),
        nombre_ingrediente=('nombre_ingrediente', 'first')
    ).reset_index()




    # Compras reales del período — fecha_dte es timestamp, cant_conv ya está en unidades
    filtro_local_c  = "AND UPPER(local) = UPPER(:l)" if local != "Todos" else ""
    filtro_local_c2 = "AND UPPER(c.local) = UPPER(:l)" if local != "Todos" else ""
    params_c = {"i": fecha_i, "f": fecha_f}
    if local != "Todos":
        params_c["l"] = local

    q_c = f"""
        SELECT
            COALESCE(e.sku_receta, c.sku) as sku,
            SUM(c.cant_conv) AS cant_real_comprada,
            AVG(c.muc) AS muc_promedio
        FROM compras c
        LEFT JOIN sku_equivalencias e ON c.sku = e.sku_compra
        WHERE c.fecha_dte::date BETWEEN :i AND :f
          AND c.subcat = 'Directo'
        {filtro_local_c2}
        GROUP BY 1
    """
    df_c = run_query(q_c, params_c)

    # Fallback: si el período no tiene compras, mostrar histórico completo
    if df_c.empty:
        q_c2 = f"""
            SELECT
                COALESCE(e.sku_receta, c.sku) as sku,
                SUM(c.cant_conv) AS cant_real_comprada,
                AVG(c.muc) AS muc_promedio
            FROM compras c
            LEFT JOIN sku_equivalencias e ON c.sku = e.sku_compra
            WHERE c.subcat = 'Directo'
            {filtro_local_c2}
            GROUP BY 1
        """
        df_c = run_query(q_c2, params_c)
        if not df_c.empty:
            st.warning("⚠️ Sin compras en el período seleccionado — mostrando totales históricos.")

    # Equivalencias ya aplicadas en SQL — no necesita remapeo en Python

    # Nombre canónico desde compras — incluir equivalencias para SKUs que solo existen como destino
    q_nom = """
        SELECT sku, MIN(nombre_producto) as nombre_compra
        FROM compras
        WHERE subcat IN ('Directo', 'Indirecto')
        GROUP BY sku
    """
    nombres_compras = run_query(q_nom)
    dict_nombres = dict(zip(nombres_compras['sku'], nombres_compras['nombre_compra'])) if not nombres_compras.empty else {}

    # Fallback de nombres via equivalencias
    df_equiv = get_equivalencias()
    if not df_equiv.empty:
        for _, row in df_equiv.iterrows():
            sku_dest = row['sku_receta']
            sku_orig = row['sku_compra']
            if sku_dest not in dict_nombres and sku_orig in dict_nombres:
                dict_nombres[sku_dest] = dict_nombres[sku_orig]

    # Subcat por SKU (para categorización en informe)
    df_subcat = run_query("""
        SELECT sku, MIN(subcat) as subcat
        FROM compras
        WHERE subcat IN ('Directo','Indirecto')
        GROUP BY sku
    """)
    dict_subcat = dict(zip(df_subcat['sku'], df_subcat['subcat'])) if not df_subcat.empty else {}

    informe = pd.merge(
        cons_teo, df_c,
        left_on='sku_ingrediente', right_on='sku', how='outer'
    )
    informe = informe.fillna(0)

    # Eliminar filas que son SKUs originales ya consolidados via equivalencias
    # (aparecen solo en compras con consumo_teorico=0 porque ya fueron mapeados a su sku_receta)
    skus_compra_equiv = set(df_equiv['sku_compra'].tolist()) if not df_equiv.empty else set()
    informe = informe[~(
        (informe['consumo_teorico'] == 0) &
        (informe['sku'].isin(skus_compra_equiv))
    )]
    informe['subcat'] = informe.apply(
        lambda r: dict_subcat.get(str(r['sku_ingrediente']), dict_subcat.get(str(r['sku']), '')), axis=1
    )

    # SKU final: unificar sku_ingrediente y sku en una sola columna
    informe['sku_final'] = informe.apply(
        lambda r: r['sku_ingrediente'] if r['sku_ingrediente'] not in [0, '', None]
        else r['sku'], axis=1
    )

    # Nombre final: recetario primero, compras como fallback para ingredientes sin receta
    informe['nombre_final'] = informe.apply(
        lambda r: r['nombre_ingrediente']
        if (r['nombre_ingrediente'] not in [0, '', None] and str(r['nombre_ingrediente']).strip() != '')
        else dict_nombres.get(str(r['sku_final']), str(r['sku_final'])), axis=1
    )

    informe['desviacion_cant']   = informe['cant_real_comprada'] - informe['consumo_teorico']
    informe['desviacion_dinero'] = informe['desviacion_cant'] * informe['muc_promedio']

    # Renombrar para consistencia con el resto del informe
    informe['sku_ingrediente']   = informe['sku_final']
    informe['nombre_ingrediente']= informe['nombre_final']

    return informe.sort_values('desviacion_dinero', ascending=False)


# ============================================================
# PERSISTENCIA
# ============================================================
def save_recetario(df_directos, df_procesados):
    engine = get_engine()
    if engine is None:
        return

    df_dir = df_directos.copy()
    df_dir.columns = df_dir.columns.str.strip()
    df_dir = df_dir.rename(columns={
        'CODIGO VENTA': 'codigo_venta', 'Plato': 'nombre_plato',
        'SKU': 'sku_ingrediente', 'Ingrediente': 'nombre_ingrediente',
        'CantReal': 'cant_real', 'Eficiencia': 'rendimiento',
        'UM': 'um_salida', 'EsOpcion': 'es_opcion'
    })
    df_dir['es_procesado'] = False
    df_dir['cant_efic'] = None
    df_dir['porcion'] = 0

    df_proc = df_procesados.copy()
    df_proc.columns = df_proc.columns.str.strip()
    # Detectar columna porcion con cualquier variación de nombre o espacios
    col_porcion = next((c for c in df_proc.columns if c.strip().lower() == 'porcion'), None)
    rename_map = {
        'Codigo Venta': 'codigo_venta', 'Ingrediente Proc': 'nombre_plato',
        'SKU Ingrediente': 'sku_ingrediente', 'Ingrediente': 'nombre_ingrediente',
        'CantReceta': 'cant_real', 'CantEfic': 'cant_efic',
        'UM Salida': 'um_salida', 'Eficiencia': 'rendimiento'
    }
    if col_porcion:
        rename_map[col_porcion] = 'porcion'
    df_proc = df_proc.rename(columns=rename_map)
    df_proc['es_procesado'] = True
    df_proc['es_opcion'] = 0
    if 'porcion' not in df_proc.columns:
        df_proc['porcion'] = 0

    cols_base = ['codigo_venta', 'nombre_plato', 'sku_ingrediente', 'nombre_ingrediente',
                 'cant_real', 'cant_efic', 'rendimiento', 'um_salida', 'es_procesado', 'es_opcion', 'porcion']

    df_final = pd.concat([df_dir, df_proc], ignore_index=True)
    cols = [c for c in cols_base if c in df_final.columns]
    df_final['rendimiento'] = pd.to_numeric(df_final['rendimiento'], errors='coerce').fillna(1)
    df_final['cant_real'] = pd.to_numeric(df_final['cant_real'], errors='coerce').fillna(0)
    df_final['cant_efic'] = pd.to_numeric(df_final['cant_efic'], errors='coerce').fillna(0)

    # Consolidar duplicados: mismo ingrediente en el mismo plato → sumar cantidades
    df_final = df_final[cols].copy()
    agg_dict = {
        'nombre_plato':      'first',
        'nombre_ingrediente':'first',
        'cant_real':         'sum',
        'cant_efic':         'sum',
        'rendimiento':       'first',
        'um_salida':         'first',
        'es_opcion':         'first'
    }
    if 'porcion' in df_final.columns:
        agg_dict['porcion'] = 'first'

    df_agg = df_final.groupby(
        ['codigo_venta', 'sku_ingrediente', 'es_procesado'],
        as_index=False
    ).agg(agg_dict)

    # cols final solo con columnas que existen en df_agg
    cols = [c for c in cols_base if c in df_agg.columns]

    duplicados = len(df_final) - len(df_agg)
    if duplicados > 0:
        st.warning(f"⚠️ Se consolidaron {duplicados} filas duplicadas (mismo SKU en mismo plato).")

    try:
        with engine.connect() as conn:
            conn.execute(text("DROP VIEW IF EXISTS vista_costo_recetas CASCADE"))
            conn.commit()
        df_agg[cols].to_sql('recetas', engine, if_exists='replace', index=False)
        st.success(f"✅ Recetario sincronizado — {len(df_agg)} filas únicas cargadas.")
    except Exception as e:
        st.error(f"Error al guardar recetario: {e}")


# ============================================================
# PROCESADO DE COMPRAS
# ============================================================

TASAS_IMP_ADIC = {
    '271': 0.18,
    '27':  0.10,
    '26':  0.21,
    '25':  0.21,
    '24':  0.3155,
    '19':  0.12,
    '18':  0.05,
}

# Columnas mínimas que debe traer el archivo fuente
COLS_REQUERIDAS = [
    'local', 'fecha_dte', 'rut_proveedor', 'nombre_proveedor',
    'tipo_dte', 'folio', 'nombre_producto',
    'cantidad', 'total_item', 'codigo_impuesto', 'iva',
    'descuento_global', 'recargo_global', 'total',
    'sku', 'subcat', 'conversion', 'formato', 'categoria_producto',
]

def _normalizar_columnas(df: pd.DataFrame) -> pd.DataFrame:
    """Limpia y normaliza los nombres de columna del Excel fuente."""
    df = df.copy()
    df.columns = (
        df.columns
        .str.strip()
        .str.lower()
        .str.replace(r'[\s]+', '_', regex=True)
        .str.replace(r'[áàä]', 'a', regex=True)
        .str.replace(r'[éèë]', 'e', regex=True)
        .str.replace(r'[íìï]', 'i', regex=True)
        .str.replace(r'[óòö]', 'o', regex=True)
        .str.replace(r'[úùü]', 'u', regex=True)
        .str.replace(r'[^a-z0-9_]', '_', regex=True)
    )
    # Mapear columnas _res del formato nuevo del robot
    res_map = {
        'sku':               'sku_res',
        'subcat':            'subcat_res',
        'conversion':        'conversion_res',
        'formato':           'formato_res',
        'categoria_producto':'categoria_res',
    }
    for canonical, src in res_map.items():
        if src in df.columns and canonical not in df.columns:
            df = df.rename(columns={src: canonical})

    # Si no viene columna 'local' pero sí 'rut_empresa', derivar local desde RUT
    if 'local' not in df.columns and 'rut_empresa' in df.columns:
        _RUT_LOCAL = {
            '76376098-7': 'Providencia',
            '76439807-6': 'Vitacura',
            '76450253-1': 'La Dehesa',
            '77009575-1': 'Las Condes',
            '77116729-2': 'Chicureo',
            '77531748-5': 'Macul',
            '77726513-K': 'La Reina',
            '77773363-K': 'Quilin',
            '77887201-3': 'Nueva Providencia',
            '77847982-6': 'Los Trapenses',
        }
        df['local'] = df['rut_empresa'].astype(str).str.strip().map(_RUT_LOCAL)

    # Alias frecuentes
    aliases = {
        'categoria_producto': ['categoria_producto', 'categoria producto', 'categoria'],
        'recargo_global':     ['recargo_global', 'recargo global', 'recargo_global'],
        'descuento_global':   ['descuento_global', 'descuento global', 'descuento_global'],
        'codigo_impuesto':    ['codigo_impuesto', 'codigo impuesto', 'cod_impuesto'],
        'iva':                ['iva', 'iva_'],
        'total':              ['total', 'total_'],
    }
    for canonical, variants in aliases.items():
        for v in variants:
            v_norm = v.replace(' ', '_')
            if v_norm in df.columns and canonical not in df.columns:
                df = df.rename(columns={v_norm: canonical})
    return df


def procesar_compras(df_raw: pd.DataFrame) -> tuple[pd.DataFrame, list[str]]:
    """
    Recibe el DataFrame crudo del Excel de compras y devuelve
    (df_procesado, lista_de_advertencias).

    Columnas calculadas:
        cant_conv       = cantidad × conversion
        monto_real      = total_item  (negativo si tipo_dte == 61)
        recargo2        = (Recargo_Global - Descuento_Global) × participación línea en folio
        total_neto2     = monto_real + recargo2
        imp_adic        = monto_real × tasa según codigo_impuesto
        IVA_2           = total_neto2 × 0.19  (0 si IVA del folio == 0)
        tootal2         = total_neto2 + imp_adic + IVA_2
        costo_realfinal = tootal2 + despacho_distribuido + ajuste_redondeo  (0 en líneas de despacho)
        MUC             = costo_realfinal / (cant_conv × formato)
                          si formato == 1 → MUC = costo_realfinal / cant_conv
    """
    warnings = []
    df = _normalizar_columnas(df_raw)

    # ── Verificar columnas mínimas ──────────────────────────────────────────
    # ── Normalización de nombres de local ────────────────────────────────
    _LOCAL_ALIAS_C = {
        'pedro de valdivia': 'Providencia',
        'providencia':       'Providencia',
    }
    if 'local' in df.columns:
        df['local'] = df['local'].apply(
            lambda x: _LOCAL_ALIAS_C.get(str(x).strip().lower(), str(x).strip()) if pd.notna(x) else x
        )

    faltantes = [c for c in COLS_REQUERIDAS if c not in df.columns]
    if faltantes:
        warnings.append(
            f"⚠️ Columnas no encontradas tras normalizar nombres: **{', '.join(faltantes)}**\n"
            f"Columnas recibidas: {', '.join(df.columns.tolist())}"
        )
    # Columnas críticas para el cálculo — si faltan el resultado será incorrecto
    criticas = {
        'total_item':       'monto_real será 0',
        'recargo_global':   'recargo2 será 0 (no se distribuye recargo)',
        'descuento_global': 'descuento no se aplicará',
        'iva':              'IVA_2 será 0 en todos los folios',
        'total':            'no se podrá ajustar redondeo ni distribuir despacho',
        'conversion':       'cant_conv = cantidad (sin conversión)',
        'formato':          'MUC calculado como por unidad en todos los casos',
    }
    for col, impacto in criticas.items():
        if col not in df.columns:
            warnings.append(f"🔴 Columna crítica **'{col}'** no encontrada → {impacto}")

    # ── Tipos básicos ────────────────────────────────────────────────────────
    def _col(df, col, default):
        return df[col] if col in df.columns else pd.Series([default] * len(df), index=df.index)

    df['tipo_dte']        = pd.to_numeric(_col(df, 'tipo_dte', 33), errors='coerce').fillna(33).astype(int)
    df['total_item']      = pd.to_numeric(_col(df, 'total_item', 0), errors='coerce').fillna(0)
    df['cantidad']        = pd.to_numeric(_col(df, 'cantidad', 1), errors='coerce').fillna(1)
    df['conversion']      = pd.to_numeric(_col(df, 'conversion', 1), errors='coerce').fillna(1)
    df['formato']         = pd.to_numeric(_col(df, 'formato', 1), errors='coerce').fillna(1)
    df['recargo_global']  = pd.to_numeric(_col(df, 'recargo_global', 0), errors='coerce').fillna(0)
    df['descuento_global']= pd.to_numeric(_col(df, 'descuento_global', 0), errors='coerce').fillna(0)
    df['iva']             = pd.to_numeric(_col(df, 'iva', 0), errors='coerce').fillna(0)
    df['total']           = pd.to_numeric(_col(df, 'total', 0), errors='coerce').fillna(0)
    # Para NC (tipo_dte=61) el total del folio debe ser negativo igual que monto_real
    df['total']           = np.where(df['tipo_dte'] == 61, -df['total'].abs(), df['total'])

    # ── PASO 1: cant_conv ────────────────────────────────────────────────────
    df['cant_conv'] = df['cantidad'] * df['conversion']

    # ── PASO 2: monto_real ───────────────────────────────────────────────────
    df['monto_real'] = np.where(df['tipo_dte'] == 61, -df['total_item'], df['total_item'])

    # ── PASO 3: recargo2  (distribución proporcional por folio) ─────────────
    # participación = monto_real_línea / suma_monto_real_folio
    df['_tot_folio'] = df.groupby(['folio','rut_proveedor'])['monto_real'].transform('sum')
    df['_recargo_neto'] = df['recargo_global'] - df['descuento_global']
    df['_part'] = np.where(df['_tot_folio'] != 0, df['monto_real'] / df['_tot_folio'], 0)
    df['recargo2'] = df['_part'] * df['_recargo_neto']
    df['total_neto2'] = df['monto_real'] + df['recargo2']

    # ── PASO 4: imp_adic ─────────────────────────────────────────────────────
    cod_str = (
        df.get('codigo_impuesto', pd.Series([''] * len(df)))
        .fillna('')
        .astype(str)
        .str.strip()
        .str.replace(r'\.0$', '', regex=True)
        .str.replace(r'^nan$', '', regex=True)
    )
    tasa = cod_str.map(TASAS_IMP_ADIC).fillna(0)
    df['imp_adic'] = df['monto_real'] * tasa

    # ── PASO 5: IVA_2  (por folio: si el folio tiene IVA registrado > 0) ────
    df['_tiene_iva'] = df.groupby(['folio','rut_proveedor'])['iva'].transform('max') != 0
    df['iva_2'] = np.where(df['_tiene_iva'], df['total_neto2'] * 0.19, 0)

    # ── PASO 6: tootal2 ──────────────────────────────────────────────────────
    df['tootal2'] = df['total_neto2'] + df['imp_adic'] + df['iva_2']

    # ── PASO 7: identificar líneas de despacho ───────────────────────────────
    nombre_lower = df['nombre_producto'].str.lower().fillna('')
    df['_es_despacho'] = (
        nombre_lower.str.contains('despacho',    na=False) |
        nombre_lower.str.contains('flete',       na=False) |
        nombre_lower.str.contains('distribucion',na=False) |
        nombre_lower.str.contains('envio',       na=False) |
        nombre_lower.str.contains('envío',       na=False)
    )

    # ── PASO 8: Desp_Folio = suma(tootal2 de líneas despacho) ───────────────
    df['_desp_linea'] = np.where(df['_es_despacho'], df['tootal2'], 0)
    df['_desp_folio'] = df.groupby(['folio','rut_proveedor'])['_desp_linea'].transform('sum')

    # ── PASO 9: ajuste redondeo = Total_factura - suma(tootal2) del folio ────
    df['_suma_tootal2_folio'] = df.groupby(['folio','rut_proveedor'])['tootal2'].transform('sum')
    df['_total_factura']      = df.groupby(['folio','rut_proveedor'])['total'].transform('max')
    df['_diferencia']         = df['_total_factura'] - df['_suma_tootal2_folio']

    # desp+red2 por folio = Desp_Folio + diferencia
    df['_desp_red2'] = df['_desp_folio'] + df['_diferencia']

    # ── PASO 10: Part_Item (excluye despachos del denominador) ───────────────
    df['_monto_limpio'] = np.where(df['_es_despacho'], 0, df['monto_real'].abs())
    df['_tot_limpio_folio'] = df.groupby(['folio','rut_proveedor'])['_monto_limpio'].transform('sum')
    df['_part_item'] = np.where(
        df['_tot_limpio_folio'] != 0,
        df['_monto_limpio'] / df['_tot_limpio_folio'],
        0
    )

    # ── PASO 11: dist_desp = part_item × desp_red2  (redondeado a entero) ───
    df['_dist_desp'] = (df['_part_item'] * df['_desp_red2']).round(0)

    # ── PASO 12: costo_realfinal ─────────────────────────────────────────────
    df['costo_realfinal'] = np.where(
        df['_es_despacho'],
        0,
        df['tootal2'] + df['_dist_desp']
    )

    # ── PASO 13: MUC ─────────────────────────────────────────────────────────
    denominador = np.where(
        df['formato'] == 1,
        df['cant_conv'],
        df['cant_conv'] * df['formato']
    )
    df['muc'] = np.where(
        (denominador != 0) & (~df['_es_despacho']),
        df['costo_realfinal'] / denominador,
        0
    )

    # ── Limpiar columnas temporales ──────────────────────────────────────────
    cols_temp = [c for c in df.columns if c.startswith('_')]
    df = df.drop(columns=cols_temp)

    # ── Renombrar IVA_2 para consistencia con BD ─────────────────────────────
    df = df.rename(columns={'iva_2': 'iva_2'})  # ya en minúsculas

    # ── Advertencias sobre datos ─────────────────────────────────────────────
    sin_sku = df['sku'].isna().sum() if 'sku' in df.columns else 0
    if sin_sku > 0:
        warnings.append(f"⚠️ {sin_sku} líneas sin SKU asignado.")
    sin_conv = (df['conversion'] == 0).sum()
    if sin_conv > 0:
        warnings.append(f"⚠️ {sin_conv} líneas con Conversion = 0.")

    return df, warnings


def recalcular_folios(df: pd.DataFrame, folios: list) -> pd.DataFrame:
    """Re-runs the financial calculation pipeline for specific folios in-place.
    Used after correcting conversion/formato for unmatched rows.
    """
    import numpy as np
    mask = df['folio'].isin(folios)
    if not mask.any():
        return df

    df = df.copy()
    d = df[mask].copy()

    # Recalculate cant_conv and MUC with corrected conversion/formato
    d['cantidad']   = pd.to_numeric(d['cantidad'],   errors='coerce').fillna(1)
    d['conversion'] = pd.to_numeric(d['conversion'], errors='coerce').fillna(1)
    d['formato']    = pd.to_numeric(d['formato'],    errors='coerce').fillna(1)
    d['total_item'] = pd.to_numeric(d['total_item'], errors='coerce').fillna(0)
    d['recargo_global']   = pd.to_numeric(d.get('recargo_global',   pd.Series([0]*len(d))), errors='coerce').fillna(0)
    d['descuento_global'] = pd.to_numeric(d.get('descuento_global', pd.Series([0]*len(d))), errors='coerce').fillna(0)
    d['iva']   = pd.to_numeric(d.get('iva',   pd.Series([0]*len(d))), errors='coerce').fillna(0)
    d['total'] = pd.to_numeric(d.get('total', pd.Series([0]*len(d))), errors='coerce').fillna(0)

    d['cant_conv']  = d['cantidad'] * d['conversion']
    d['monto_real'] = np.where(d['tipo_dte'] == 61, -d['total_item'], d['total_item'])

    d['_tot_folio']   = d.groupby(['folio','rut_proveedor'])['monto_real'].transform('sum')
    d['_recargo_neto']= d['recargo_global'] - d['descuento_global']
    d['_part']        = np.where(d['_tot_folio'] != 0, d['monto_real'] / d['_tot_folio'], 0)
    d['recargo2']     = d['_part'] * d['_recargo_neto']
    d['total_neto2']  = d['monto_real'] + d['recargo2']

    cod_str = d.get('codigo_impuesto', pd.Series([''] * len(d))).fillna('').astype(str).str.strip()
    cod_str = cod_str.str.replace(r'\.0$', '', regex=True).str.replace(r'^nan$', '', regex=True)
    tasa = cod_str.map(TASAS_IMP_ADIC).fillna(0)
    d['imp_adic'] = d['monto_real'] * tasa

    d['_tiene_iva'] = d.groupby(['folio','rut_proveedor'])['iva'].transform('max') != 0
    d['iva_2']   = np.where(d['_tiene_iva'], d['total_neto2'] * 0.19, 0)
    d['tootal2'] = d['total_neto2'] + d['imp_adic'] + d['iva_2']

    nombre_lower = d['nombre_producto'].str.lower().fillna('')
    d['_es_despacho'] = (
        nombre_lower.str.contains('despacho',    na=False) |
        nombre_lower.str.contains('flete',       na=False) |
        nombre_lower.str.contains('distribucion',na=False) |
        nombre_lower.str.contains('envio',       na=False) |
        nombre_lower.str.contains('envío',       na=False)
    )

    d['_desp_linea']        = np.where(d['_es_despacho'], d['monto_real'] * 1.19, 0)
    d['_desp_folio']        = d.groupby(['folio','rut_proveedor'])['_desp_linea'].transform('sum')
    d['_suma_tootal2_folio']= d.groupby(['folio','rut_proveedor'])['tootal2'].transform('sum')
    d['_total_factura']     = d.groupby(['folio','rut_proveedor'])['total'].transform('max')
    d['_diferencia']        = d['_total_factura'] - d['_suma_tootal2_folio']
    d['_desp_red2']         = d['_desp_folio'] + d['_diferencia']
    d['_monto_limpio']      = np.where(d['_es_despacho'], 0, d['monto_real'].abs())
    d['_tot_limpio_folio']  = d.groupby(['folio','rut_proveedor'])['_monto_limpio'].transform('sum')
    d['_part_item']         = np.where(d['_tot_limpio_folio'] != 0, d['_monto_limpio'] / d['_tot_limpio_folio'], 0)
    d['_dist_desp']         = (d['_part_item'] * d['_desp_red2']).round(0)

    d['costo_realfinal'] = np.where(d['_es_despacho'], 0, d['tootal2'] + d['_dist_desp'])

    denominador = np.where(d['formato'] == 1, d['cant_conv'], d['cant_conv'] * d['formato'])
    d['muc'] = np.where((denominador != 0) & (~d['_es_despacho']), d['costo_realfinal'] / denominador, 0)

    cols_temp = [c for c in d.columns if c.startswith('_')]
    d = d.drop(columns=cols_temp)

    df.loc[mask, d.columns] = d.values
    return df


def save_compras(df: pd.DataFrame):
    """Guarda el DataFrame ya procesado en la tabla compras de Supabase.
    Elimina previamente los registros del mismo período y locales
    para evitar duplicados al recargar.
    """
    engine = get_engine()
    if engine is None:
        return
    cols_req = [
        'local', 'fecha_dte', 'rut_proveedor', 'nombre_proveedor', 'tipo_dte',
        'folio', 'nombre_producto', 'sku', 'subcat', 'codigo_impuesto',
        'cantidad', 'conversion', 'formato', 'categoria_producto',
        'cant_conv', 'monto_real', 'recargo2', 'total_neto2',
        'imp_adic', 'iva_2', 'tootal2', 'costo_realfinal', 'muc', 'total'
    ]
    cols_ok = [c for c in cols_req if c in df.columns]
    try:
        # Detectar rango de fechas y locales del archivo a cargar
        fechas = pd.to_datetime(df['fecha_dte'], errors='coerce').dropna()
        if fechas.empty:
            st.error("No se pudo determinar el período del archivo.")
            return
        fecha_min = fechas.min().date()
        fecha_max = fechas.max().date()
        locales   = df['local'].dropna().unique().tolist() if 'local' in df.columns else []

        with engine.connect() as conn:
            if locales:
                conn.execute(text("""
                    DELETE FROM compras
                    WHERE fecha_dte::date BETWEEN :fi AND :ff
                      AND local = ANY(:locales)
                """), {'fi': fecha_min, 'ff': fecha_max, 'locales': locales})
            else:
                conn.execute(text("""
                    DELETE FROM compras
                    WHERE fecha_dte::date BETWEEN :fi AND :ff
                """), {'fi': fecha_min, 'ff': fecha_max})
            conn.commit()

        total = len(df)
        with st.spinner(f"Insertando {total:,} registros..."):
            df[cols_ok].to_sql('compras', engine, if_exists='append',
                               index=False, method='multi', chunksize=500)

        st.success(f"✅ {total:,} registros guardados ({fecha_min} → {fecha_max}).")
    except Exception as e:
        st.error(f"Error al guardar compras: {e}")


def save_ventas(df_raw):
    engine = get_engine()
    if engine is None:
        return

    df = df_raw.copy()
    # Si viene como string único (CSV con sep=;), re-parsear
    if len(df.columns) == 1 and ';' in str(df.columns[0]):
        import io as _io
        raw_bytes = df_raw.to_csv(index=False).encode()
        df = pd.read_csv(_io.BytesIO(raw_bytes), sep=';', dtype=str)
    df.columns = df.columns.str.strip()

    mapeo = {
        'ID de orden': 'id_orden', 'ID Producto': 'sku_producto',
        'Nombre': 'nombre_producto', 'Cantidad': 'cantidad_vendida',
        'Precio a Pagar': 'precio_pagar', 'Precio Base': 'precio_base',
        'Costo': 'costo_receta', 'Descuento': 'descuento', 'Impuesto': 'impuesto',
        'AB.': 'ab_categoria',
        'Categorias de Productos/Platos': 'categoria_menu',
        'Categorías de Productos/Platos': 'categoria_menu',
        'BA.': 'ba_opcion',
        'Jerarquia de Extras': 'jerarquia_extras',
        'Jerarquía de Extras': 'jerarquia_extras',
        'AC.': 'ac_excepcion',
        'Jerarquia de Excp.': 'jerarquia_excepcion',
        'Jerarquía de Excp.': 'jerarquia_excepcion',
        'Local': 'local', 'fechahora_pedido': 'fecha_pedido',
        'fechahora_creacion': 'fecha_creacion', 'fechahora_cierre': 'fecha_cierre',
        'Nombre de mesa': 'mesa', 'Sector': 'sector', 'Origen': 'origen',
        'Nombre garzon apertura': 'garzon', 'Nombre garzón apertura': 'garzon',
        'Folio': 'folio', 'Forma de Pago': 'forma_pago',
        'Nombre Lista Precio': 'lista_precio',
        # Columnas nuevas
        'Numero de clientes': 'num_clientes',
        'Número de clientes': 'num_clientes',
        'Capacidad de la mesa': 'capacidad_mesa',
        'Impuestos totales': 'impuestos_totales',
        'Pago total': 'pago_total',
        'Pagos': 'pago',
        'ID Caja': 'id_caja',
        'Nombre de la caja': 'nombre_caja',
        'Total con propina': 'total_con_propina',
        'ID de Pago': 'id_pago',
        'Valor de boleta': 'valor_boleta',
        'Tipo de documento': 'tipo_documento',
        'Descuentos': 'descuentos',
        'Total a pagar': 'total_a_pagar',
        'Propina': 'propina',
        'Pagado': 'pagado',
        'Cambio': 'cambio',
        'Diferencia a favor': 'diferencia_favor',
        'Formas de pago': 'formas_pago',
        'Valor': 'valor',
        'Precio Lista': 'precio_lista',
        'Precio Turno': 'precio_turno',
        'Productos': 'productos',
        # Compatibilidad formato anterior
        'fecha_pura': 'fecha_pedido', 'cat_menu': 'categoria_menu',
        'id_producto': 'sku_producto', 'cantidad': 'cantidad_vendida',
        'venta_real': 'precio_pagar',
    }
    df = df.rename(columns={k: v for k, v in mapeo.items() if k in df.columns})

    # Fecha venta
    fecha_col = next((c for c in ['fecha_pedido','fecha_creacion','Fecha Pedido','Fecha de creacion']
                      if c in df.columns), None)
    if fecha_col:
        df['fecha_venta'] = pd.to_datetime(
            df[fecha_col].astype(str).str[:10], errors='coerce').dt.date
    elif 'fecha_venta' not in df.columns:
        st.error("No se encontró columna de fecha."); return

    df = df.dropna(subset=['fecha_venta', 'sku_producto'])
    df = df[df['sku_producto'].astype(str).str.strip() != '']

    if 'precio_pagar' in df.columns and 'monto_venta_real' not in df.columns:
        _precio = pd.to_numeric(df['precio_pagar'], errors='coerce').fillna(0)
        _desc   = pd.to_numeric(df['descuento'], errors='coerce').fillna(0) if 'descuento' in df.columns else 0
        df['monto_venta_real'] = _precio - _desc

    for col in ['cantidad_vendida','monto_venta_real','precio_base','costo_receta','descuento','impuesto',
                'pago_total','valor_boleta','total_a_pagar','propina','pagado','cambio',
                'diferencia_favor','valor','precio_lista','precio_turno','impuestos_totales','descuentos']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce').fillna(0)

    # Integer columns — vienen como '1.0', convertir a Int64 nullable
    for col in ['num_clientes','capacidad_mesa','id_caja']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce').round(0).astype('Int64')

    if 'ba_opcion' in df.columns:
        df['es_opcion'] = df['ba_opcion'].notna() & (df['ba_opcion'].astype(str).str.strip() != '')
    else:
        df['es_opcion'] = False

    cols_bd = ['fecha_venta','id_orden','sku_producto','nombre_producto',
               'cantidad_vendida','monto_venta_real','precio_base',
               'costo_receta','descuento','impuesto',
               'ab_categoria','categoria_menu','ba_opcion','jerarquia_extras',
               'ac_excepcion','jerarquia_excepcion','es_opcion',
               'local','mesa','sector','origen','garzon',
               'folio','forma_pago','lista_precio',
               'fecha_pedido','fecha_creacion','fecha_cierre',
               'num_clientes','capacidad_mesa','impuestos_totales','pago_total','pago',
               'id_caja','nombre_caja','total_con_propina','id_pago','valor_boleta',
               'tipo_documento','descuentos','total_a_pagar','propina','pagado','cambio',
               'diferencia_favor','formas_pago','valor','precio_lista','precio_turno',
               'productos']
    cols_ok = [c for c in cols_bd if c in df.columns]
    df_save = df[cols_ok].copy()

    # ── Normalización de nombres de local ────────────────────────────────────
    LOCAL_ALIAS = {
        'pedro de valdivia': 'Providencia',
        'providencia':       'Providencia',
    }
    if 'local' in df_save.columns:
        df_save['local'] = df_save['local'].apply(
            lambda x: LOCAL_ALIAS.get(str(x).strip().lower(), str(x).strip()) if pd.notna(x) else x
        )

    try:
        fechas    = pd.to_datetime(df_save['fecha_venta'].astype(str), errors='coerce').dropna()
        fecha_min = fechas.min().date()
        fecha_max = fechas.max().date()
        locales   = df_save['local'].dropna().unique().tolist() if 'local' in df_save.columns else []

        # Fechas exactas del archivo — DELETE solo por los días que trae el archivo
        fechas_archivo = [str(f) for f in fechas.dt.date.unique().tolist()]

        with engine.connect() as conn:
            # Construir IN dinámico con cast explícito a date
            _f_placeholders = ','.join([f"'{f}'::date" for f in fechas_archivo])
            if locales:
                conn.execute(text(
                    f"DELETE FROM ventas WHERE fecha_venta IN ({_f_placeholders}) AND local = ANY(:locales)"),
                    {'locales': locales})
            else:
                conn.execute(text(
                    f"DELETE FROM ventas WHERE fecha_venta IN ({_f_placeholders})"))
            conn.commit()

        df_save.to_sql('ventas', engine, if_exists='append', index=False)
        st.success(f"✅ {len(df_save):,} registros guardados ({fecha_min} → {fecha_max}). {len(fechas_archivo)} día(s) reemplazado(s).")
    except Exception as e:
        st.error(f"Error al guardar ventas: {e}")
        st.exception(e)


