def get_locales():
    # Lista fija — evita un DISTINCT pesado sobre la tabla ventas en cada carga
    return ["Todos", "Vitacura", "Las Condes", "Chicureo", "La Dehesa",
            "Macul", "La Reina", "Quilin", "Nueva Providencia",
            "Providencia", "Los Trapenses"]

