LOGO_PATH = '/mount/src/mi-costeo/Logo_AE.jpg'

# ============================================================
# HELPER REUTILIZABLE: Query de variación de precios
# Precio unitario = SUM(costo_realfinal) / SUM(cant_conv)
#   → expresa el precio en la unidad real del SKU (Kg, L, Un)
#   → impacto = cant_base × precio  (sin × formato)
# ============================================================
def _calc_corte_dias(fi_str, ff_str, filtro_local=''):
    """
    Calcula el corte de fechas normalizado por días de compra.
    Retorna (corte_base, corte_comp, n_dias_min, nota) donde:
    - corte_base / corte_comp son strings YYYY-MM-DD del último día a incluir
    - n_dias_min es el mínimo de días con compras entre ambos meses
    - nota es un string descriptivo del ajuste (vacío si no hubo ajuste)
    """
    from sqlalchemy import text as _text
    q = f"""
        SELECT
            DATE_TRUNC('month', fecha_dte::date)::date          AS mes,
            COUNT(DISTINCT fecha_dte::date)                      AS n_dias,
            ARRAY_AGG(DISTINCT fecha_dte::date ORDER BY fecha_dte::date) AS dias
        FROM compras
        WHERE fecha_dte::date BETWEEN '{fi_str}' AND '{ff_str}'
          AND UPPER(COALESCE(categoria_producto,'')) NOT LIKE '%ART%LIMPIEZA%' AND UPPER(COALESCE(categoria_producto,'')) NOT LIKE '%ADMINISTR%' AND UPPER(COALESCE(subcat,'')) NOT IN ('NO VENDIBLE','NO VENDIBLES')
          AND costo_realfinal > 0
          {filtro_local}
        GROUP BY 1
    """
    df_d = run_query(q)
    if df_d.empty:
        return fi_str, ff_str, None, ''

    # Extraer meses extremos
    import pandas as pd
    fi_date = pd.Timestamp(fi_str).date()
    ff_mes  = pd.Timestamp(ff_str).replace(day=1).date()

    row_i = df_d[df_d['mes'] == fi_date]
    row_f = df_d[df_d['mes'] == ff_mes]

    n_i = int(row_i['n_dias'].values[0]) if len(row_i) else 0
    n_f = int(row_f['n_dias'].values[0]) if len(row_f) else 0

    if n_i == 0 or n_f == 0:
        return fi_str, ff_str, None, ''

    n_min = min(n_i, n_f)

    def nth_day(dias_arr, n):
        dias = sorted([pd.Timestamp(d).date() for d in dias_arr])
        return dias[min(n - 1, len(dias) - 1)]

    corte_i = str(nth_day(row_i['dias'].values[0], n_min))
    corte_f = str(nth_day(row_f['dias'].values[0], n_min))

    nota = ''
    if n_i != n_f:
        mes_menor = pd.Timestamp(fi_str).strftime('%B %Y').capitalize() if n_f < n_i \
                    else pd.Timestamp(ff_str).strftime('%B %Y').capitalize()
        nota = f"⚖️ Ajustado a {n_min} días de compra (menor: {mes_menor})"

    return corte_i, corte_f, n_min, nota


def _build_variacion_query(fecha_base_i, fecha_base_f,
                            fecha_comp_i, fecha_comp_f,
                            filtro_cat="", filtro_local="",
                            corte_base=None, corte_comp=None,
                            fecha_cant_i=None, fecha_cant_f=None):
    """
    Construye la query SQL del Informe de Variación de Precios.

    Precio unitario = SUM(costo_realfinal) / NULLIF(SUM(cant_conv * formato), 0)

    Parámetros
    ----------
    fecha_base_i / fecha_base_f : str  YYYY-MM-DD  mes de precios de referencia
    fecha_comp_i / fecha_comp_f : str  YYYY-MM-DD  mes de precios de comparación
    fecha_cant_i / fecha_cant_f : str  YYYY-MM-DD  mes de cantidades (si None usa fecha_base)
    filtro_cat   : str  fragmento SQL adicional
    filtro_local : str  fragmento SQL adicional
    corte_base / corte_comp : str  YYYY-MM-DD  fecha límite (ajuste de días)
    """
    _fb_f   = corte_base  if corte_base  else fecha_base_f
    _fc_f   = corte_comp  if corte_comp  else fecha_comp_f
    # Mes de cantidades: si se especifica uno distinto, las cantidades vienen de ahí
    _cant_i = fecha_cant_i if fecha_cant_i else fecha_base_i
    _cant_f = fecha_cant_f if fecha_cant_f else fecha_base_f
    _cant_diferente = (fecha_cant_i is not None and fecha_cant_i != fecha_base_i)

    if _cant_diferente:
        # Canasta fija: cantidades de un mes, precios de otro
        return f"""
        WITH equiv AS (
            SELECT sku_compra, sku_receta FROM sku_equivalencias
        ),
        -- Cantidades fijas del mes base de cantidades (ej: enero)
        cant AS (
            SELECT
                COALESCE(e.sku_receta, c.sku)                              AS sku,
                c.formato,
                MIN(c.nombre_producto)                                     AS nombre,
                MIN(c.nombre_proveedor)                                    AS proveedor,
                MIN(c.categoria_producto)                                  AS categoria,
                MAX(c.conversion)                                          AS conversion,
                SUM(c.cant_conv * NULLIF(c.formato, 0))                   AS cant_base
            FROM compras c
            LEFT JOIN equiv e ON c.sku = e.sku_compra
            WHERE c.fecha_dte::date BETWEEN '{_cant_i}' AND '{_cant_f}'
              AND UPPER(COALESCE(c.categoria_producto,'')) NOT LIKE '%ART%LIMPIEZA%' AND UPPER(COALESCE(c.categoria_producto,'')) NOT LIKE '%ADMINISTR%' AND UPPER(COALESCE(c.subcat,'')) NOT IN ('NO VENDIBLE','NO VENDIBLES')
              AND c.costo_realfinal > 0 AND c.monto_real > 0 AND c.cant_conv > 0
              AND c.id NOT IN (SELECT compra_id FROM compras_excluidas)
              {filtro_cat}
              {filtro_local}
            GROUP BY 1, 2
        ),
        -- Precios del mes de referencia (inicio)
        precio_ref AS (
            SELECT
                COALESCE(e.sku_receta, c.sku)                              AS sku,
                c.formato,
                SUM(c.costo_realfinal) / NULLIF(SUM(c.cant_conv * NULLIF(c.formato, 0)), 0) AS precio_base
            FROM compras c
            LEFT JOIN equiv e ON c.sku = e.sku_compra
            WHERE c.fecha_dte::date BETWEEN '{fecha_base_i}' AND '{_fb_f}'
              AND UPPER(COALESCE(c.categoria_producto,'')) NOT LIKE '%ART%LIMPIEZA%' AND UPPER(COALESCE(c.categoria_producto,'')) NOT LIKE '%ADMINISTR%' AND UPPER(COALESCE(c.subcat,'')) NOT IN ('NO VENDIBLE','NO VENDIBLES')
              AND c.costo_realfinal > 0 AND c.monto_real > 0 AND c.cant_conv > 0
              AND c.id NOT IN (SELECT compra_id FROM compras_excluidas)
              {filtro_local}
            GROUP BY 1, 2
        ),
        -- Precios del mes de comparación (término)
        comp AS (
            SELECT
                COALESCE(e.sku_receta, c.sku)                              AS sku,
                c.formato,
                SUM(c.costo_realfinal) / NULLIF(SUM(c.cant_conv * NULLIF(c.formato, 0)), 0) AS precio_comp
            FROM compras c
            LEFT JOIN equiv e ON c.sku = e.sku_compra
            WHERE c.fecha_dte::date BETWEEN '{fecha_comp_i}' AND '{_fc_f}'
              AND UPPER(COALESCE(c.categoria_producto,'')) NOT LIKE '%ART%LIMPIEZA%' AND UPPER(COALESCE(c.categoria_producto,'')) NOT LIKE '%ADMINISTR%' AND UPPER(COALESCE(c.subcat,'')) NOT IN ('NO VENDIBLE','NO VENDIBLES')
              AND c.costo_realfinal > 0 AND c.monto_real > 0 AND c.cant_conv > 0
              AND c.id NOT IN (SELECT compra_id FROM compras_excluidas)
              {filtro_local}
            GROUP BY 1, 2
        )
        SELECT
            ca.sku, ca.nombre, ca.proveedor, ca.categoria,
            ca.formato, ca.conversion, ca.cant_base,
            pr.precio_base,
            c.precio_comp,
            ca.cant_base * pr.precio_base                              AS impacto_base,
            ca.cant_base * COALESCE(c.precio_comp, pr.precio_base)    AS impacto_comp
        FROM cant ca
        LEFT JOIN precio_ref pr ON ca.sku = pr.sku AND ca.formato = pr.formato
        LEFT JOIN comp c        ON ca.sku = c.sku  AND ca.formato = c.formato
        ORDER BY ca.nombre
        """
    else:
        # Lógica original: cantidades y precio base del mismo mes
        return f"""
        WITH equiv AS (
            SELECT sku_compra, sku_receta FROM sku_equivalencias
        ),
        base AS (
            SELECT
                COALESCE(e.sku_receta, c.sku)                              AS sku,
                c.formato,
                MIN(c.nombre_producto)                                     AS nombre,
                MIN(c.nombre_proveedor)                                    AS proveedor,
                MIN(c.categoria_producto)                                  AS categoria,
                MAX(c.conversion)                                          AS conversion,
                SUM(c.cant_conv * NULLIF(c.formato, 0))                   AS cant_base,
                SUM(c.costo_realfinal) / NULLIF(SUM(c.cant_conv * NULLIF(c.formato, 0)), 0) AS precio_base
            FROM compras c
            LEFT JOIN equiv e ON c.sku = e.sku_compra
            WHERE c.fecha_dte::date BETWEEN '{fecha_base_i}' AND '{_fb_f}'
              AND UPPER(COALESCE(c.categoria_producto,'')) NOT LIKE '%ART%LIMPIEZA%' AND UPPER(COALESCE(c.categoria_producto,'')) NOT LIKE '%ADMINISTR%' AND UPPER(COALESCE(c.subcat,'')) NOT IN ('NO VENDIBLE','NO VENDIBLES')
              AND c.costo_realfinal > 0
              AND c.monto_real > 0
              AND c.cant_conv > 0
              AND c.id NOT IN (SELECT compra_id FROM compras_excluidas)
              {filtro_cat}
              {filtro_local}
            GROUP BY 1, 2
        ),
        comp AS (
            SELECT
                COALESCE(e.sku_receta, c.sku)                              AS sku,
                c.formato,
                SUM(c.costo_realfinal) / NULLIF(SUM(c.cant_conv * NULLIF(c.formato, 0)), 0) AS precio_comp
            FROM compras c
            LEFT JOIN equiv e ON c.sku = e.sku_compra
            WHERE c.fecha_dte::date BETWEEN '{fecha_comp_i}' AND '{_fc_f}'
              AND UPPER(COALESCE(c.categoria_producto,'')) NOT LIKE '%ART%LIMPIEZA%' AND UPPER(COALESCE(c.categoria_producto,'')) NOT LIKE '%ADMINISTR%' AND UPPER(COALESCE(c.subcat,'')) NOT IN ('NO VENDIBLE','NO VENDIBLES')
              AND c.costo_realfinal > 0
              AND c.monto_real > 0
              AND c.cant_conv > 0
              AND c.id NOT IN (SELECT compra_id FROM compras_excluidas)
              {filtro_local}
            GROUP BY 1, 2
        )
        SELECT
            b.sku, b.nombre, b.proveedor, b.categoria,
            b.formato, b.conversion, b.cant_base, b.precio_base,
            c.precio_comp,
            b.cant_base * b.precio_base                               AS impacto_base,
            b.cant_base * COALESCE(c.precio_comp, b.precio_base)     AS impacto_comp
        FROM base b
        LEFT JOIN comp c ON b.sku = c.sku AND b.formato = c.formato
        ORDER BY b.nombre
        """


def _procesar_variacion_df(df):
    """
    Aplica los tipos numéricos y calcula columnas derivadas
    sobre un DataFrame crudo devuelto por _build_variacion_query.
    Retorna el DataFrame listo para visualización.
    """
    df['precio_base']     = pd.to_numeric(df['precio_base'],  errors='coerce').fillna(0)
    df['precio_comp_raw'] = pd.to_numeric(df['precio_comp'],  errors='coerce')
    df['sin_precio_comp'] = df['precio_comp_raw'].isna() | (df['precio_comp_raw'] == 0)
    # Para delta por SKU: usar precio_base como fallback cuando no hay precio comp
    df['precio_comp']     = df['precio_comp_raw'].fillna(df['precio_base'])
    df['cant_base']       = pd.to_numeric(df['cant_base'],    errors='coerce').fillna(0)
    df['formato']         = pd.to_numeric(df['formato'],      errors='coerce').fillna(1)
    df['impacto_base']    = pd.to_numeric(df['impacto_base'], errors='coerce').fillna(0)
    df['impacto_comp']    = df['cant_base'] * df['precio_comp']
    df['delta_dinero']    = df['impacto_comp'] - df['impacto_base']
    df['delta_pct']       = df.apply(
        lambda r: (r['delta_dinero'] / r['impacto_base'] * 100)
        if r['impacto_base'] > 0 and not r['sin_precio_comp'] else None, axis=1
    )
    # Para el total de canasta:
    # - impacto_base_cf = siempre el total completo (canasta fija)
    # - impacto_comp_cf = usa precio_comp donde existe, precio_base como fallback
    df['impacto_base_cf'] = df['impacto_base']
    df['impacto_comp_cf'] = df['impacto_comp']  # ya usa fallback precio_base cuando sin_precio_comp
    # Precio para visualización: si formato=1 → $/unidad, si no → $/kg o $/L (×1000)
    _mult = df['formato'].apply(lambda f: float(f) if float(f) > 0 else 1)
    df['precio_base_disp'] = df['precio_base'] * _mult
    df['precio_comp_disp'] = df['precio_comp'] * _mult
    return df


def generar_pdf_variacion(df, mes_base, mes_comp, local='Cadena Completa'):
    import os
    from reportlab.lib.pagesizes import A4, landscape
    from reportlab.lib import colors as rc
    from reportlab.lib.units import mm
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, HRFlowable
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.enums import TA_LEFT, TA_CENTER, TA_RIGHT
    from reportlab.platypus import Image as RLImage

    CB  = rc.HexColor('#0d0d0d')
    CP  = rc.HexColor('#1a1a1a')
    CG  = rc.HexColor('#d4a853')
    CT  = rc.HexColor('#f0ede8')
    CM  = rc.HexColor('#666666')
    CM2 = rc.HexColor('#2a2a2a')
    CR  = rc.HexColor('#e84545')
    CGr = rc.HexColor('#4caf7d')
    CH  = rc.HexColor('#0d0d0d')
    CBR = rc.HexColor('#1e0808')
    CBG = rc.HexColor('#081408')
    CBo = rc.HexColor('#2a2a2a')

    PAGE  = landscape(A4)
    W, H  = PAGE
    LM = RM = 12*mm
    AVAIL = W - LM - RM          # 273mm
    COL   = (AVAIL - 4*mm) / 2   # 134.5mm por columna

    # Columnas tabla (sin SKU para ganar espacio):
    # #(5) | Producto(flex) | Q(18) | P.base(20) | P.comp(20) | Δ$(20) | Δ%(14)
    _FIXED = (5 + 18 + 20 + 20 + 20 + 14) * mm
    _PROD  = COL - _FIXED          # ~37.5mm

    def sty(sz, col, bold=False, align=TA_LEFT):
        return ParagraphStyle('_', fontSize=sz, textColor=col,
            fontName='Helvetica-Bold' if bold else 'Helvetica',
            alignment=align, leading=sz * 1.25, spaceAfter=0, spaceBefore=0)

    def P(txt, sz=7, col=None, bold=False, align=TA_RIGHT):
        return Paragraph(str(txt), sty(sz, col or CT, bold=bold, align=align))

    # ── Datos ─────────────────────────────────────────────────
    df = df.copy()
    df['delta_pct_abs'] = df['delta_pct'].abs().fillna(0)
    df['delta_din_abs'] = df['delta_dinero'].abs().fillna(0)
    df_sig   = df[(df['delta_pct_abs'] >= 1.0) | (df['delta_din_abs'] >= 500)]
    top_alza = df_sig[df_sig['delta_dinero'] > 0].nlargest(15, 'delta_dinero')
    top_baja = df_sig[df_sig['delta_dinero'] < 0].nsmallest(15, 'delta_dinero')

    tb = df['impacto_base_cf'].sum()
    tc = df['impacto_comp_cf'].sum()
    td = tc - tb
    tp = (td / tb * 100) if tb > 0 else 0
    n_alza  = int((df['delta_dinero'] > 0).sum())
    n_baja  = int((df['delta_dinero'] < 0).sum())
    n_estab = int((df['delta_dinero'] == 0).sum())
    kc = CR if td > 0 else CGr

    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=PAGE,
        leftMargin=LM, rightMargin=RM, topMargin=8*mm, bottomMargin=7*mm)

    story = []

    # ── ENCABEZADO ────────────────────────────────────────────
    logo_cell = Spacer(28*mm, 22*mm)
    if os.path.exists(LOGO_PATH):
        logo_cell = RLImage(LOGO_PATH, width=28*mm, height=28*mm)

    hdr_data = [[
        logo_cell,
        [Paragraph("INFORME DE VARIACIÓN DE PRECIOS", sty(13, CG, bold=True, align=TA_CENTER)),
         Spacer(1, 1*mm),
         Paragraph("ALEMAN EXPERTO", sty(7, CM, align=TA_CENTER))],
        [Paragraph(local.upper(), sty(10, CT, bold=True, align=TA_RIGHT)),
         Spacer(1, 1*mm),
         Paragraph(f"{mes_base}  →  {mes_comp}", sty(7.5, CM, align=TA_RIGHT))],
    ]]
    hdr_tbl = Table(hdr_data, colWidths=[30*mm, 160*mm, 83*mm])
    hdr_tbl.setStyle(TableStyle([
        ('VALIGN',        (0,0), (-1,-1), 'MIDDLE'),
        ('LINEBELOW',     (0,0), (-1,0),  1.5, CG),
        ('TOPPADDING',    (0,0), (-1,-1), 0),
        ('BOTTOMPADDING', (0,0), (-1,-1), 4),
        ('LEFTPADDING',   (0,0), (-1,-1), 0),
        ('RIGHTPADDING',  (0,0), (-1,-1), 0),
    ]))
    story += [hdr_tbl, Spacer(1, 3*mm)]

    # ── KPIs ─────────────────────────────────────────────────
    kw = AVAIL / 7
    kpi_rows = [
        [P(f"CANASTA {mes_base[:3].upper()}", 5.5, CM, align=TA_CENTER),
         P(f"CANASTA {mes_comp[:3].upper()}",  5.5, CM, align=TA_CENTER),
         P("IMPACTO Δ$",   5.5, CM, align=TA_CENTER),
         P("VARIACIÓN %",  5.5, CM, align=TA_CENTER),
         P("PROD. ALZA ↑", 5.5, CM, align=TA_CENTER),
         P("PROD. BAJA ↓", 5.5, CM, align=TA_CENTER),
         P("SIN CAMBIO",   5.5, CM, align=TA_CENTER)],
        [P(f"${tb:,.0f}",   11, CG,  bold=True, align=TA_CENTER),
         P(f"${tc:,.0f}",   11, CT,  bold=True, align=TA_CENTER),
         P(f"${td:+,.0f}",  11, kc,  bold=True, align=TA_CENTER),
         P(f"{tp:+.1f}%",   11, kc,  bold=True, align=TA_CENTER),
         P(str(n_alza),     11, CR,  bold=True, align=TA_CENTER),
         P(str(n_baja),     11, CGr, bold=True, align=TA_CENTER),
         P(str(n_estab),    11, CM,  bold=True, align=TA_CENTER)],
    ]
    kpi_tbl = Table(kpi_rows, colWidths=[kw]*7)
    kpi_tbl.setStyle(TableStyle([
        ('BACKGROUND',    (0,0), (-1,-1), CP),
        ('BOX',           (0,0), (-1,-1), 0.5, CBo),
        ('LINEBEFORE',    (1,0), (-1,-1), 0.3, CBo),
        ('TOPPADDING',    (0,0), (-1,-1), 3),
        ('BOTTOMPADDING', (0,0), (-1,-1), 3),
        ('LINEABOVE',     (2,0), (3,0),   2, kc),
    ]))
    story += [kpi_tbl, Spacer(1, 4*mm)]

    # ── HELPER tabla top 10 ───────────────────────────────────
    def tabla_top(df_sub, titulo, col_t, col_f):
        if df_sub.empty:
            return [P(titulo, 7, col_t, bold=True),
                    Spacer(1, 2*mm),
                    P("Sin movimientos significativos", 6.5, CM)]
        mb = mes_base[:3]; mc = mes_comp[:3]
        cw   = [5*mm, _PROD, 18*mm, 20*mm, 20*mm, 20*mm, 14*mm]
        hdrs = ['#', 'Producto', 'Q base', f'P.Unit {mb}', f'P.Unit {mc}', 'Δ$', 'Δ%']
        rows = [[P(h, 6, CM, bold=True, align=TA_LEFT if i < 2 else TA_RIGHT)
                 for i, h in enumerate(hdrs)]]
        for pos, (_, r) in enumerate(df_sub.iterrows(), 1):
            dd = r.get('delta_dinero', 0) or 0
            dp = r.get('delta_pct',    0) or 0
            dc = CR if dd > 0 else CGr
            _cant = float(r.get('cant_base', 0) or 0)
            _fmt  = float(r.get('formato', 1) or 1)
            _conv = float(r.get('conversion', 1) or 1)
            _cant_u = _cant / _fmt if _fmt > 0 else _cant
            if _conv == 1000:
                _cant_str = f"{_cant_u:,.1f} kg"
            else:
                _cant_str = f"{_cant_u:,.0f} un"
            rows.append([
                P(str(pos),                         6,   CM,  align=TA_CENTER),
                P(str(r.get('nombre', '')),         6.5, CT,  align=TA_LEFT),
                P(_cant_str,                        6.5, CM,  align=TA_RIGHT),
                P(f"${r.get('precio_base_disp', r.get('precio_base',0)):,.0f}",6.5, CM),
                P(f"${r.get('precio_comp_disp', r.get('precio_comp',0)):,.0f}",6.5, CT),
                P(f"${dd:+,.0f}",                   6.5, dc,  bold=True),
                P(f"{dp:+.1f}%",                    6.5, dc,  bold=True),
            ])
        tbl = Table(rows, colWidths=cw, repeatRows=1)
        rs = [
            ('BACKGROUND',    (0,0), (-1,0),  CH),
            ('LINEBELOW',     (0,0), (-1,0),  0.8, col_t),
            ('TOPPADDING',    (0,0), (-1,-1), 2),
            ('BOTTOMPADDING', (0,0), (-1,-1), 2),
            ('LEFTPADDING',   (0,0), (-1,-1), 3),
            ('RIGHTPADDING',  (0,0), (-1,-1), 3),
        ]
        for i in range(1, len(rows)):
            rs += [('BACKGROUND', (0,i), (-1,i), col_f if i%2==0 else CP),
                   ('LINEBELOW',  (0,i), (-1,i), 0.2, CM2)]
        tbl.setStyle(TableStyle(rs))
        return [P(titulo, 7, col_t, bold=True), Spacer(1, 1.5*mm), tbl]

    # ── DOS COLUMNAS LADO A LADO ──────────────────────────────
    alza = tabla_top(top_alza, "▲  TOP 15 ALZAS  (mayor impacto $)", CR,  CBR)
    baja = tabla_top(top_baja, "▼  TOP 15 BAJAS  (mayor ahorro $)",  CGr, CBG)

    dos_col = Table(
        [[alza, [Spacer(4*mm, 1)], baja]],
        colWidths=[COL, 4*mm, COL]
    )
    dos_col.setStyle(TableStyle([
        ('VALIGN',        (0,0), (-1,-1), 'TOP'),
        ('LINEBEFORE',    (2,0), (2,0),   0.4, CBo),
        ('LEFTPADDING',   (0,0), (-1,-1), 0),
        ('RIGHTPADDING',  (0,0), (-1,-1), 0),
        ('TOPPADDING',    (0,0), (-1,-1), 0),
        ('BOTTOMPADDING', (0,0), (-1,-1), 0),
    ]))
    story += [dos_col, Spacer(1, 3*mm)]

    # ── FOOTER ───────────────────────────────────────────────
    story += [
        HRFlowable(width="100%", thickness=0.4, color=CBo),
        Spacer(1, 1*mm),
        P(f"Aleman Experto  ·  {mes_base} vs {mes_comp}  ·  {local}  ·  Productos con variación ≥1% o Δ$≥$500",
          5.5, CM, align=TA_CENTER),
    ]

    def add_bg(c, d):
        c.saveState()
        c.setFillColor(CB)
        c.rect(0, 0, W, H, fill=1, stroke=0)
        c.restoreState()

    doc.build(story, onFirstPage=add_bg, onLaterPages=add_bg)
    buf.seek(0)
    return buf.getvalue()


