# ============================================================
# PDF COLACIONES RRHH — informe por local y resumen empresa
# Comparación adaptativa: ≥2 meses → mes a mes; si no → semana a semana.
# Análisis real: cada local clasificado por cruce de métricas (caso A/B/C/D),
# umbral de alerta col/turno = 2.0, gráficos incrustados, conclusiones que
# varían según magnitud. Métricas: colaciones/turno y colaciones/persona.
# ============================================================
_CR_UMBRAL_CT = 2.0   # col/turno sobre el cual un local entra en alerta


def _cr_detectar_modo(fi, ff):
    """Devuelve 'mes' si el rango cubre ≥2 meses calendario; si no 'semana'."""
    import datetime as _dt
    meses = set()
    d = fi
    while d <= ff:
        meses.add((d.year, d.month))
        d += _dt.timedelta(days=1)
    return "mes" if len(meses) >= 2 else "semana"


def _cr_periodo_label(d, modo):
    if modo == "mes":
        _MN = ["", "Ene", "Feb", "Mar", "Abr", "May", "Jun",
               "Jul", "Ago", "Sep", "Oct", "Nov", "Dic"]
        return f"{_MN[d.month]} {d.year}"
    iso = d.isocalendar()
    return f"Sem {iso[1]:02d}/{iso[0]}"


def _cr_armar_comparativo(df_col, df_tur, df_pers_dia, modo):
    """Agrupa por (local, período): colaciones, turnos, personas + ambas métricas."""
    import pandas as _pd
    def _per(d):
        return _cr_periodo_label(d, modo)
    _c = df_col.copy(); _c["periodo"] = _c["fecha"].apply(_per)
    _c = _c.groupby(["local", "periodo"])["colaciones"].sum().reset_index()
    _t = df_tur.copy(); _t["periodo"] = _t["fecha"].apply(_per)
    _t = _t.groupby(["local", "periodo"])["turnos"].sum().reset_index()
    _p = df_pers_dia.copy(); _p["periodo"] = _p["fecha"].apply(_per)
    _p = _p.groupby(["local", "periodo"])["rut"].nunique().reset_index()
    _p.columns = ["local", "periodo", "personas"]
    _m = _t.merge(_c, on=["local", "periodo"], how="left").merge(
        _p, on=["local", "periodo"], how="left")
    _m["colaciones"] = _m["colaciones"].fillna(0)
    _m["personas"] = _m["personas"].fillna(0)
    _m["col_x_turno"] = (_m["colaciones"] / _m["turnos"].replace(0, _pd.NA)).round(2)
    _m["col_x_persona"] = (_m["colaciones"] / _m["personas"].replace(0, _pd.NA)).round(2)
    return _m


def _cr_clasificar(ct, cp, cp_red):
    """Cruza col/turno (vs umbral 2.0) con col/persona (vs red) → caso A/B/C/D."""
    import pandas as _pd
    if _pd.isna(ct):
        return ("—", "Sin datos suficientes.")
    ct_alto = ct > _CR_UMBRAL_CT
    cp_alto = (not _pd.isna(cp)) and cp_red and cp > cp_red * 1.2
    if ct_alto and cp_alto:
        return ("A", "Consumo elevado y generalizado: tanto las colaciones por jornada "
                "como por persona superan lo esperado. Apunta a una política de doble "
                "comida o a sobreconsumo extendido en toda la dotación.")
    if (not ct_alto) and cp_alto:
        return ("B", "Concentración: el consumo por jornada es normal, pero pocas "
                "personas acumulan muchas colaciones. Revisar si un grupo reducido "
                "carga colaciones por sobre el resto.")
    if ct_alto and (not cp_alto):
        return ("C", "Desbalance turnos/colaciones: hay muchas colaciones por jornada "
                "pero repartidas entre la dotación. Más probable un sub-registro de "
                "turnos de asistencia que un sobreconsumo real.")
    return ("D", "Dentro de lo esperado: consumo por jornada y por persona en rango "
            "normal respecto a la red.")


def _cr_chart_barras(comp, periodo, pal_hex):
    """Gráfico de barras: ranking de locales por col/turno en un período. Devuelve PNG bytes."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    import io as _io, pandas as _pd
    sub = comp[comp["periodo"] == periodo].dropna(subset=["col_x_turno"]).sort_values("col_x_turno")
    if sub.empty:
        return None
    fig, ax = plt.subplots(figsize=(7.2, max(2.2, 0.42 * len(sub))), dpi=130)
    colores = ["#e84545" if v > _CR_UMBRAL_CT else "#4caf7d" for v in sub["col_x_turno"]]
    ax.barh(sub["local"], sub["col_x_turno"], color=colores)
    ax.axvline(_CR_UMBRAL_CT, color="#d4a853", ls="--", lw=1.2, label=f"Umbral {_CR_UMBRAL_CT}")
    for i, v in enumerate(sub["col_x_turno"]):
        ax.text(v + 0.03, i, f"{v:.2f}", va="center", fontsize=8, color="#222")
    ax.set_xlabel("Colaciones por turno", fontsize=9)
    ax.set_title(f"Ranking por local — {periodo}", fontsize=10, color="#1a1a1a")
    ax.legend(fontsize=8, loc="lower right")
    ax.spines[["top", "right"]].set_visible(False)
    plt.tight_layout()
    b = _io.BytesIO(); fig.savefig(b, format="png", bbox_inches="tight"); plt.close(fig)
    b.seek(0); return b.getvalue()


def _cr_chart_lineas(comp, periodos):
    """Gráfico de líneas: evolución de col/turno por local entre períodos. PNG bytes."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    import io as _io
    if len(periodos) < 2:
        return None
    fig, ax = plt.subplots(figsize=(7.2, 3.4), dpi=130)
    for loc in sorted(comp["local"].unique()):
        sub = comp[comp["local"] == loc].set_index("periodo").reindex(periodos)
        ax.plot(periodos, sub["col_x_turno"], marker="o", lw=1.4, label=loc, markersize=4)
    ax.axhline(_CR_UMBRAL_CT, color="#d4a853", ls="--", lw=1.2)
    ax.set_ylabel("Colaciones por turno", fontsize=9)
    ax.set_title("Evolución por local entre períodos", fontsize=10, color="#1a1a1a")
    ax.legend(fontsize=7, ncol=2, loc="best")
    ax.spines[["top", "right"]].set_visible(False)
    plt.tight_layout()
    b = _io.BytesIO(); fig.savefig(b, format="png", bbox_inches="tight"); plt.close(fig)
    b.seek(0); return b.getvalue()


def _cr_chart_dispersion(comp, periodo, cp_red):
    """Dispersión col/turno (x) vs col/persona (y), cuadrantes A/B/C/D. PNG bytes."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    import io as _io, pandas as _pd
    sub = comp[comp["periodo"] == periodo].dropna(subset=["col_x_turno", "col_x_persona"])
    if sub.empty:
        return None
    fig, ax = plt.subplots(figsize=(7.2, 4.6), dpi=130)
    ax.scatter(sub["col_x_turno"], sub["col_x_persona"], s=60, color="#1a1a1a", zorder=3)
    for _, r in sub.iterrows():
        ax.annotate(r["local"], (r["col_x_turno"], r["col_x_persona"]),
                    fontsize=7, xytext=(4, 4), textcoords="offset points")
    ax.axvline(_CR_UMBRAL_CT, color="#d4a853", ls="--", lw=1.1)
    cp_lim = cp_red * 1.2 if cp_red else sub["col_x_persona"].median()
    ax.axhline(cp_lim, color="#d4a853", ls="--", lw=1.1)
    # etiquetas de cuadrante
    xr = ax.get_xlim(); yr = ax.get_ylim()
    ax.text(xr[1], yr[1], "A", fontsize=13, color="#e84545", ha="right", va="top", weight="bold")
    ax.text(xr[0], yr[1], "B", fontsize=13, color="#d4a853", ha="left", va="top", weight="bold")
    ax.text(xr[1], yr[0], "C", fontsize=13, color="#d4a853", ha="right", va="bottom", weight="bold")
    ax.text(xr[0], yr[0], "D", fontsize=13, color="#4caf7d", ha="left", va="bottom", weight="bold")
    ax.set_xlabel("Colaciones por turno", fontsize=9)
    ax.set_ylabel("Colaciones por persona", fontsize=9)
    ax.set_title(f"Cruce de métricas — {periodo}", fontsize=10, color="#1a1a1a")
    ax.spines[["top", "right"]].set_visible(False)
    plt.tight_layout()
    b = _io.BytesIO(); fig.savefig(b, format="png", bbox_inches="tight"); plt.close(fig)
    b.seek(0); return b.getvalue()


def _cr_pdf_base():
    """Imports y paleta compartida para los PDF de colaciones."""
    import os
    from reportlab.lib.pagesizes import A4
    from reportlab.lib import colors as rc
    from reportlab.lib.units import mm
    from reportlab.platypus import (SimpleDocTemplate, Table, TableStyle, Paragraph,
                                    Spacer, HRFlowable, PageBreak)
    from reportlab.platypus import Image as RLImage
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.enums import TA_LEFT, TA_CENTER, TA_RIGHT, TA_JUSTIFY
    pal = dict(
        CB=rc.HexColor('#1a1a1a'), CG=rc.HexColor('#b8860b'), CT=rc.HexColor('#1a1a1a'),
        CM=rc.HexColor('#444444'), CR=rc.HexColor('#c0392b'), CGr=rc.HexColor('#2e7d52'),
        CY=rc.HexColor('#9a6a00'), CBo=rc.HexColor('#cccccc'), CHd=rc.HexColor('#1a1a1a'),
        CHdT=rc.HexColor('#d4a853'), CRowAlt=rc.HexColor('#f5f2ec'),
    )
    return dict(os=os, A4=A4, rc=rc, mm=mm, SimpleDocTemplate=SimpleDocTemplate,
                Table=Table, TableStyle=TableStyle, Paragraph=Paragraph, Spacer=Spacer,
                HRFlowable=HRFlowable, PageBreak=PageBreak, RLImage=RLImage,
                ParagraphStyle=ParagraphStyle, TA_LEFT=TA_LEFT, TA_CENTER=TA_CENTER,
                TA_RIGHT=TA_RIGHT, TA_JUSTIFY=TA_JUSTIFY, pal=pal)


def _cr_img_flow(png_bytes, R, ancho_mm=170):
    """Convierte PNG bytes en un flowable Image escalado al ancho dado."""
    import io as _io
    if not png_bytes:
        return R["Spacer"](1, 1)
    from reportlab.lib.utils import ImageReader
    ir = ImageReader(_io.BytesIO(png_bytes))
    iw, ih = ir.getSize()
    w = ancho_mm * R["mm"]
    h = w * ih / iw
    return R["RLImage"](_io.BytesIO(png_bytes), width=w, height=h)


def _cr_metodologia_flow(R, modo, fi, ff):
    mm = R["mm"]; pal = R["pal"]; Paragraph = R["Paragraph"]; Spacer = R["Spacer"]
    PS = R["ParagraphStyle"]; TA_LEFT = R["TA_LEFT"]; TA_JUSTIFY = R["TA_JUSTIFY"]
    def s(sz, col, bold=False, align=TA_JUSTIFY):
        return PS('_', fontSize=sz, textColor=col,
                  fontName='Helvetica-Bold' if bold else 'Helvetica',
                  alignment=align, leading=sz*1.4)
    cmp_txt = "mes a mes" if modo == "mes" else "semana a semana"
    return [
        Paragraph("METODOLOGÍA", s(11, pal["CG"], bold=True, align=TA_LEFT)),
        Spacer(1, 2*mm),
        Paragraph(
            f"<b>Período analizado:</b> {fi} al {ff}. Como el rango "
            f"{'abarca dos o más meses' if modo=='mes' else 'es menor a dos meses'}, "
            f"la comparación se realiza <b>{cmp_txt}</b>.", s(9, pal["CT"])),
        Spacer(1, 1.5*mm),
        Paragraph(
            "<b>Qué se cuenta como colación:</b> platos principales del personal por "
            "código de venta CPC (colación completa) y CPP (proteína de la colación "
            "armada). Acompañamientos (CPA) y ensaladas (CPE) se excluyen por ser "
            "guarnición, evitando el doble conteo. Cada unidad de CPC o CPP = una colación.",
            s(8.5, pal["CM"])),
        Spacer(1, 1.5*mm),
        Paragraph(
            f"<b>Indicadores:</b> <b>Colaciones por turno</b> = colaciones ÷ turnos "
            f"trabajados (jornadas con horas&gt;0). <b>Colaciones por persona</b> = "
            f"colaciones ÷ trabajadores distintos. Un local entra en <b>alerta</b> cuando "
            f"supera <b>{_CR_UMBRAL_CT:.1f} colaciones por turno</b> (equivalente a más de "
            f"almuerzo y cena por jornada).", s(8.5, pal["CM"])),
        Spacer(1, 1.5*mm),
        Paragraph(
            "<b>Cruce de métricas:</b> combinar ambas distingue el tipo de situación — "
            "<b>A</b> consumo elevado generalizado, <b>B</b> pocas personas concentran el "
            "consumo, <b>C</b> desbalance que sugiere sub-registro de turnos, <b>D</b> "
            "normal. Esto evita tratar igual a locales con causas distintas.", s(8.5, pal["CM"])),
    ]


def _cr_tabla_periodos(R, sub, periodos):
    """Tabla comparativa de períodos para un local."""
    mm = R["mm"]; pal = R["pal"]; Table = R["Table"]; TableStyle = R["TableStyle"]
    import pandas as _pd
    head = ["Período", "Colac.", "Turnos", "Personas", "Col/Turno", "Col/Persona"]
    rows = [head]
    for per in periodos:
        r = sub.loc[per]
        if _pd.isna(r["turnos"]):
            rows.append([per, "—", "—", "—", "—", "—"])
        else:
            rows.append([per, f"{int(r['colaciones'])}", f"{int(r['turnos'])}",
                         f"{int(r['personas'])}",
                         "—" if _pd.isna(r["col_x_turno"]) else f"{r['col_x_turno']:.2f}",
                         "—" if _pd.isna(r["col_x_persona"]) else f"{r['col_x_persona']:.2f}"])
    t = Table(rows, colWidths=[32*mm, 24*mm, 24*mm, 26*mm, 28*mm, 30*mm])
    style = [
        ('BACKGROUND',(0,0),(-1,0),pal["CHd"]),
        ('TEXTCOLOR',(0,0),(-1,0),pal["CHdT"]),
        ('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),
        ('FONTSIZE',(0,0),(-1,-1),8.5),
        ('ALIGN',(1,0),(-1,-1),'CENTER'),
        ('GRID',(0,0),(-1,-1),0.4,pal["CBo"]),
        ('ROWBACKGROUNDS',(0,1),(-1,-1),[R["rc"].white, pal["CRowAlt"]]),
        ('TOPPADDING',(0,0),(-1,-1),3.5),('BOTTOMPADDING',(0,0),(-1,-1),3.5),
        ('TEXTCOLOR',(0,1),(-1,-1),pal["CT"]),
    ]
    # Resaltar celdas col/turno en alerta
    for i, per in enumerate(periodos, start=1):
        r = sub.loc[per]
        if not _pd.isna(r["col_x_turno"]) and r["col_x_turno"] > _CR_UMBRAL_CT:
            style.append(('TEXTCOLOR',(4,i),(4,i),pal["CR"]))
            style.append(('FONTNAME',(4,i),(4,i),'Helvetica-Bold'))
    t.setStyle(TableStyle(style))
    return t


def generar_pdf_colaciones_local(comp, modo, fi, ff):
    R = _cr_pdf_base()
    mm = R["mm"]; pal = R["pal"]; PS = R["ParagraphStyle"]
    TA_LEFT, TA_CENTER, TA_JUSTIFY = R["TA_LEFT"], R["TA_CENTER"], R["TA_JUSTIFY"]
    Paragraph, Spacer, Table, TableStyle = R["Paragraph"], R["Spacer"], R["Table"], R["TableStyle"]
    HRFlowable, PageBreak, RLImage = R["HRFlowable"], R["PageBreak"], R["RLImage"]
    import io as _io, pandas as _pd

    def s(sz, col, bold=False, align=TA_LEFT):
        return PS('_', fontSize=sz, textColor=col,
                  fontName='Helvetica-Bold' if bold else 'Helvetica',
                  alignment=align, leading=sz*1.35)

    buf = _io.BytesIO()
    doc = R["SimpleDocTemplate"](buf, pagesize=R["A4"],
        leftMargin=15*mm, rightMargin=15*mm, topMargin=12*mm, bottomMargin=12*mm)
    story = []

    logo = Spacer(24*mm, 20*mm)
    if R["os"].path.exists(LOGO_PATH):
        logo = RLImage(LOGO_PATH, width=22*mm, height=22*mm)
    hdr = Table([[logo,
        [Paragraph("INFORME DE COLACIONES RRHH", s(15, pal["CG"], bold=True, align=TA_CENTER)),
         Paragraph("Análisis por local · Alemán Experto", s(8.5, pal["CM"], align=TA_CENTER))]]],
        colWidths=[26*mm, 154*mm])
    hdr.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'MIDDLE'),
        ('LINEBELOW',(0,0),(-1,0),1.5,pal["CG"]), ('BOTTOMPADDING',(0,0),(-1,-1),5)]))
    story += [hdr, Spacer(1, 4*mm)]
    story += _cr_metodologia_flow(R, modo, fi, ff)
    story += [Spacer(1, 3*mm), HRFlowable(width="100%", color=pal["CBo"], thickness=0.5),
              Spacer(1, 3*mm)]

    periodos = sorted(comp["periodo"].unique())
    locales = sorted(comp["local"].unique())
    ult = periodos[-1]
    cp_red = comp[comp["periodo"] == ult]["col_x_persona"].mean()

    # Gráfico dispersión (cruce) del último período, una vez al inicio
    disp = _cr_chart_dispersion(comp, ult, cp_red)
    if disp:
        story += [Paragraph(f"CRUCE DE MÉTRICAS — {ult}", s(11, pal["CG"], bold=True)),
                  Spacer(1, 2*mm), _cr_img_flow(disp, R, 165), Spacer(1, 4*mm)]

    story += [Paragraph("DETALLE POR LOCAL", s(11, pal["CG"], bold=True)), Spacer(1, 3*mm)]

    for idx, loc in enumerate(locales):
        sub = comp[comp["local"] == loc].set_index("periodo").reindex(periodos)
        r_ult = sub.loc[ult]
        caso, _desc = _cr_clasificar(r_ult["col_x_turno"], r_ult["col_x_persona"], cp_red)
        concl = _cr_conclusion_local(sub, periodos, modo, cp_red, caso)
        # color del badge de caso
        badge_col = {"A": pal["CR"], "B": pal["CY"], "C": pal["CY"],
                     "D": pal["CGr"], "—": pal["CM"]}[caso]
        titulo = Table([[
            Paragraph(loc.upper(), s(11, pal["CB"], bold=True)),
            Paragraph(f"CASO {caso}", s(9, R["rc"].white, bold=True, align=TA_CENTER)),
        ]], colWidths=[140*mm, 25*mm])
        titulo.setStyle(TableStyle([
            ('BACKGROUND',(1,0),(1,0),badge_col), ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
            ('TOPPADDING',(1,0),(1,0),3),('BOTTOMPADDING',(1,0),(1,0),3),
        ]))
        story += [titulo, Spacer(1, 1.5*mm),
                  _cr_tabla_periodos(R, sub, periodos), Spacer(1, 2*mm),
                  Paragraph(concl, s(8.5, pal["CM"], align=TA_JUSTIFY)), Spacer(1, 5*mm)]
        if idx < len(locales) - 1 and (idx + 1) % 3 == 0:
            story += [PageBreak()]

    doc.build(story)
    buf.seek(0)
    return buf.getvalue()


def generar_pdf_colaciones_individual(loc, fi, ff, df_dia, df_pers, modo):
    """PDF ejecutivo de UN local: resumen + desglose diario + lista de personal.
    df_dia : DataFrame [fecha, colaciones, turnos, ratio]
    df_pers: DataFrame [nombre, cargo, turnos, colacion_min_prom]  (personal del local)
    """
    R = _cr_pdf_base()
    mm = R["mm"]; pal = R["pal"]; PS = R["ParagraphStyle"]; rc = R["rc"]
    TA_LEFT, TA_CENTER, TA_RIGHT = R["TA_LEFT"], R["TA_CENTER"], R["TA_RIGHT"]
    Paragraph, Spacer, Table, TableStyle = R["Paragraph"], R["Spacer"], R["Table"], R["TableStyle"]
    HRFlowable, RLImage = R["HRFlowable"], R["RLImage"]
    import io as _io, pandas as _pd

    def s(sz, col, bold=False, align=TA_LEFT, lead=None):
        return PS('_', fontSize=sz, textColor=col,
                  fontName='Helvetica-Bold' if bold else 'Helvetica',
                  alignment=align, leading=lead or sz*1.3)

    # ── Semáforo (mismos criterios que la app: <2,5 Normal / 2,5–3 Atención / >3 Alto) ──
    def _sem(r):
        if _pd.isna(r): return ("s/d", pal["CM"])
        if r > 3.0:     return ("Alto", pal["CR"])
        if r >= 2.5:    return ("Atención", pal["CY"])
        return ("Normal", pal["CGr"])

    buf = _io.BytesIO()
    doc = R["SimpleDocTemplate"](buf, pagesize=R["A4"],
        leftMargin=16*mm, rightMargin=16*mm, topMargin=13*mm, bottomMargin=14*mm)
    story = []

    # ════════ CABECERA ════════
    logo = Spacer(22*mm, 18*mm)
    if R["os"].path.exists(LOGO_PATH):
        logo = RLImage(LOGO_PATH, width=20*mm, height=20*mm)
    hdr = Table([[logo,
        [Paragraph("COLACIONES RRHH", s(16, pal["CG"], bold=True)),
         Paragraph(f"{loc}", s(12, pal["CB"], bold=True)),
         Paragraph(f"{fi} &nbsp;→&nbsp; {ff}", s(9, pal["CM"]))]]],
        colWidths=[24*mm, 154*mm])
    hdr.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'MIDDLE'),
        ('LINEBELOW',(0,0),(-1,0),1.5,pal["CG"]), ('BOTTOMPADDING',(0,0),(-1,-1),6)]))
    story += [hdr, Spacer(1, 5*mm)]

    # ════════ 1) RESUMEN POR LOCAL (KPI cards) ════════
    tot_col = float(df_dia["colaciones"].sum()) if not df_dia.empty else 0.0
    tot_tur = float(df_dia["turnos"].sum()) if not df_dia.empty else 0.0
    n_pers  = int(len(df_pers)) if df_pers is not None else 0
    ratio   = (tot_col / tot_tur) if tot_tur > 0 else float("nan")
    estado, est_col = _sem(ratio)
    ratio_txt = (f"{ratio:.2f}".replace(".", ",")) if tot_tur > 0 else "s/d"

    story += [Paragraph("📍 RESUMEN POR LOCAL", s(11, pal["CG"], bold=True)),
              Spacer(1, 3*mm)]

    def _kpi(titulo, valor, color=pal["CB"], sub=""):
        return Table([
            [Paragraph(titulo.upper(), s(7, pal["CM"], bold=True, align=TA_CENTER))],
            [Paragraph(str(valor), s(17, color, bold=True, align=TA_CENTER))],
            [Paragraph(sub, s(6.5, pal["CM"], align=TA_CENTER))],
        ], colWidths=[40*mm], rowHeights=[5*mm, 9*mm, 4*mm])

    def _kpi_style(bg=pal["CRowAlt"], bd=pal["CBo"]):
        return TableStyle([
            ('BACKGROUND',(0,0),(-1,-1),bg), ('BOX',(0,0),(-1,-1),0.5,bd),
            ('VALIGN',(0,0),(-1,-1),'MIDDLE'), ('TOPPADDING',(0,0),(-1,-1),2),
            ('BOTTOMPADDING',(0,0),(-1,-1),2),
        ])

    k1 = _kpi("Colaciones", f"{int(tot_col):,}")
    k1.setStyle(_kpi_style())
    k2 = _kpi("Turnos", f"{int(tot_tur):,}")
    k2.setStyle(_kpi_style())
    k3 = _kpi("Personas", f"{n_pers:,}")
    k3.setStyle(_kpi_style())
    k4 = _kpi("Colac./Turno", ratio_txt, color=est_col, sub=estado.upper())
    k4.setStyle(TableStyle([
        ('BACKGROUND',(0,0),(-1,-1),rc.HexColor('#faf6ee')),
        ('BOX',(0,0),(-1,-1),1.2,est_col),
        ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
        ('TOPPADDING',(0,0),(-1,-1),2),('BOTTOMPADDING',(0,0),(-1,-1),2),
    ]))
    kpis = Table([[k1, k2, k3, k4]], colWidths=[42*mm]*4)
    kpis.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'MIDDLE'),
        ('LEFTPADDING',(0,0),(-1,-1),3),('RIGHTPADDING',(0,0),(-1,-1),3)]))
    story += [kpis, Spacer(1, 3*mm)]
    story += [Paragraph(
        "Ratio = colaciones servidas ÷ turnos trabajados. "
        "Referencia: &lt; 2,5 Normal · 2,5–3,0 Atención · &gt; 3,0 Alto.",
        s(7.5, pal["CM"])), Spacer(1, 6*mm)]

    # ════════ 2) DESGLOSE DIARIO ════════
    story += [Paragraph("📅 DESGLOSE DIARIO", s(11, pal["CG"], bold=True)),
              Spacer(1, 3*mm)]
    _DOW = {0:"Lun",1:"Mar",2:"Mié",3:"Jue",4:"Vie",5:"Sáb",6:"Dom"}
    if df_dia is None or df_dia.empty:
        story += [Paragraph("Sin movimiento diario en el período.", s(9, pal["CM"]))]
    else:
        dd = df_dia.sort_values("fecha").copy()
        head = [Paragraph(h, s(8, pal["CHdT"], bold=True, align=a)) for h, a in
                [("Fecha", TA_LEFT), ("Día", TA_LEFT), ("Colaciones", TA_RIGHT),
                 ("Turnos", TA_RIGHT), ("Col./Turno", TA_RIGHT), ("Estado", TA_CENTER)]]
        rows = [head]
        for _, r in dd.iterrows():
            f = _pd.Timestamp(r["fecha"])
            rr = r.get("ratio")
            est, ecol = _sem(rr)
            rtxt = (f"{rr:.2f}".replace(".", ",")) if not _pd.isna(rr) else "—"
            rows.append([
                Paragraph(f.strftime("%d-%m-%Y"), s(8, pal["CT"])),
                Paragraph(_DOW[f.weekday()], s(8, pal["CT"])),
                Paragraph(f"{int(r['colaciones']):,}", s(8, pal["CT"], align=TA_RIGHT)),
                Paragraph(f"{int(r['turnos']):,}", s(8, pal["CT"], align=TA_RIGHT)),
                Paragraph(rtxt, s(8, ecol, bold=True, align=TA_RIGHT)),
                Paragraph(est, s(7.5, ecol, bold=True, align=TA_CENTER)),
            ])
        # fila total
        rows.append([
            Paragraph("TOTAL", s(8, pal["CB"], bold=True)),
            Paragraph("", s(8, pal["CT"])),
            Paragraph(f"{int(tot_col):,}", s(8, pal["CB"], bold=True, align=TA_RIGHT)),
            Paragraph(f"{int(tot_tur):,}", s(8, pal["CB"], bold=True, align=TA_RIGHT)),
            Paragraph(ratio_txt, s(8, est_col, bold=True, align=TA_RIGHT)),
            Paragraph(estado, s(7.5, est_col, bold=True, align=TA_CENTER)),
        ])
        t = Table(rows, colWidths=[30*mm, 18*mm, 32*mm, 28*mm, 30*mm, 30*mm], repeatRows=1)
        ts = [('BACKGROUND',(0,0),(-1,0),pal["CHd"]),
              ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
              ('TOPPADDING',(0,0),(-1,-1),3),('BOTTOMPADDING',(0,0),(-1,-1),3),
              ('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),
              ('LINEBELOW',(0,0),(-1,0),0.8,pal["CG"]),
              ('LINEABOVE',(0,-1),(-1,-1),0.8,pal["CB"]),
              ('BACKGROUND',(0,-1),(-1,-1),pal["CRowAlt"]),
              ('GRID',(0,1),(-1,-2),0.3,pal["CBo"])]
        for i in range(1, len(rows)-1):
            if i % 2 == 0:
                ts.append(('BACKGROUND',(0,i),(-1,i),pal["CRowAlt"]))
        t.setStyle(TableStyle(ts))
        story += [t]
    story += [Spacer(1, 6*mm)]

    # ════════ 3) LISTA DEL PERSONAL ════════
    story += [Paragraph("👥 PERSONAL DEL LOCAL", s(11, pal["CG"], bold=True)),
              Spacer(1, 3*mm)]
    if df_pers is None or df_pers.empty:
        story += [Paragraph("Sin personal con asistencia en el período.", s(9, pal["CM"]))]
    else:
        # Orden jerárquico de cargos (de mayor a menor responsabilidad)
        _JERARQUIA = [
            "Administrador", "Sub Administrador",
            "Jefe de Producción", "Subjefe de Producción", "Sub Jefe de Producción",
            "Jefe de Cocina", "Sub Jefe de Cocina",
            "Jefe de Salón", "Sub Jefe de Salón",
            "Jefe de Barra", "Sub Jefe de Barra",
            "Parrillero", "Bartender",
            "Cajero (a)", "Anfitrión (a)", "Anfitriona de reservas",
            "Anfitriona de delivery", "Encargado de delivery",
            "Garzón", "Runner", "Ayudante de Cocina", "Copero",
            "Bodeguero (a)", "Conserje", "Chofer", "Sin Cargo",
        ]
        def _rango(cargo):
            c = str(cargo or "Sin Cargo")
            return _JERARQUIA.index(c) if c in _JERARQUIA else len(_JERARQUIA)

        pp = df_pers.copy()
        pp["_rango"] = pp["cargo"].apply(_rango)
        # dentro de cada cargo: por turnos desc (nulos al final), luego nombre
        pp["_turnos_sort"] = pd.to_numeric(pp["turnos"], errors="coerce").fillna(-1)
        pp = pp.sort_values(["_rango", "_turnos_sort", "nombre"],
                            ascending=[True, False, True])

        head = [Paragraph(h, s(8, pal["CHdT"], bold=True, align=a)) for h, a in
                [("#", TA_CENTER), ("Colaborador", TA_LEFT), ("Cargo", TA_LEFT),
                 ("Turnos", TA_RIGHT), ("Colación prom.", TA_RIGHT)]]
        rows = [head]
        _cargo_rows = []   # filas que son subtítulo de grupo de cargo (para estilo)
        _alt_rows = []     # filas de datos para sombreado alterno
        _cargo_actual = None
        _idx = 0
        for _, r in pp.iterrows():
            _cargo = str(r.get("cargo") or "Sin Cargo")
            if _cargo != _cargo_actual:
                _cargo_actual = _cargo
                rows.append([Paragraph(_cargo.upper(),
                            s(7.5, pal["CB"], bold=True)), "", "", "", ""])
                _cargo_rows.append(len(rows) - 1)
            _idx += 1
            cmin = r.get("colacion_min_prom")
            cmin_txt = (f"{int(round(cmin))} min"
                        if cmin is not None and not _pd.isna(cmin) and cmin else "—")
            turnos = r.get("turnos")
            turnos_txt = (f"{int(turnos):,}"
                          if turnos is not None and not _pd.isna(turnos) else "—")
            rows.append([
                Paragraph(str(_idx), s(8, pal["CM"], align=TA_CENTER)),
                Paragraph(str(r["nombre"]), s(8, pal["CT"])),
                Paragraph(_cargo, s(7.5, pal["CM"])),
                Paragraph(turnos_txt, s(8, pal["CT"], align=TA_RIGHT)),
                Paragraph(cmin_txt, s(8, pal["CT"], align=TA_RIGHT)),
            ])
            if (len(rows) - 1) % 2 == 0:
                _alt_rows.append(len(rows) - 1)
        t2 = Table(rows, colWidths=[10*mm, 66*mm, 44*mm, 24*mm, 34*mm], repeatRows=1)
        ts2 = [('BACKGROUND',(0,0),(-1,0),pal["CHd"]),
               ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
               ('TOPPADDING',(0,0),(-1,-1),3),('BOTTOMPADDING',(0,0),(-1,-1),3),
               ('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),
               ('LINEBELOW',(0,0),(-1,0),0.8,pal["CG"]),
               ('GRID',(0,1),(-1,-1),0.3,pal["CBo"])]
        # subtítulos de cargo: fondo destacado y celda fusionada
        for _cr in _cargo_rows:
            ts2.append(('SPAN',(0,_cr),(-1,_cr)))
            ts2.append(('BACKGROUND',(0,_cr),(-1,_cr),pal["CRowAlt"]))
            ts2.append(('LINEBELOW',(0,_cr),(-1,_cr),0.4,pal["CG"]))
        t2.setStyle(TableStyle(ts2))
        story += [t2]

    # ── Pie ──
    story += [Spacer(1, 8*mm),
              HRFlowable(width="100%", color=pal["CBo"], thickness=0.5),
              Spacer(1, 2*mm),
              Paragraph("Alemán Experto · Control de Gestión — documento interno.",
                        s(7, pal["CM"], align=TA_CENTER))]

    doc.build(story)
    buf.seek(0)
    return buf.getvalue()


def _cr_conclusion_local(sub, periodos, modo, cp_red, caso):
    """Conclusión específica: tendencia real + diagnóstico de caso + recomendación graduada."""
    import pandas as _pd
    vals = [(p, sub.loc[p, "col_x_turno"]) for p in periodos
            if not _pd.isna(sub.loc[p, "col_x_turno"])]
    if not vals:
        return "Sin datos suficientes para analizar este local en el período."
    ult_p, ult_v = vals[-1]
    cp_ult = sub.loc[ult_p, "col_x_persona"]
    partes = []

    # 1) Tendencia (solo si hay 2+ períodos con dato)
    if len(vals) >= 2:
        prev_p, prev_v = vals[-2]
        if prev_v and prev_v > 0:
            chg = (ult_v - prev_v) / prev_v * 100
            if abs(chg) < 5:
                partes.append(f"El ratio se mantuvo estable ({prev_v:.2f}→{ult_v:.2f}) "
                              f"entre {prev_p} y {ult_p}.")
            else:
                verbo = "aumentó" if chg > 0 else "disminuyó"
                intens = "fuertemente" if abs(chg) >= 25 else "moderadamente"
                partes.append(f"El ratio {verbo} {intens} {abs(chg):.0f}% "
                              f"({prev_v:.2f}→{ult_v:.2f}) entre {prev_p} y {ult_p}.")

    # 2) Diagnóstico según caso + magnitud
    exceso = ult_v - _CR_UMBRAL_CT
    if caso == "A":
        partes.append(
            f"Con {ult_v:.2f} colaciones por turno ({exceso:+.2f} sobre el umbral de "
            f"{_CR_UMBRAL_CT:.1f}) y {cp_ult:.0f} por persona, el consumo es alto en ambas "
            "dimensiones. <b>Recomendación:</b> revisar la política de colaciones del local "
            "y auditar una muestra de jornadas; es el patrón con mayor exposición.")
    elif caso == "B":
        partes.append(
            f"El consumo por jornada ({ult_v:.2f}) está en rango, pero las {cp_ult:.0f} "
            "colaciones por persona están por sobre la red: el consumo se concentra en "
            "pocos trabajadores. <b>Recomendación:</b> identificar a quiénes acumulan "
            "colaciones y validar que correspondan a turnos reales.")
    elif caso == "C":
        partes.append(
            f"Las {ult_v:.2f} colaciones por turno superan el umbral, pero repartidas "
            f"entre la dotación ({cp_ult:.0f} por persona, en rango). Esto suele indicar "
            "que faltan turnos por registrar en asistencia más que un sobreconsumo. "
            "<b>Recomendación:</b> verificar la carga de asistencia del período antes de "
            "concluir que hay exceso de colaciones.")
    else:  # D
        partes.append(
            f"Con {ult_v:.2f} colaciones por turno y {cp_ult:.0f} por persona, el local "
            "opera dentro de lo esperado. <b>Recomendación:</b> sin acción; mantener el "
            "monitoreo en los próximos períodos.")
    return " ".join(partes)


def generar_pdf_colaciones_empresa(comp, modo, fi, ff, df_pers_dia=None):
    R = _cr_pdf_base()
    mm = R["mm"]; pal = R["pal"]; PS = R["ParagraphStyle"]
    TA_LEFT, TA_CENTER, TA_JUSTIFY = R["TA_LEFT"], R["TA_CENTER"], R["TA_JUSTIFY"]
    Paragraph, Spacer, Table, TableStyle = R["Paragraph"], R["Spacer"], R["Table"], R["TableStyle"]
    HRFlowable, RLImage, PageBreak = R["HRFlowable"], R["RLImage"], R["PageBreak"]
    import io as _io, pandas as _pd

    def s(sz, col, bold=False, align=TA_LEFT):
        return PS('_', fontSize=sz, textColor=col,
                  fontName='Helvetica-Bold' if bold else 'Helvetica',
                  alignment=align, leading=sz*1.35)

    buf = _io.BytesIO()
    doc = R["SimpleDocTemplate"](buf, pagesize=R["A4"],
        leftMargin=15*mm, rightMargin=15*mm, topMargin=12*mm, bottomMargin=12*mm)
    story = []

    logo = Spacer(24*mm, 20*mm)
    if R["os"].path.exists(LOGO_PATH):
        logo = RLImage(LOGO_PATH, width=22*mm, height=22*mm)
    hdr = Table([[logo,
        [Paragraph("COLACIONES RRHH — RESUMEN EMPRESA", s(15, pal["CG"], bold=True, align=TA_CENTER)),
         Paragraph("Consolidado de la red · Alemán Experto", s(8.5, pal["CM"], align=TA_CENTER))]]],
        colWidths=[26*mm, 154*mm])
    hdr.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'MIDDLE'),
        ('LINEBELOW',(0,0),(-1,0),1.5,pal["CG"]), ('BOTTOMPADDING',(0,0),(-1,-1),5)]))
    story += [hdr, Spacer(1, 4*mm)]
    story += _cr_metodologia_flow(R, modo, fi, ff)
    story += [Spacer(1, 3*mm), HRFlowable(width="100%", color=pal["CBo"], thickness=0.5),
              Spacer(1, 3*mm)]

    periodos = sorted(comp["periodo"].unique())
    ult = periodos[-1]
    cp_red = comp[comp["periodo"] == ult]["col_x_persona"].mean()

    # Consolidado red: turnos y colaciones SÍ se suman entre locales.
    # PERSONAS NO se suman: una persona es una sola persona aunque trabaje
    # en varios días. Se cuentan los RUT DISTINTOS de toda la red por período.
    red = comp.groupby("periodo").agg(
        colaciones=("colaciones", "sum"), turnos=("turnos", "sum")).reindex(periodos)
    # Personas distintas de la red por período (recontadas, no sumadas)
    if df_pers_dia is not None and not df_pers_dia.empty:
        _pr = df_pers_dia.copy()
        _pr["periodo"] = _pr["fecha"].apply(lambda d: _cr_periodo_label(d, modo))
        _pers_red = _pr.groupby("periodo")["rut"].nunique()
        red["personas"] = red.index.map(lambda p: _pers_red.get(p, 0))
    else:
        # Fallback conservador: máximo de personas entre locales (nunca la suma)
        red["personas"] = comp.groupby("periodo")["personas"].max().reindex(periodos)
    red["col_x_turno"] = (red["colaciones"] / red["turnos"].replace(0, _pd.NA)).round(2)
    red["col_x_persona"] = (red["colaciones"] / red["personas"].replace(0, _pd.NA)).round(2)

    # Resumen ejecutivo (texto, arriba)
    story += [Paragraph("RESUMEN EJECUTIVO", s(11, pal["CG"], bold=True)), Spacer(1, 2*mm)]
    for txt in _cr_resumen_ejecutivo(comp, red, periodos, modo, cp_red):
        story += [Paragraph(txt, s(9, pal["CM"], align=TA_JUSTIFY)), Spacer(1, 1.5*mm)]
    story += [Spacer(1, 3*mm)]

    # Gráfico barras ranking último período
    bar = _cr_chart_barras(comp, ult, pal)
    if bar:
        story += [Paragraph(f"RANKING DE LOCALES — {ult}", s(11, pal["CG"], bold=True)),
                  Spacer(1, 2*mm), _cr_img_flow(bar, R, 165), Spacer(1, 4*mm)]

    # Gráfico líneas evolución (solo si 2+ períodos)
    lin = _cr_chart_lineas(comp, periodos)
    if lin:
        story += [Paragraph("EVOLUCIÓN ENTRE PERÍODOS", s(11, pal["CG"], bold=True)),
                  Spacer(1, 2*mm), _cr_img_flow(lin, R, 165), Spacer(1, 4*mm)]

    # Tabla consolidado red
    story += [Paragraph("CONSOLIDADO DE LA RED", s(11, pal["CG"], bold=True)), Spacer(1, 2*mm)]
    head = ["Período", "Colac.", "Turnos", "Personas", "Col/Turno", "Col/Persona"]
    rows = [head]
    for per in periodos:
        r = red.loc[per]
        rows.append([per, f"{int(r['colaciones'])}", f"{int(r['turnos'])}",
                     f"{int(r['personas'])}",
                     "—" if _pd.isna(r["col_x_turno"]) else f"{r['col_x_turno']:.2f}",
                     "—" if _pd.isna(r["col_x_persona"]) else f"{r['col_x_persona']:.2f}"])
    t = Table(rows, colWidths=[32*mm, 24*mm, 24*mm, 26*mm, 28*mm, 30*mm])
    t.setStyle(TableStyle([
        ('BACKGROUND',(0,0),(-1,0),pal["CHd"]), ('TEXTCOLOR',(0,0),(-1,0),pal["CHdT"]),
        ('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'), ('FONTSIZE',(0,0),(-1,-1),8.5),
        ('ALIGN',(1,0),(-1,-1),'CENTER'), ('GRID',(0,0),(-1,-1),0.4,pal["CBo"]),
        ('ROWBACKGROUNDS',(0,1),(-1,-1),[R["rc"].white, pal["CRowAlt"]]),
        ('TEXTCOLOR',(0,1),(-1,-1),pal["CT"]),
        ('TOPPADDING',(0,0),(-1,-1),3.5),('BOTTOMPADDING',(0,0),(-1,-1),3.5),
    ]))
    story += [t, Spacer(1, 5*mm)]

    # Conclusiones y recomendaciones priorizadas
    story += [Paragraph("CONCLUSIONES Y RECOMENDACIONES", s(11, pal["CG"], bold=True)),
              Spacer(1, 2*mm)]
    for txt in _cr_conclusiones_empresa(comp, red, periodos, modo, cp_red):
        story += [Paragraph(txt, s(8.5, pal["CM"], align=TA_JUSTIFY)), Spacer(1, 2*mm)]

    doc.build(story)
    buf.seek(0)
    return buf.getvalue()


def _cr_resumen_ejecutivo(comp, red, periodos, modo, cp_red):
    """2-3 frases que sintetizan la situación de la red."""
    import pandas as _pd
    ult = periodos[-1]
    rank = comp[comp["periodo"] == ult].dropna(subset=["col_x_turno"])
    out = []
    red_ct = red.loc[ult, "col_x_turno"]
    n_alerta = int((rank["col_x_turno"] > _CR_UMBRAL_CT).sum())
    n_total = len(rank)
    if not _pd.isna(red_ct):
        estado = ("por sobre" if red_ct > _CR_UMBRAL_CT else "por debajo de")
        out.append(
            f"En {ult}, la red registró <b>{int(red.loc[ult,'colaciones'])} colaciones</b> "
            f"sobre {int(red.loc[ult,'turnos'])} turnos, un promedio de <b>{red_ct:.2f} "
            f"colaciones por turno</b> ({estado} el umbral de {_CR_UMBRAL_CT:.1f}).")
    if n_total:
        if n_alerta == 0:
            out.append(f"Ninguno de los {n_total} locales superó el umbral de alerta.")
        else:
            peor = rank.sort_values("col_x_turno", ascending=False).iloc[0]
            out.append(
                f"<b>{n_alerta} de {n_total} locales</b> superaron el umbral. El más "
                f"alto es <b>{peor['local']}</b> con {peor['col_x_turno']:.2f} "
                f"colaciones por turno.")
    return out


def _cr_conclusiones_empresa(comp, red, periodos, modo, cp_red):
    """Conclusiones priorizadas: cada local en alerta con su diagnóstico de caso."""
    import pandas as _pd
    out = []
    ult = periodos[-1]
    rank = comp[comp["periodo"] == ult].dropna(subset=["col_x_turno"]).sort_values(
        "col_x_turno", ascending=False)

    # Tendencia de red
    rv = [(p, red.loc[p, "col_x_turno"]) for p in periodos
          if not _pd.isna(red.loc[p, "col_x_turno"])]
    if len(rv) >= 2 and rv[-2][1]:
        chg = (rv[-1][1] - rv[-2][1]) / rv[-2][1] * 100
        if abs(chg) >= 5:
            verbo = "subió" if chg > 0 else "bajó"
            out.append(f"• <b>Red:</b> el ratio promedio {verbo} {abs(chg):.0f}% "
                       f"({rv[-2][1]:.2f}→{rv[-1][1]:.2f}) respecto al período anterior.")
        else:
            out.append(f"• <b>Red:</b> el ratio promedio se mantuvo estable "
                       f"(~{rv[-1][1]:.2f} colaciones por turno).")

    # Cada local en alerta, ordenado por severidad, con su caso
    en_alerta = rank[rank["col_x_turno"] > _CR_UMBRAL_CT]
    if en_alerta.empty:
        out.append("• <b>Sin locales en alerta:</b> todos operan bajo el umbral de "
                   f"{_CR_UMBRAL_CT:.1f} colaciones por turno. Mantener monitoreo.")
    else:
        for rank_i, (_, r) in enumerate(en_alerta.iterrows(), start=1):
            caso, desc = _cr_clasificar(r["col_x_turno"], r["col_x_persona"], cp_red)
            prio = "Prioridad alta" if rank_i == 1 else ("Prioridad media" if rank_i <= 3 else "Seguimiento")
            out.append(
                f"• <b>{r['local']}</b> ({prio}) — {r['col_x_turno']:.2f} col/turno, "
                f"{r['col_x_persona']:.0f} col/persona. <b>Caso {caso}:</b> {desc}")

    # Locales con sub-registro posible (ratio muy bajo)
    bajos = rank[rank["col_x_turno"] < _CR_UMBRAL_CT * 0.4]
    if not bajos.empty:
        nombres = ", ".join(f"{r['local']} ({r['col_x_turno']:.2f})" for _, r in bajos.iterrows())
        out.append(
            f"• <b>Registro bajo:</b> {nombres} están muy por debajo del resto. Verificar "
            "que las colaciones se carguen como venta CP; un ratio así suele ser "
            "sub-registro, no ausencia de consumo.")

    out.append(
        "• <b>Control de calidad:</b> este indicador depende de que colaciones (venta CP) "
        "y asistencia se registren íntegramente. Validar la captura antes de accionar "
        "sobre un local con ratio extremo.")
    return out


# ===========================================================================
#  RESUMEN DE COLORES (réplica de la foto) — 1 página horizontal
#  Ranking triple (DAX): (rankVdp + rankPctTotal - venta/1e10)/2, ascendente.
#  Colores por posición de ranking: verde (mejores) / amarillo (medio) / rojo.
# ===========================================================================
# ===========================================================================
#  CUMPLIMIENTO DE METAS (Cafetería/Postres) — cuadro mensual 1 pág horizontal
# ===========================================================================
def _cm_pct_color_estado(meta, real):
    pct = (real/meta*100) if meta else 0.0
    if pct >= 100:   color = "verde"; estado = "✔ CUMPLE"
    elif pct >= 90:  color = "ambar"; estado = "✘ NO CUMPLE"
    else:            color = "rojo";  estado = "✘ NO CUMPLE"
    return pct, color, estado

def generar_pdf_cumplimiento_metas(rows, tot, mes_label, meta_col_label="Meta Mensual",
                                   nota=None, logo_path=None,
                                   rows2=None, tot2=None, meta_col_label2=None,
                                   subtitulo1=None, subtitulo2=None):
    """rows: lista de dicts {local, mc, rc, mp, rp}. tot: {mc,rc,mp,rp}.
    Si rows2/tot2 se entregan, dibuja un SEGUNDO cuadro idéntico debajo
    (p. ej. cuadro 1 = meta proyectada, cuadro 2 = meta mensual total)."""
    import io as _io
    from reportlab.lib.pagesizes import letter, landscape
    from reportlab.lib import colors
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.enums import TA_CENTER, TA_LEFT
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer

    VERDE = colors.HexColor("#C6EFCE"); VERDE_T = colors.HexColor("#1E7B34")
    AMBAR = colors.HexColor("#FFEB9C"); AMBAR_T = colors.HexColor("#9C6500")
    ROJO  = colors.HexColor("#FFC7CE"); ROJO_T  = colors.HexColor("#9C0006")
    GRIS  = colors.HexColor("#D9D9D9"); AZUL = colors.HexColor("#1F3864")
    BORDE = colors.HexColor("#808080")
    _cfill = {"verde": VERDE, "ambar": AMBAR, "rojo": ROJO}
    _ctext = {"verde": VERDE_T, "ambar": AMBAR_T, "rojo": ROJO_T}

    stt = ParagraphStyle("t", fontName="Helvetica-Bold", fontSize=12.5, alignment=TA_CENTER, leading=15, textColor=AZUL)
    sst = ParagraphStyle("sst", fontName="Helvetica-Bold", fontSize=9.5, alignment=TA_CENTER, leading=12, textColor=AZUL)
    sts = ParagraphStyle("s", fontName="Helvetica", fontSize=7.5, alignment=TA_CENTER, leading=9, textColor=colors.HexColor("#555"))
    sgh = ParagraphStyle("gh", fontName="Helvetica-Bold", fontSize=8.5, alignment=TA_CENTER, leading=10, textColor=colors.white)
    sh  = ParagraphStyle("h", fontName="Helvetica-Bold", fontSize=6.6, alignment=TA_CENTER, leading=8, textColor=colors.white)
    sc  = ParagraphStyle("c", fontName="Helvetica", fontSize=7.2, alignment=TA_CENTER, leading=8.6)
    scl = ParagraphStyle("cl", fontName="Helvetica-Bold", fontSize=7.4, alignment=TA_LEFT, leading=8.6)
    se  = ParagraphStyle("e", fontName="Helvetica-Bold", fontSize=6.3, alignment=TA_CENTER, leading=7.6)

    def _fm(v): return f"{v:,.0f}".replace(",", ".")
    def _fmeta(v): return f"{v:,.0f}".replace(",", ".")
    def _fp(v): return f"{v:.1f}%".replace(".", ",")

    PAG_W = landscape(letter)[0]; MX = 20
    util = PAG_W - 2*MX
    pesos = [3.0, 2.3,1.6,1.5,2.0,  2.3,1.6,1.5,2.0,  2.3,1.6,1.5,2.0]
    sp = sum(pesos); wcols = [util*p/sp for p in pesos]

    def _build_tabla(_rows, _tot, _meta_lbl):
        """Construye la Table de cumplimiento (cabecera + filas + TOTAL RED)."""
        g_row = [Paragraph("LOCAL", sgh),
                 Paragraph("CAFETERÍA", sgh), "", "", "",
                 Paragraph("POSTRES", sgh), "", "", "",
                 Paragraph("TOTAL LOCAL", sgh), "", "", ""]
        sub = ["", _meta_lbl,"Real","Cumpl. %","Estado",
                   _meta_lbl,"Real","Cumpl. %","Estado",
                   _meta_lbl,"Real","Cumpl. %","Estado"]
        h_row = [Paragraph(x, sh) if x else "" for x in sub]
        data = [g_row, h_row]
        cell_styles = []
        r = 2
        for row in _rows:
            cels = [Paragraph(row["local"], scl)]
            for meta, real in [(row["mc"],row["rc"]), (row["mp"],row["rp"]),
                               (row["mc"]+row["mp"], row["rc"]+row["rp"])]:
                pct, color, estado = _cm_pct_color_estado(meta, real)
                base = len(cels)
                cels += [Paragraph(_fmeta(meta), sc), Paragraph(_fm(real), sc),
                         Paragraph(_fp(pct), ParagraphStyle("p", parent=se, textColor=_ctext[color])),
                         Paragraph(estado, ParagraphStyle("es", parent=se, textColor=_ctext[color]))]
                cell_styles.append((base+3, r, _cfill[color]))
                cell_styles.append((base+2, r, _cfill[color]))
            data.append(cels)
            r += 1
        cels = [Paragraph("TOTAL RED", ParagraphStyle("tr", parent=scl, textColor=colors.white))]
        for meta, real in [(_tot["mc"],_tot["rc"]), (_tot["mp"],_tot["rp"]),
                           (_tot["mc"]+_tot["mp"], _tot["rc"]+_tot["rp"])]:
            pct, color, estado = _cm_pct_color_estado(meta, real)
            cels += [Paragraph(_fmeta(meta), ParagraphStyle("w", parent=sc, textColor=colors.white)),
                     Paragraph(_fm(real), ParagraphStyle("w", parent=sc, textColor=colors.white)),
                     Paragraph(_fp(pct), ParagraphStyle("w", parent=se, textColor=colors.white)),
                     Paragraph(estado, ParagraphStyle("w", parent=se, textColor=colors.white))]
        data.append(cels)
        r_total = r
        t = Table(data, colWidths=wcols, repeatRows=2)
        style = [
            ("GRID",(0,0),(-1,-1),0.5,BORDE),
            ("VALIGN",(0,0),(-1,-1),"MIDDLE"),
            ("ALIGN",(0,0),(-1,-1),"CENTER"),
            ("SPAN",(1,0),(4,0)), ("SPAN",(5,0),(8,0)), ("SPAN",(9,0),(12,0)),
            ("SPAN",(0,0),(0,1)),
            ("BACKGROUND",(0,0),(-1,1),AZUL),
            ("TOPPADDING",(0,0),(-1,-1),3),("BOTTOMPADDING",(0,0),(-1,-1),3),
            ("LEFTPADDING",(0,0),(-1,-1),2),("RIGHTPADDING",(0,0),(-1,-1),2),
            ("ROWBACKGROUNDS",(0,2),(-1,r_total-1),[colors.white, colors.HexColor("#F2F2F2")]),
            ("BACKGROUND",(0,r_total),(-1,r_total),AZUL),
        ]
        for (c, rr, col) in cell_styles:
            style.append(("BACKGROUND",(c,rr),(c,rr),col))
        t.setStyle(TableStyle(style))
        return t

    t1 = _build_tabla(rows, tot, meta_col_label)

    buf = _io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=landscape(letter),
                            leftMargin=MX, rightMargin=MX, topMargin=20, bottomMargin=20)
    elems = [
        Paragraph(f"CUADRO RESUMEN · CUMPLIMIENTO DE METAS · {mes_label}", stt),
        Spacer(1,3),
        Paragraph("% Cumplimiento = Ventas Reales ÷ Meta × 100  |  Verde ≥100% · Ámbar 90–99% · Rojo &lt;90%", sts),
    ] + ([Spacer(1,2), Paragraph(nota, ParagraphStyle("n", parent=sts, textColor=colors.HexColor("#9C6500")))] if nota else [])

    # ── Cuadro 1 ──
    if subtitulo1:
        elems += [Spacer(1,8), Paragraph(subtitulo1, sst)]
    elems += [Spacer(1,6), t1]

    # ── Cuadro 2 (opcional): meta total del mes ──
    if rows2 is not None and tot2 is not None:
        t2 = _build_tabla(rows2, tot2, meta_col_label2 or "Meta Mensual")
        elems += [Spacer(1,14)]
        if subtitulo2:
            elems += [Paragraph(subtitulo2, sst), Spacer(1,6)]
        elems += [t2]

    elems += [Spacer(1,6),
        Paragraph("Real: unidades vendidas en Salón (es_opcion=false). 'Providencia' en ventas = 'Pedro de Valdivia' en metas.", sts),
    ]
    doc.build(elems)
    buf.seek(0)
    return buf.getvalue()


def _sg_color_bands(n):
    """Cantidad de verdes/amarillos/rojos según nº de garzones (regla confirmada)."""
    if n <= 0:
        return 0, 0, 0
    if n >= 10:   nv, na = 3, 2
    elif n >= 8:  nv, na = 3, 1
    elif n >= 5:  nv, na = 2, 1     # 5 garzones -> 2/1/2
    elif n >= 3:  nv, na = 1, 1
    else:         nv, na = 1, 0
    nv = min(nv, n)
    na = min(na, max(n - nv, 0))
    nr = max(n - nv - na, 0)
    return nv, na, nr


# Conteos FIJOS por local (verde, amarillo), leídos de las fotos enviadas por el usuario.
# Clave = nombre del local en la BD ('Providencia' se muestra como 'Pedro de Valdivia').
# El orden sigue saliendo del ranking triple; aquí solo se fija CUÁNTOS de cada color.
_SG_COLOR_FIJO = {
    "Vitacura":          (3, 1),
    "Las Condes":        (3, 1),
    "Chicureo":          (3, 1),
    "La Dehesa":         (3, 1),
    "Macul":             (3, 1),
    "Los Trapenses":     (3, 1),
    "La Reina":          (2, 1),
    "Quilin":            (2, 1),
    "Nueva Providencia": (2, 1),
    "Providencia":       (2, 1),   # foto: PEDRO DE VALDIVIA
}


def _sg_bandas_local(local, n):
    """(nv, na, nr) fijos por local (de las fotos). Si el local no está mapeado,
    cae a la regla general. Hace cap si hay menos garzones que verdes+amarillos."""
    par = _SG_COLOR_FIJO.get(local)
    if par is None:
        return _sg_color_bands(n)
    nv, na = par
    nv = min(nv, n)
    na = min(na, max(n - nv, 0))
    nr = max(n - nv - na, 0)
    return nv, na, nr


def _sg_rank_dense_desc(valores):
    """Rank denso descendente (igual que RANKX(...; DESC; DENSE))."""
    uniq = sorted(set(valores), reverse=True)
    pos = {v: i + 1 for i, v in enumerate(uniq)}
    return [pos[v] for v in valores]


def _sg_orden_colores(df_acum, dias_periodo, local=None):
    """Ordena garzones por el ranking triple y asigna color por posición.

    df_acum: DataFrame crudo de la sección 5 acumulado
             (cols: garzon, dias, venta_total, v_agr, v_caf, v_pos, v_lsa, v_lca).
    Devuelve (filas_ordenadas, total).  Cada fila trae los mismos valores que
    muestra la sección 5 (venta, propina=venta*0.10, vdp=venta/dias, %s) + rank + color.
    """
    import re as _re
    def _limpia(n):
        return _re.sub(r'^\S+_', '', str(n or '')).strip()
    g = []
    for _, r in df_acum.iterrows():
        vt = float(r["venta_total"]) or 0.0
        if vt <= 0:
            continue
        dias = int(r["dias"]) or 1
        # AGREGADOS del cuadro = SOLO 'Agregados' (sin Acompañamientos), como el Excel original
        va = float(r["v_agr_solo"]) if ("v_agr_solo" in r.index and pd.notna(r["v_agr_solo"])) else float(r["v_agr"])
        vc, vp = float(r["v_caf"]), float(r["v_pos"])
        vsa, vca = float(r["v_lsa"]), float(r["v_lca"])
        adic = va + vc + vp + vsa + vca
        g.append({
            "nombre": _limpia(r["garzon"]),
            "venta": vt, "propina": vt * 0.10, "vdp": vt / dias, "dias": dias,
            "v_agr": va, "p_agr": va / vt, "v_caf": vc, "p_caf": vc / vt,
            "v_pos": vp, "p_pos": vp / vt, "v_lsa": vsa, "p_sa": vsa / vt,
            "v_lca": vca, "p_ca": vca / vt, "p_total": adic / vt,
        })
    if not g:
        return [], None
    rvp = _sg_rank_dense_desc([x["vdp"] for x in g])
    r2 = _sg_rank_dense_desc([x["p_total"] for x in g])
    comp = [(rvp[i] + r2[i] - g[i]["venta"] / 1e10) / 2 for i in range(len(g))]
    orden = sorted(range(len(g)), key=lambda i: comp[i])
    filas = [g[i] for i in orden]
    nv, na, nr = _sg_bandas_local(local, len(filas))
    colores = ["verde"] * nv + ["amar"] * na + ["rojo"] * nr
    for i, f in enumerate(filas):
        f["rank"] = i + 1
        f["color"] = colores[i] if i < len(colores) else "rojo"
    sv = sum(f["venta"] for f in filas)
    tot = {"nombre": "TOTAL GENERAL", "venta": sv, "propina": sv * 0.10,
           "vdp": (sv / dias_periodo) if dias_periodo else 0, "dias": dias_periodo,
           "v_agr": sum(f["v_agr"] for f in filas), "v_caf": sum(f["v_caf"] for f in filas),
           "v_pos": sum(f["v_pos"] for f in filas), "v_lsa": sum(f["v_lsa"] for f in filas),
           "v_lca": sum(f["v_lca"] for f in filas)}
    for kv, kp in [("v_agr", "p_agr"), ("v_caf", "p_caf"), ("v_pos", "p_pos"),
                   ("v_lsa", "p_sa"), ("v_lca", "p_ca")]:
        tot[kp] = (tot[kv] / sv) if sv else 0
    tot["p_total"] = (sum(tot[k] for k in ("v_agr", "v_caf", "v_pos", "v_lsa", "v_lca")) / sv) if sv else 0
    return filas, tot


def _sg_resumen_colores_pdf(df_acum, local, dias_periodo, logo_path=None):
    """Genera el cuadro resumen con colores (1 página horizontal) y devuelve bytes PDF."""
    import io as _io
    from reportlab.lib.pagesizes import letter as _letter, landscape as _landscape
    from reportlab.lib import colors as _colors
    from reportlab.lib.styles import ParagraphStyle as _PS
    from reportlab.lib.enums import TA_CENTER as _TAC
    from reportlab.platypus import (SimpleDocTemplate as _Doc, Table as _Table,
                                    TableStyle as _TS, Paragraph as _Par, Spacer as _Sp)

    def _fm(v):
        try: return f"${int(round(float(v))):,}".replace(",", ".")
        except: return "$0"
    def _fp(v):
        try: return f"{float(v)*100:.1f}%".replace(".", ",")
        except: return "0,0%"

    filas, tot = _sg_orden_colores(df_acum, dias_periodo, local=local)

    VERDE = _colors.HexColor("#63BE7B"); AMAR = _colors.HexColor("#FFEB84")
    ROJO = _colors.HexColor("#F8696B"); GRIS = _colors.HexColor("#D9D9D9")
    BORDE = _colors.HexColor("#808080")
    _cmap = {"verde": VERDE, "amar": AMAR, "rojo": ROJO}

    st_h = _PS("h", fontName="Helvetica-Bold", fontSize=6.2, alignment=_TAC, leading=7)
    st_c = _PS("c", fontName="Helvetica", fontSize=6.4, alignment=_TAC, leading=7.6)
    st_b = _PS("b", fontName="Helvetica-Bold", fontSize=6.4, alignment=_TAC, leading=7.6)
    st_t = _PS("t", fontName="Helvetica-Bold", fontSize=11, alignment=_TAC, leading=13)
    P = lambda s, e=st_c: _Par(str(s), e)

    headers = ["Rank", "NOMBRE GARZON", "VENTA", "APORTE<br/>PROPINA",
               "VENTA DIARIA<br/>PROMEDIO", "DIAS<br/>TRAB", "VENTA<br/>AGREGADOS",
               "%<br/>AGREGADO", "VENTA<br/>CAFETERIA", "%<br/>CAFETERIA",
               "VENTA<br/>POSTRES", "%<br/>POSTRES", "VENTA LIQ<br/>S/A", "% LIQ<br/>S/A",
               "VENTA LIQ<br/>C/A", "% LIQ<br/>C/A", "% TOTAL"]
    head = [P(h, st_h) for h in headers]

    def fila_de(f, bold=False):
        e = st_b if bold else st_c
        return [P(f.get("rank", ""), e), P(f["nombre"], e), P(_fm(f["venta"]), e),
                P(_fm(f["propina"]), e), P(_fm(f["vdp"]), e), P(f["dias"], e),
                P(_fm(f["v_agr"]), e), P(_fp(f["p_agr"]), e), P(_fm(f["v_caf"]), e),
                P(_fp(f["p_caf"]), e), P(_fm(f["v_pos"]), e), P(_fp(f["p_pos"]), e),
                P(_fm(f["v_lsa"]), e), P(_fp(f["p_sa"]), e), P(_fm(f["v_lca"]), e),
                P(_fp(f["p_ca"]), e), P(_fp(f["p_total"]), e)]

    data = [head]
    for f in filas:
        data.append(fila_de(f))
    if tot:
        data.append(fila_de(tot, bold=True))

    PAG_W = _landscape(_letter)[0]
    MX = 22
    util = PAG_W - 2 * MX
    pesos = [3.2, 12, 7.2, 6.6, 7.2, 3.6, 6.6, 5, 6.6, 5, 6.6, 5, 6.6, 5, 6.6, 5, 5.6]
    sp = sum(pesos)
    wcols = [util * p / sp for p in pesos]

    t = _Table(data, colWidths=wcols, repeatRows=1)
    estilo = [
        ("GRID", (0, 0), (-1, -1), 0.5, BORDE),
        ("BACKGROUND", (0, 0), (-1, 0), GRIS),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("ALIGN", (0, 0), (-1, -1), "CENTER"),
        ("TOPPADDING", (0, 0), (-1, -1), 2.5),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 2.5),
        ("LEFTPADDING", (0, 0), (-1, -1), 2),
        ("RIGHTPADDING", (0, 0), (-1, -1), 2),
    ]
    for i, f in enumerate(filas):
        estilo.append(("BACKGROUND", (0, i + 1), (-1, i + 1), _cmap.get(f["color"], ROJO)))
    if tot:
        estilo.append(("BACKGROUND", (0, len(filas) + 1), (-1, len(filas) + 1), GRIS))
    t.setStyle(_TS(estilo))

    buf = _io.BytesIO()
    doc = _Doc(buf, pagesize=_landscape(_letter),
               leftMargin=MX, rightMargin=MX, topMargin=18, bottomMargin=18)
    _titulo_loc = "Pedro de Valdivia" if str(local) == "Providencia" else str(local)
    doc.build([_Par(_titulo_loc.upper(), st_t), _Sp(1, 6), t])
    buf.seek(0)
    return buf.getvalue()


def _sg_construir_ctx_b(local, ini, fin, ng, jef, ranking,
                        s1, s2, s3, s4, rows5, rows5_sem, s6_raw, s7, rows9, g10,
                        s9_raw=None, s11s=None, s11m=None):
    """Mapea los datos calculados al esquema 'ctx' que espera generar_pdf_garzones_b.

    Parámetros nuevos (opcionales, no rompen llamadas previas):
      s9_raw : DataFrame crudo sección 9  (cols: garzon, iso_week, venta, adic)
      s11s   : DataFrame crudo comportamiento semanal (cols: local, iso_week, venta, adic)
      s11m   : DataFrame crudo comportamiento mensual (cols: local, mes 'YYYY-MM', venta, adic)
    """
    import pandas as _pd

    def _money_to_int(x):
        """'$9.448.490' -> 9448490 ; números pasan directo."""
        if isinstance(x, (int, float)):
            return int(x)
        s = str(x).replace("$", "").replace(".", "").replace(",", "").strip()
        try: return int(s)
        except: return 0

    def _pct_to_frac(x):
        """'82.6%' -> 0.826 ; floats que ya son fracción pasan."""
        if isinstance(x, (int, float)):
            return float(x)
        s = str(x).replace("%", "").replace(",", ".").strip()
        try: return float(s) / 100.0
        except: return 0.0

    # ---- Sección 1 y 2 (desde DataFrame con rollup) ----
    def _ventas_block(df):
        if df is None or df.empty:
            return {"filas": [], "total": {}}
        order = ["ALIMENTOS","BAR","CAFETERÍA Y POSTRES"]
        di = df.set_index("macro")
        tot_acum = float(di.loc["TOTAL","venta_acum"]) if "TOTAL" in di.index else 0
        tot_sem = float(di.loc["TOTAL","venta_sem"]) if "TOTAL" in di.index else 0
        dias_acum = max((fin - ini.replace(day=1)).days + 1, 1)
        filas = []
        for m in order:
            if m not in di.index: continue
            r = di.loc[m]
            va, vs = float(r["venta_acum"]), float(r["venta_sem"])
            qa, qs = int(r["q_acum"]), int(r["q_sem"])
            filas.append({
                "item": m, "acum": int(va), "acum_q": qa,
                "acum_pct": va/tot_acum if tot_acum else 0,
                "diario": int(va/dias_acum), "diario_q": int(round(qa/dias_acum)),
                "diario_pct": (va/dias_acum)/tot_acum if tot_acum else 0,
                "semanal": int(vs), "semanal_q": qs,
                "semanal_pct": vs/tot_sem if tot_sem else 0,
            })
        total = {"item":"TOTAL VENTA SALÓN","acum":int(tot_acum),
                 "acum_q":int(di.loc["TOTAL","q_acum"]) if "TOTAL" in di.index else 0,
                 "acum_pct":1.0,"diario":int(tot_acum/dias_acum),
                 "diario_q":int(round((di.loc["TOTAL","q_acum"] if "TOTAL" in di.index else 0)/dias_acum)),
                 "diario_pct":0.0,"semanal":int(tot_sem),
                 "semanal_q":int(di.loc["TOTAL","q_sem"]) if "TOTAL" in di.index else 0,
                 "semanal_pct":None}
        return {"filas": filas, "total": total}

    # ---- Sección 3 subcategorías (desde DataFrame por categoria_menu) ----
    def _subcats_block(df):
        if df is None or df.empty:
            return []
        di = df.set_index("categoria_menu")
        dias_acum = max((fin - ini.replace(day=1)).days + 1, 1)
        ng_div = max(ng, 1)
        # total evaluado para %
        tot_eval = float(di["venta_acum"].sum()) if "venta_acum" in di.columns else 0
        bloques_def = [
            ("VENTAS ALIMENTOS", [
                ("PARA COMPARTIR", ["Para Compartir"]),
                ("SANDWICH Y HAMBURGUESAS", ["Sandwich Clasicos","Churrasco Clasico","Pernil Clasico",
                    "Hamburguesa De La Casa","Hamburguesa De Quinoa","Hamburguesa Clasica","Mechada Clasica",
                    "Filete Clasico","Lomito Clasico","Ave Clasica"]),
                ("ENSALADAS Y OTROS", ["Ensaladas Y Otros"]),
                ("PLATOS", ["Platos Clasicos","Platos Alemanes"]),
                ("AGREGADOS Y ACOMPAÑAMIENTOS", ["Agregados","Acompanamientos"]),
                ("NIÑOS", ["Ninos"]),
            ]),
            ("VENTAS CAFETERÍA Y POSTRES", [
                ("CAFETERÍA", ["Cafeteria"]), ("POSTRES", ["Postres"]),
            ]),
            ("VENTAS LÍQUIDOS C/A", [
                ("CERVEZAS", ["Cervezas"]),
                ("TRAGOS Y COCTAILS", ["Cocteles","Piscos","Ron","Tequila","Vodka","Whisky","Bajativos"]),
                ("VINOS Y ESPUMANTES", ["Vinos","Espumantes"]),
            ]),
            ("VENTAS LÍQUIDOS S/A", [
                ("BEBIDAS Y AGUAS", ["Bebidas"]),
                ("JUGOS, LIMONADAS Y TRAGOS S/A", ["Jugos Naturales","Limonadas","Tragos Sin Alcohol"]),
            ]),
        ]
        out = []
        for titulo, casos in bloques_def:
            filas = []; t_a=t_s=t_qa=t_qs=0
            for etiqueta, cats in casos:
                va=vs=qa=qs=0
                for c in cats:
                    if c in di.index:
                        r=di.loc[c]
                        va+=float(r["venta_acum"]); vs+=float(r["venta_sem"])
                        qa+=float(r["q_acum"]); qs+=float(r["q_sem"])
                filas.append({"item":etiqueta,"acum":int(va),"acum_q":round(qa/ng_div,0),
                    "acum_pct":va/tot_eval if tot_eval else 0,
                    "diario":int(va/dias_acum),"diario_q":round(qa/dias_acum/ng_div,0),
                    "diario_pct":(va/dias_acum)/tot_eval if tot_eval else 0,
                    "semanal":int(vs),"semanal_q":round(qs/ng_div,0),
                    "semanal_pct":vs/tot_eval if tot_eval else 0})
                t_a+=va; t_s+=vs; t_qa+=qa; t_qs+=qs
            total={"item":"TOTAL","acum":int(t_a),"acum_q":round(t_qa/ng_div,0),
                "acum_pct":t_a/tot_eval if tot_eval else 0,"diario":int(t_a/dias_acum),
                "diario_q":round(t_qa/dias_acum/ng_div,0),"diario_pct":(t_a/dias_acum)/tot_eval if tot_eval else 0,
                "semanal":int(t_s),"semanal_q":round(t_qs/ng_div,0),"semanal_pct":t_s/tot_eval if tot_eval else 0}
            out.append({"titulo":titulo,"filas":filas,"total":total})
        return out

    # ---- Sección 5 (desde rows ya formateadas) ----
    def _sec5_block(rows):
        if not rows:
            return {"filas": [], "total": {}}
        filas = []
        for r in rows:
            filas.append({
                "nombre": _igb_safe(r.get("Garzón","")),
                "venta": _money_to_int(r.get("Venta",0)),
                "propina": _money_to_int(r.get("Aporte Propina",0)),
                "venta_diaria_prom": _money_to_int(r.get("Vta Diaria Prom",0)),
                "dias": int(r.get("Días",0) or 0),
                "v_agreg": _money_to_int(r.get("Agreg.",0)), "q_agreg": int(r.get("Q Ag",0) or 0),
                "p_agreg": _pct_to_frac(r.get("%Ag",0)),
                "v_cafe": _money_to_int(r.get("Café",0)), "q_cafe": int(r.get("Q Cf",0) or 0),
                "p_cafe": _pct_to_frac(r.get("%Cf",0)),
                "v_post": _money_to_int(r.get("Postres",0)), "q_post": int(r.get("Q Po",0) or 0),
                "p_post": _pct_to_frac(r.get("%Po",0)),
                "v_liqsa": _money_to_int(r.get("Líq S/A",0)), "q_liqsa": int(r.get("Q SA",0) or 0),
                "p_liqsa": _pct_to_frac(r.get("%SA",0)),
                "v_liqca": _money_to_int(r.get("Líq C/A",0)), "q_liqca": int(r.get("Q CA",0) or 0),
                "p_liqca": _pct_to_frac(r.get("%CA",0)),
                "p_total": _pct_to_frac(r.get("%Total",0)),
            })
        return {"filas": filas, "total": {}}

    # ---- Sección 4 estratégicos (desde rows4 formateadas) ----
    def _estrat_block(rows):
        if not rows:
            return {"filas": [], "total": {}}
        filas=[]; total={}
        for r in rows:
            d={"item":_igb_safe(r.get("Ítem","")),
               "acum":_money_to_int(r.get("$ Acumulado",0)),
               "acum_q":int(r.get("Q",0) or 0),
               "acum_pct":_pct_to_frac(r.get("%",0)),
               "diario":_money_to_int(r.get("$ Diario",0)),"diario_q":0,"diario_pct":0,
               "semanal":_money_to_int(r.get("$ Semanal",0)),
               "semanal_q":int(r.get("Q",0) or 0),"semanal_pct":_pct_to_frac(r.get("%",0))}
            if str(d["item"]).upper().startswith("TOTAL"): total=d
            else: filas.append(d)
        return {"filas":filas,"total":total}

    # ---- Sección 6 adicionales por local (desde DataFrame _s6 con pct_*) ----
    def _adic_local_block(df):
        if df is None or df.empty:
            return {"filas": [], "total": {}}
        filas=[]
        for _,r in df.iterrows():
            loc = r.get("Local", r.get("local",""))
            filas.append({"local":str(loc).upper(),
                "p_agreg":float(r.get("pct_ag",0))/100,"p_cafe":float(r.get("pct_cf",0))/100,
                "p_post":float(r.get("pct_po",0))/100,"p_liqsa":float(r.get("pct_sa",0))/100,
                "p_liqca":float(r.get("pct_ca",0))/100,"p_total":float(r.get("pct_total",0))/100})
        return {"filas":filas,"total":{}}

    # ---- Sección 7 estratégicos por local (desde DataFrame s7 long) ----
    def _estrat_local_block(df):
        if df is None or df.empty:
            return {"filas": [], "total": {}}
        try:
            piv = df.pivot_table(index="local", columns="nombre_producto",
                                 values="q_x_garzon", aggfunc="sum", fill_value=0)
        except Exception:
            return {"filas": [], "total": {}}
        mp = {"Aji Verde":"aji","Alcaparra":"alcaparra","Mayonesa Trufada":"mayonesa",
              "Salsa a la pimienta":"salsa_pimienta","Salsa Queso Azul":"salsa_azul"}
        filas=[]
        for loc, row in piv.iterrows():
            d={"local":str(loc).upper()}; tot=0
            for col,key in mp.items():
                v=int(round(row[col])) if col in piv.columns else 0
                d[key]=v; tot+=v
            d["total"]=tot; filas.append(d)
        return {"filas":filas,"total":{}}

    # ---- Helpers de nombre / periodo (replican la lógica on-screen) ----
    import re as _re
    def _limpia_nombre(n):
        """'12345_Juan Perez' -> 'Juan Perez' (igual que _sg_limpia_nombre on-screen)."""
        return _re.sub(r'^\S+_', '', str(n or '')).strip()

    _MESES_ABBR = {1:"ene",2:"feb",3:"mar",4:"abr",5:"may",6:"jun",
                   7:"jul",8:"ago",9:"sep",10:"oct",11:"nov",12:"dic"}
    def _lab_mes(praw):
        """'2026-03' -> 'mar-2026'. Si no parsea, devuelve el valor crudo."""
        try:
            y, m = str(praw).split("-")[:2]
            return f"{_MESES_ABBR[int(m)]}-{y}"
        except Exception:
            return str(praw)

    # ---- Sección 9: adicionales_por_garzon_anual (desde s9_raw crudo) ----
    def _sec9_anual_block(df):
        """Cols esperadas: garzon, iso_week, venta, adic. pct = adic/venta (fracción)."""
        empty = {"series": [], "filas": [], "total": {}}
        if df is None or getattr(df, "empty", True):
            return empty
        d = df.copy()
        d["iso_week"] = _pd.to_numeric(d["iso_week"], errors="coerce")
        d["venta"]    = _pd.to_numeric(d["venta"],    errors="coerce").fillna(0.0)
        d["adic"]     = _pd.to_numeric(d["adic"],     errors="coerce").fillna(0.0)
        d = d.dropna(subset=["iso_week"])
        if d.empty:
            return empty
        semanas = sorted(int(w) for w in d["iso_week"].unique())
        series  = [str(w) for w in semanas]
        filas = []
        for g in sorted(d["garzon"].dropna().unique()):
            sub = d[d["garzon"] == g]
            anios = []; tv = ta = 0.0
            for w in semanas:
                wk = sub[sub["iso_week"] == w]
                v = float(wk["venta"].sum()) if not wk.empty else 0.0
                a = float(wk["adic"].sum())  if not wk.empty else 0.0
                tv += v; ta += a
                anios.append({"venta": int(round(v)), "pct": a / v} if v else None)
            filas.append({"nombre": _limpia_nombre(g), "anios": anios,
                          "total_venta": int(round(tv)),
                          "total_pct": (ta / tv) if tv else 0.0})
        # TOTAL GENERAL (anios siempre como dict; el generador no tolera None aquí)
        anios_t = []; gtv = gta = 0.0
        for w in semanas:
            wk = d[d["iso_week"] == w]
            v = float(wk["venta"].sum()); a = float(wk["adic"].sum())
            gtv += v; gta += a
            anios_t.append({"venta": int(round(v)), "pct": (a / v) if v else 0.0})
        total = {"nombre": "TOTAL GENERAL", "anios": anios_t,
                 "total_venta": int(round(gtv)),
                 "total_pct": (gta / gtv) if gtv else 0.0}
        return {"series": series, "filas": filas, "total": total}

    # ---- Sección 11: comportamiento por local (desde s11s / s11m crudos) ----
    def _comportamiento_block(df, period_col, sort_key, label_fn):
        """Cols esperadas: local, <period_col>, venta, adic.
        Devuelve {columnas, filas:[{local,valores,total}], total:{valores,total}}.
        % por celda = adic/venta; total por fila = Σadic/Σventa (no promedio de %)."""
        empty = {"columnas": [], "filas": [], "total": {}}
        if df is None or getattr(df, "empty", True):
            return empty
        d = df.copy()
        d["venta"] = _pd.to_numeric(d["venta"], errors="coerce").fillna(0.0)
        d["adic"]  = _pd.to_numeric(d["adic"],  errors="coerce").fillna(0.0)
        d[period_col] = d[period_col].astype(str)
        d["local"] = d["local"].apply(lambda x: "Pedro de Valdivia" if x == "Providencia" else x)
        periodos_raw = sorted(d[period_col].dropna().unique(), key=sort_key)
        if not periodos_raw:
            return empty
        columnas = [label_fn(p) for p in periodos_raw]
        raw2lab  = dict(zip(periodos_raw, columnas))
        filas = []
        for loc in d["local"].dropna().unique():
            sub = d[d["local"] == loc]
            valores = {}; sv = sa = 0.0
            for praw in periodos_raw:
                cell = sub[sub[period_col] == praw]
                v = float(cell["venta"].sum()); a = float(cell["adic"].sum())
                sv += v; sa += a
                valores[raw2lab[praw]] = (a / v) if v else None
            filas.append({"local": loc, "valores": valores,
                          "total": (sa / sv) if sv else None})
        # orden por % total descendente (None al fondo)
        filas.sort(key=lambda r: (r["total"] is not None, r["total"] or 0.0), reverse=True)
        # TOTAL GENERAL por columna (Σ sobre locales)
        valores_t = {}
        for praw in periodos_raw:
            cell = d[d[period_col] == praw]
            v = float(cell["venta"].sum()); a = float(cell["adic"].sum())
            valores_t[raw2lab[praw]] = (a / v) if v else None
        gv = float(d["venta"].sum()); ga = float(d["adic"].sum())
        total = {"valores": valores_t, "total": (ga / gv) if gv else None}
        return {"columnas": columnas, "filas": filas, "total": total}

    # ---- Gráficos 8 y 10 (se derivan de las tablas 9 y 11-semanal ya construidas) ----
    def _wrap_nombre(nombre, maxlen=14):
        """Parte un nombre largo en dos líneas, en el espacio más cercano al medio."""
        s = str(nombre or "")
        if len(s) <= maxlen or " " not in s:
            return s
        espacios = [i for i, ch in enumerate(s) if ch == " "]
        medio = len(s) / 2.0
        corte = min(espacios, key=lambda i: abs(i - medio))
        return s[:corte] + "\n" + s[corte + 1:]

    def _sec8_evol_block(sec9):
        """Sección 8 (gráfico): % adicionales por garzón y semana, desde la sección 9."""
        if not sec9 or not sec9.get("filas"):
            return {"series": [], "filas": []}
        series = sec9.get("series", [])
        filas = [{"nombre": _wrap_nombre(f.get("nombre", "")),
                  "valores": [(a["pct"] if a else None) for a in f.get("anios", [])]}
                 for f in sec9["filas"]]
        return {"series": series, "filas": filas}

    def _sec10_comp_block(sem11):
        """Sección 10 (gráfico): % adicionales por local y semana, desde la sección 11 semanal."""
        if not sem11 or not sem11.get("filas"):
            return {"series": [], "filas": []}
        cols = sem11.get("columnas", [])
        filas = [{"local": r.get("local", ""),
                  "valores": [r["valores"].get(c) for c in cols]}
                 for r in sem11["filas"]]
        return {"series": cols, "filas": filas}

    # Bloques base (tablas) que también alimentan a los gráficos
    _sec9_tab  = _sec9_anual_block(s9_raw)
    _sem11_tab = _comportamiento_block(
        s11s, "iso_week", sort_key=lambda p: int(p), label_fn=lambda p: str(int(p)))
    _mes11_tab = _comportamiento_block(
        s11m, "mes", sort_key=lambda p: str(p), label_fn=_lab_mes)

    ctx = {
        "local": local.upper(),
        "semana": f"{ini.strftime('%d-%m')} AL {fin.strftime('%d-%m')}",
        "ranking": ranking,
        "supervisor": (jef[0] or "").upper(),
        "jefe": (jef[1] or "").upper(),
        "subjefe": (jef[2] or "").upper(),
        "cantidad_garzones": ng,
        "ventas_totales_salon": _ventas_block(s1),
        "ventas_por_categoria": _ventas_block(s2),
        "ventas_subcategorias": _subcats_block(s3),
        "productos_estrategicos": _estrat_block(s4),
        "adicionales_por_garzon_semanal": _sec5_block(rows5_sem),
        "adicionales_por_garzon_mensual": _sec5_block(rows5),
        "adicionales_por_local": _adic_local_block(s6_raw),
        "estrategicos_por_local": _estrat_local_block(s7),
        "evolucion_por_garzon": _sec8_evol_block(_sec9_tab),
        "adicionales_por_garzon_anual": _sec9_tab,
        "comparativa_por_local": _sec10_comp_block(_sem11_tab),
        "comportamiento_semanal": _sem11_tab,
        "comportamiento_mensual": _mes11_tab,
    }
    return ctx


def _igb_safe(s):
    return str(s or "")



# ===== GENERADOR PDF 'INFORME B' (template Claude Code, replica visual fiel) =====
# -*- coding: utf-8 -*-

import io

from reportlab.lib.pagesizes import letter
from reportlab.lib import colors
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib.enums import TA_CENTER, TA_LEFT, TA_RIGHT
from reportlab.platypus import (
    SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, Image,
    PageBreak, KeepTogether,
)

# ---------------------------------------------------------------------------
#  PALETA Y CONSTANTES VISUALES  (ajusta aqui si quieres afinar la replica)
# ---------------------------------------------------------------------------
GRIS_HEADER   = colors.HexColor("#D0CECE")   # fila de titulos de columna / fila TOTAL
GRIS_BARRA    = colors.HexColor("#757171")   # barra oscura de sub-seccion (sec 3)
GRIS_BORDE    = colors.HexColor("#595959")   # lineas de la grilla
ROJO          = colors.HexColor("#FF0000")   # formato condicional (bajo rendimiento)
BLANCO        = colors.white
NEGRO         = colors.black

# Colores de las 4 series de los graficos (paleta Office por defecto)
SERIE_COLORES = ["#5B9BD5", "#ED7D31", "#A5A5A5", "#FFC000"]

FUENTE      = "Helvetica"
FUENTE_BOLD = "Helvetica-Bold"

# Tamanos de fuente por contexto
FS_TITULO   = 10
FS_SUBTIT   = 9
FS_SEMANA   = 6.5
FS_SECCION  = 7.5
FS_INFO     = 8
FS_CELDA    = 5.3    # tablas secciones 1-4, 6, 7, 9, 11
FS_HEADER   = 5      # titulos de columna
FS_CELDA_XS = 4.4    # tabla ancha seccion 5 (21 columnas)
FS_HEADER_XS = 4.1

GROSOR_BORDE = 0.4   # grosor de las lineas de grilla (pt)
PAD_CELDA    = 0.7   # padding vertical de las celdas de tabla

# Pagina
ANCHO_PAG, ALTO_PAG = letter            # 612 x 792 pt (Carta vertical)
MARGEN_X = 40
MARGEN_SUP = 26
MARGEN_INF = 20
ANCHO_UTIL = ANCHO_PAG - 2 * MARGEN_X   # 532 pt


# ---------------------------------------------------------------------------
#  FORMATEADORES (estilo chileno)
# ---------------------------------------------------------------------------
def _igb_fmt_miles(v):
    """9407 -> '9.407'. Si v es str, se devuelve tal cual."""
    if isinstance(v, str):
        return v
    if v is None:
        return ""
    return f"{int(round(v)):,}".replace(",", ".")


def _igb_fmt_monto(v, signo=True):
    """48931250 -> '$48.931.250'."""
    if isinstance(v, str):
        return v
    if v is None:
        return ""
    s = _igb_fmt_miles(v)
    return ("$" + s) if signo else s


def _igb_fmt_pct(v, dec=1):
    """0.826 -> '82,6%'.  Acepta fraccion (0..1) o string literal."""
    if isinstance(v, str):
        return v
    if v is None:
        return ""
    return f"{v * 100:.{dec}f}".replace(".", ",") + "%"


# ---------------------------------------------------------------------------
#  ESTILOS DE PARRAFO
# ---------------------------------------------------------------------------
def _igb__estilos():
    return {
        "titulo":  ParagraphStyle("titulo", fontName=FUENTE_BOLD, fontSize=FS_TITULO,
                                  alignment=TA_CENTER, leading=FS_TITULO + 2),
        "subtit":  ParagraphStyle("subtit", fontName=FUENTE_BOLD, fontSize=FS_SUBTIT,
                                  alignment=TA_CENTER, leading=FS_SUBTIT + 2),
        "semana":  ParagraphStyle("semana", fontName=FUENTE_BOLD, fontSize=FS_SEMANA,
                                  alignment=TA_CENTER, leading=FS_SEMANA + 2),
        "seccion": ParagraphStyle("seccion", fontName=FUENTE_BOLD, fontSize=FS_SECCION,
                                  alignment=TA_LEFT, leading=FS_SECCION + 1.5,
                                  spaceBefore=4, spaceAfter=1.5, textColor=colors.HexColor("#262626")),
        "rank_lbl": ParagraphStyle("rank_lbl", fontName=FUENTE_BOLD, fontSize=12,
                                   alignment=TA_CENTER, leading=14),
        "rank_val": ParagraphStyle("rank_val", fontName=FUENTE_BOLD, fontSize=13,
                                   alignment=TA_CENTER, leading=15),
        "info_lbl": ParagraphStyle("info_lbl", fontName=FUENTE_BOLD, fontSize=FS_INFO,
                                   alignment=TA_RIGHT, leading=FS_INFO + 2),
        "info_val": ParagraphStyle("info_val", fontName=FUENTE_BOLD, fontSize=FS_INFO,
                                   alignment=TA_LEFT, leading=FS_INFO + 2),
        "pg_titulo": ParagraphStyle("pg_titulo", fontName=FUENTE_BOLD, fontSize=10.5,
                                    alignment=TA_CENTER, leading=12, spaceAfter=3),
        "barra":   ParagraphStyle("barra", fontName=FUENTE_BOLD, fontSize=FS_HEADER,
                                  alignment=TA_CENTER, leading=FS_HEADER + 1.5, textColor=BLANCO),
        # encabezados de columna
        "th":      ParagraphStyle("th", fontName=FUENTE_BOLD, fontSize=FS_HEADER,
                                  alignment=TA_CENTER, leading=FS_HEADER + 1),
        "th_xs":   ParagraphStyle("th_xs", fontName=FUENTE_BOLD, fontSize=FS_HEADER_XS,
                                  alignment=TA_CENTER, leading=FS_HEADER_XS + 1),
        # nombre de item (col izquierda de cada tabla)
        "item":    ParagraphStyle("item", fontName=FUENTE_BOLD, fontSize=FS_CELDA,
                                  alignment=TA_CENTER, leading=FS_CELDA + 0.6),
        "item_l":  ParagraphStyle("item_l", fontName=FUENTE, fontSize=FS_CELDA,
                                  alignment=TA_CENTER, leading=FS_CELDA + 0.6),
        "item_xs": ParagraphStyle("item_xs", fontName=FUENTE, fontSize=FS_CELDA_XS,
                                  alignment=TA_CENTER, leading=FS_CELDA_XS + 0.6),
    }


S = _igb__estilos()


def _igb_P(texto, estilo):
    return Paragraph(str(texto), S[estilo])


# ===========================================================================
#  PAGINA 1  ----------------------------------------------------------------
# ===========================================================================
def _igb__cabecera(ctx, logo_path):
    """Logo (izq) + bloque de titulo (centro) + caja RANKING (der)."""
    # --- caja ranking ---
    ranking = Table(
        [[_igb_P("RANKING", "rank_lbl")], [_igb_P(ctx.get("ranking", ""), "rank_val")]],
        colWidths=[110], rowHeights=[26, 26],
    )
    ranking.setStyle(TableStyle([
        ("BOX", (0, 0), (-1, -1), 0.8, NEGRO),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("TOPPADDING", (0, 0), (-1, -1), 2),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 2),
    ]))

    # --- bloque central de titulo ---
    centro = [
        _igb_P("INFORME DE CONTROL DE VENTAS SALÓN", "titulo"),
        _igb_P("LOCAL&nbsp;&nbsp;-&nbsp;&nbsp;" + str(ctx.get("local", "")), "subtit"),
        _igb_P("SEMANA " + str(ctx.get("semana", "")), "semana"),
    ]

    # --- logo ---
    try:
        logo = Image(logo_path, width=58, height=58)
    except Exception:
        logo = Spacer(58, 58)

    cab = Table([[logo, centro, ranking]],
                colWidths=[120, ANCHO_UTIL - 120 - 120, 120])
    cab.setStyle(TableStyle([
        ("VALIGN", (0, 0), (0, 0), "MIDDLE"),
        ("VALIGN", (1, 0), (1, 0), "MIDDLE"),
        ("VALIGN", (2, 0), (2, 0), "MIDDLE"),
        ("ALIGN", (0, 0), (0, 0), "LEFT"),
        ("ALIGN", (2, 0), (2, 0), "RIGHT"),
        ("LEFTPADDING", (0, 0), (-1, -1), 0),
        ("RIGHTPADDING", (0, 0), (-1, -1), 0),
    ]))
    return cab


def _igb__bloque_info(ctx):
    filas = [
        [_igb_P("SUPERVISOR SERVICIO:", "info_lbl"), _igb_P(ctx.get("supervisor", ""), "info_val")],
        [_igb_P("JEFE SERVICIO:", "info_lbl"), _igb_P(ctx.get("jefe", ""), "info_val")],
        [_igb_P("SUB JEFE SERVICIO:", "info_lbl"), _igb_P(ctx.get("subjefe", ""), "info_val")],
        [_igb_P("CANTIDAD GARZONES:", "info_lbl"), _igb_P(str(ctx.get("cantidad_garzones", "")), "info_val")],
    ]
    t = Table(filas, colWidths=[160, ANCHO_UTIL - 160])
    t.setStyle(TableStyle([
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("LEFTPADDING", (0, 0), (0, -1), 40),   # indenta las etiquetas hacia la derecha
        ("LEFTPADDING", (1, 0), (1, -1), 14),
        ("TOPPADDING", (0, 0), (-1, -1), 0.5),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 0.5),
    ]))
    return t


# ---- Secciones 1 y 2 : ventas (10 columnas logicas, $ ACUMULADO en formato contable) ----
# Columnas fisicas (11):
#   0 ITEM | 1 "$" | 2 acum | 3 q | 4 % | 5 diario | 6 q | 7 % | 8 semanal | 9 q | 10 %
_W_VENTAS = [104, 9, 63, 42, 33, 67, 42, 31, 67, 42, 32]   # suma = 532

def _igb__fila_ventas(f, total=False):
    est_item = "item"
    return [
        _igb_P(f["item"], est_item),
        "", _igb_fmt_monto(f.get("acum")),
        _igb_fmt_miles(f.get("acum_q")),
        _igb_fmt_pct(f.get("acum_pct")),
        _igb_fmt_monto(f.get("diario")),
        _igb_fmt_miles(f.get("diario_q")),
        _igb_fmt_pct(f.get("diario_pct")),
        _igb_fmt_monto(f.get("semanal")),
        _igb_fmt_miles(f.get("semanal_q")),
        _igb_fmt_pct(f.get("semanal_pct")),
    ]


def _igb__tabla_ventas(seccion, header_q="Q PRODUCTOS"):
    filas = seccion["filas"]
    total = seccion.get("total")

    head = [
        _igb_P("ITEM", "th"),
        _igb_P("$ ACUMULADO", "th"), "",
        _igb_P(header_q, "th"),
        _igb_P("%", "th"),
        _igb_P("$ DIARIO", "th"),
        _igb_P(header_q, "th"),
        _igb_P("%", "th"),
        _igb_P("$ SEMANAL", "th"),
        _igb_P(header_q, "th"),
        _igb_P("%", "th"),
    ]
    data = [head]
    for f in filas:
        data.append(_igb__fila_ventas(f))
    n_total = None
    if total:
        n_total = len(data)
        data.append(_igb__fila_ventas(total, total=True))

    t = Table(data, colWidths=_W_VENTAS)
    estilo = [
        ("GRID", (0, 0), (-1, -1), GROSOR_BORDE, GRIS_BORDE),
        ("SPAN", (1, 0), (2, 0)),                       # "$ ACUMULADO" sobre $ + numero
        ("BACKGROUND", (0, 0), (-1, 0), GRIS_HEADER),   # fila de titulos
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("FONTNAME", (0, 1), (-1, -1), FUENTE),
        ("FONTSIZE", (0, 1), (-1, -1), FS_CELDA),
        ("LEADING", (0, 0), (-1, -1), FS_CELDA + 0.6),
        # todo el contenido centrado (H + V)
        ("ALIGN", (0, 0), (-1, -1), "CENTER"),
        # columnas % en negrita (diario y semanal)
        ("FONTNAME", (7, 1), (7, -1), FUENTE_BOLD),
        ("FONTNAME", (10, 1), (10, -1), FUENTE_BOLD),
        ("TOPPADDING", (0, 0), (-1, -1), PAD_CELDA),
        ("BOTTOMPADDING", (0, 0), (-1, -1), PAD_CELDA),
        ("LEFTPADDING", (0, 0), (-1, -1), 2),
        ("RIGHTPADDING", (0, 0), (-1, -1), 2),
    ]
    if n_total is not None:
        estilo += [
            ("BACKGROUND", (0, n_total), (-1, n_total), GRIS_HEADER),
            ("FONTNAME", (0, n_total), (-1, n_total), FUENTE_BOLD),
        ]
    t.setStyle(TableStyle(estilo))
    return t


# ---- Seccion 3 : sub-tablas con barra oscura (Q PROMEDIO X GARZON) ----
def _igb__barra_subseccion(titulo, ancho=104):
    b = Table([[_igb_P(titulo, "barra")]], colWidths=[ancho], rowHeights=[8.5])
    b.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, -1), GRIS_BARRA),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("LEFTPADDING", (0, 0), (-1, -1), 2),
        ("RIGHTPADDING", (0, 0), (-1, -1), 2),
        ("TOPPADDING", (0, 0), (-1, -1), 0.5),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 0.5),
    ]))
    return b


def _igb__subtabla_categoria(sub):
    """Una sub-tabla de la seccion 3 (barra + tabla con 'Q PROMEDIO X GARZON')."""
    barra = _igb__barra_subseccion(sub["titulo"], ancho=_W_VENTAS[0])
    tabla = _igb__tabla_ventas(sub, header_q="Q PROMEDIO X GARZON")
    return KeepTogether([barra, tabla, Spacer(1, 3)])


# ===========================================================================
#  TABLA GENERICA  (secciones 6, 7, 9, 11)
# ===========================================================================
def _igb__tabla_generica(headers, filas, col_widths, aligns=None, fs=FS_CELDA,
                    th_estilo="th", total_idx=None, item_estilo="item",
                    rojos=None, rojo_cols=None, extra_estilo=None,
                    spans=None, header_rows=1):
    """
    headers     : lista de filas-de-encabezado (cada una lista de textos/Paragraph)
    filas       : lista de listas (celdas ya formateadas como str)
    col_widths  : lista de anchos
    aligns      : lista de alineaciones por columna ('LEFT'/'CENTER'/'RIGHT')
    total_idx   : indice (en `data`) de la fila TOTAL para resaltarla en gris
    rojos       : lista de (row_data_idx, col) a pintar de rojo  -> formato condicional
    """
    ncols = len(col_widths)
    data = []
    for h in headers:
        data.append(h)
    base = header_rows
    for f in filas:
        data.append(list(f))

    t = Table(data, colWidths=col_widths)
    estilo = [
        ("GRID", (0, 0), (-1, -1), GROSOR_BORDE, GRIS_BORDE),
        ("BACKGROUND", (0, 0), (-1, header_rows - 1), GRIS_HEADER),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("FONTNAME", (0, base), (-1, -1), FUENTE),
        ("FONTSIZE", (0, base), (-1, -1), fs),
        ("LEADING", (0, 0), (-1, -1), fs + 0.6),
        ("TOPPADDING", (0, 0), (-1, -1), PAD_CELDA),
        ("BOTTOMPADDING", (0, 0), (-1, -1), PAD_CELDA),
        ("LEFTPADDING", (0, 0), (-1, -1), 2),
        ("RIGHTPADDING", (0, 0), (-1, -1), 2),
    ]
    if aligns:
        for c, a in enumerate(aligns):
            estilo.append(("ALIGN", (c, base), (c, -1), a))
    if total_idx is not None:
        estilo += [
            ("BACKGROUND", (0, total_idx), (-1, total_idx), GRIS_HEADER),
            ("FONTNAME", (0, total_idx), (-1, total_idx), FUENTE_BOLD),
        ]
    if spans:
        for (c0, r0, c1, r1) in spans:
            estilo.append(("SPAN", (c0, r0), (c1, r1)))
    if rojos:
        for (r, c) in rojos:
            estilo += [
                ("BACKGROUND", (c, base + r), (c, base + r), ROJO),
                ("TEXTCOLOR", (c, base + r), (c, base + r), BLANCO),
                ("FONTNAME", (c, base + r), (c, base + r), FUENTE_BOLD),
            ]
    if extra_estilo:
        estilo += extra_estilo
    t.setStyle(TableStyle(estilo))
    return t


